/// A Z3 numeral that already lies in `word`. Anything else is wider than that word.
fn numeral_fits_word(value: &Int<'_>, word: (u32, bool)) -> bool {
    let (bits, signed) = word;
    if bits == 0 || bits > 64 {
        return true;
    }
    let text = value.to_string();
    let Some(parsed) = (if let Some(inner) = text.strip_prefix("(- ") {
        inner
            .strip_suffix(')')
            .and_then(|inner| inner.trim().parse::<i128>().ok())
            .map(|magnitude| -magnitude)
    } else {
        text.trim().parse::<i128>().ok()
    }) else {
        return false;
    };
    if signed {
        let min = -1i128 << (bits - 1);
        let max = (1i128 << (bits - 1)) - 1;
        parsed >= min && parsed <= max
    } else {
        parsed >= 0 && parsed < (1i128 << bits)
    }
}

enum FieldBytes {
    Raw { nbytes: u32 },
    Int { bits: u32, signed: bool },
}

fn rust_type_name(ty: &syn::Type) -> Option<String> {
    match ty {
        syn::Type::Reference(reference) => rust_type_name(&reference.elem),
        other => type_ident(other),
    }
}

fn is_buffer_len_assert(stmt: &Stmt, buffer: &str) -> bool {
    let text = match stmt {
        Stmt::Macro(mac) => format!("{}!({})", path_to_string(&mac.mac.path), mac.mac.tokens),
        Stmt::Expr(Expr::Macro(mac), _) => {
            format!("{}!({})", path_to_string(&mac.mac.path), mac.mac.tokens)
        }
        _ => return false,
    };
    let compact = text.replace(' ', "");
    compact.contains("assert_eq") && compact.contains(&format!("{buffer}.len()"))
}

fn primitives_types_source() -> Option<String> {
    if !crate::parser::spec_expr::consensus_workspace_present() {
        return None;
    }
    let path =
        std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../blvm-primitives/src/types.rs");
    std::fs::read_to_string(path).ok()
}

fn struct_field_type(src: &str, struct_name: &str, field: &str) -> Option<String> {
    let marker = format!("struct {struct_name}");
    let start = src.find(&marker)?;
    let rest = &src[start..];
    let brace = rest.find('{')?;
    let mut depth = 0i32;
    let mut end = None;
    for (index, byte) in rest[brace..].bytes().enumerate() {
        if byte == b'{' {
            depth += 1;
        } else if byte == b'}' {
            depth -= 1;
            if depth == 0 {
                end = Some(brace + index);
                break;
            }
        }
    }
    let body = &rest[brace..end?];
    let needle = format!("{field}:");
    for line in body.lines() {
        let line = line.trim().trim_start_matches("pub ");
        let Some(after) = line.strip_prefix(&needle) else {
            continue;
        };
        return Some(after.split(',').next()?.trim().to_string());
    }
    None
}

fn alias_target(src: &str, name: &str) -> Option<String> {
    let key = format!("type {name} =");
    let rest = src.get(src.find(&key)? + key.len()..)?;
    Some(rest.split(';').next()?.trim().to_string())
}

fn byte_array_len(ty: &str) -> Option<u32> {
    let rest = ty.strip_prefix("[u8;")?.trim();
    let rest = rest.strip_suffix(']')?.trim();
    rest.parse().ok()
}

fn word_of_named_type(src: &str, name: &str) -> Option<(u32, bool)> {
    let resolved = alias_target(src, name).unwrap_or_else(|| name.to_string());
    let ty: syn::Type = syn::parse_str(&resolved).ok()?;
    int_cast_width(&ty)
}

struct CompactTarget {
    bits: String,
    exp_shift: i64,
    exp_bits: u32,
    mask: i64,
    lo: i64,
    hi: i64,
    bias: i64,
    byte_limit: i64,
}

fn parse_compact_target(block: &Block) -> Option<CompactTarget> {
    let mut exponent_name = None;
    let mut mantissa_name = None;
    let mut bits = None;
    let mut exp_shift = None;
    let mut exp_bits = None;
    let mut mask = None;
    let mut lo = None;
    let mut hi = None;
    let mut bias = None;
    let mut byte_mul = None;
    let mut bit_limit = None;
    for stmt in &block.stmts {
        if let Stmt::Local(local) = stmt {
            let name = local_name(&local.pat)?;
            let init = &local.init.as_ref()?.expr;
            if let Some((param, shift, bits_n)) = cast_shift(init) {
                exponent_name = Some(name);
                bits = Some(param);
                exp_shift = Some(shift);
                exp_bits = Some(bits_n);
                continue;
            }
            if let Some((param, mask_n)) = bitand_mask(init) {
                if bits.as_deref() != Some(param.as_str()) {
                    return None;
                }
                mantissa_name = Some(name);
                mask = Some(mask_n);
            }
        }
    }
    let exponent = exponent_name?;
    let mantissa = mantissa_name?;
    for stmt in &block.stmts {
        let Stmt::Expr(Expr::If(if_expr), _) = stmt else {
            continue;
        };
        if let Some((range_lo, range_hi)) = rejected_range(if_expr, &exponent) {
            lo = Some(range_lo);
            hi = Some(range_hi);
        }
        if zero_mantissa_guard(if_expr, &mantissa) && bias.is_none() {
            continue;
        }
        if let Some((split, mul, limit)) = shift_if(if_expr, &exponent) {
            bias = Some(split);
            byte_mul = Some(mul);
            bit_limit = Some(limit);
        }
    }
    let byte_mul = byte_mul?;
    let bit_limit = bit_limit?;
    if byte_mul <= 0 || bit_limit % byte_mul != 0 {
        return None;
    }
    let byte_limit = bit_limit / byte_mul;
    if !(2..=32).contains(&byte_limit) {
        return None;
    }
    let mask = mask?;
    if mask <= 0 || !((mask as u64).wrapping_add(1)).is_power_of_two() {
        return None;
    }
    let lo = lo?;
    let hi = hi?;
    Some(CompactTarget {
        bits: bits?,
        exp_shift: exp_shift?,
        exp_bits: exp_bits?,
        mask,
        lo,
        hi,
        bias: bias?,
        byte_limit,
    })
}

pub(crate) struct CompressTarget {
    pub(crate) param: String,
    pub(crate) zero_bits: i64,
    pub(crate) byte: i64,
    pub(crate) base: i64,
    pub(crate) small_at: i64,
    pub(crate) sign_mask: i64,
    pub(crate) sign_shift: i64,
    pub(crate) mant_mask: i64,
    pub(crate) exp_shift: i64,
    pub(crate) size_limit: i64,
}

/// Whole-body clause for `compress_target`. Powers are a chain of lets so the
/// expression stays shallow. The sign mask and the exponent shift are the
/// census edits; every other literal is a check those edits leave in place.
pub(crate) fn compress_identity_clause(p: &CompressTarget) -> String {
    let mut lets = String::from(" let p0 = 1;");
    for k in 1..256 {
        lets.push_str(&format!(" let p{k} = (p{} * 2);", k - 1));
    }
    lets.push_str(" let h0 = 1;");
    let max_k = 32 - p.small_at;
    for k in 1..=max_k {
        lets.push_str(&format!(" let h{k} = (h{} * {});", k - 1, p.base));
    }
    let param = &p.param;
    let mut prev = "0".to_string();
    for k in 0..256 {
        lets.push_str(&format!(
            " let b{k} = (if {param} >= p{k} {{ {k} }} else {{ {prev} }});"
        ));
        prev = format!("b{k}");
    }
    lets.push_str(&format!(
        " let n_size = (({prev} + {byte}) / {byte}); let low = ({param} % p64);",
        byte = p.byte
    ));
    let mut prev_c = "0".to_string();
    for size in (p.small_at + 1..=32).rev() {
        let k = size - p.small_at;
        lets.push_str(&format!(
            " let w{size} = (if n_size == {size} {{ (({param} / h{k}) % p64) }} else {{ {prev_c} }});"
        ));
        prev_c = format!("w{size}");
    }
    for size in (1..=p.small_at).rev() {
        let k = p.small_at - size;
        lets.push_str(&format!(
            " let w{size} = (if n_size == {size} {{ (low * h{k}) }} else {{ {prev_c} }});"
        ));
        prev_c = format!("w{size}");
    }
    lets.push_str(&format!(" let c = {prev_c};"));
    let mut prev_c = "c".to_string();
    let mut prev_s = "n_size".to_string();
    let steps = (64 + p.sign_shift - 1) / p.sign_shift;
    for step in 0..steps {
        let set = format!("(({prev_c} & {mask}) != 0)", mask = p.sign_mask);
        lets.push_str(&format!(
            " let c{step} = (if {set} {{ ({prev_c} / {base}) }} else {{ {prev_c} }}); let s{step} = (if {set} {{ ({prev_s} + 1) }} else {{ {prev_s} }});",
            base = p.base
        ));
        prev_c = format!("c{step}");
        prev_s = format!("s{step}");
    }
    let mant_mod = p.mant_mask + 1;
    format!(
        "{{ {lets} let m = ({prev_c} % {mant_mod}); result_is_err == (if {param} == 0 {{ 0 }} else if {prev_s} > {limit} {{ 1 }} else {{ 0 }}) && result == (if {param} == 0 {{ {zero} }} else if {prev_s} > {limit} {{ 0 }} else {{ ({prev_s} << {shift}) | m }}) }}",
        limit = p.size_limit,
        zero = p.zero_bits,
        shift = p.exp_shift
    )
}

fn compress_clause_params(block: &Block) -> Option<CompressTarget> {
    let Stmt::Local(first) = block.stmts.first()? else {
        return None;
    };
    if local_name(&first.pat).as_deref() != Some("p0") {
        return None;
    }
    let Stmt::Expr(tail, None) = block.stmts.last()? else {
        return None;
    };
    if !expr_mentions(tail, "result_is_err") {
        return None;
    }
    let mut bits = ClauseBits::default();
    bits.walk_block(block);
    let byte = bits.byte?;
    let base = bits.base?;
    if byte <= 0 || byte >= 62 || base != (1i64 << byte) {
        return None;
    }
    let mant_mod = bits.mant_mod?;
    if mant_mod <= 1 || !(mant_mod as u64).is_power_of_two() {
        return None;
    }
    let exp_shift = bits.exp_shift?;
    if !(0..64).contains(&exp_shift) {
        return None;
    }
    let small_at = bits.small_at?;
    Some(CompressTarget {
        param: bits.param?,
        zero_bits: bits.zero_bits?,
        byte,
        base,
        small_at,
        sign_mask: bits.sign_mask?,
        sign_shift: byte,
        mant_mask: mant_mod - 1,
        exp_shift,
        size_limit: bits.size_limit?,
    })
}

#[derive(Default)]
struct ClauseBits {
    sign_mask: Option<i64>,
    byte: Option<i64>,
    base: Option<i64>,
    mant_mod: Option<i64>,
    exp_shift: Option<i64>,
    size_limit: Option<i64>,
    zero_bits: Option<i64>,
    param: Option<String>,
    small_at: Option<i64>,
}

impl ClauseBits {
    fn walk_block(&mut self, block: &Block) {
        for stmt in &block.stmts {
            match stmt {
                Stmt::Local(local) => {
                    if let Some(init) = &local.init {
                        self.walk(&init.expr);
                    }
                }
                Stmt::Expr(expr, _) => self.walk(expr),
                Stmt::Macro(_) | Stmt::Item(_) => {}
            }
        }
    }

    fn walk(&mut self, expr: &Expr) {
        match expr {
            Expr::Binary(bin) => {
                self.note_bin(bin);
                self.walk(&bin.left);
                self.walk(&bin.right);
            }
            Expr::If(iff) => {
                self.note_if(iff);
                self.walk(&iff.cond);
                self.walk_block(&iff.then_branch);
                if let Some((_, els)) = &iff.else_branch {
                    self.walk(els);
                }
            }
            Expr::Block(inner) => self.walk_block(&inner.block),
            Expr::Paren(paren) => self.walk(&paren.expr),
            Expr::Reference(reference) => self.walk(&reference.expr),
            Expr::Cast(cast) => self.walk(&cast.expr),
            Expr::Unary(unary) => self.walk(&unary.expr),
            _ => {}
        }
    }

    fn note_bin(&mut self, bin: &syn::ExprBinary) {
        if matches!(bin.op, syn::BinOp::BitAnd(_)) {
            if let Some(lit) = extract_int_literal(peel_refs(&bin.right)) {
                self.sign_mask = Some(lit);
            }
        }
        if matches!(bin.op, syn::BinOp::Div(_)) {
            if let Expr::Binary(add) = peel_refs(&bin.left) {
                if matches!(add.op, syn::BinOp::Add(_)) {
                    let right = extract_int_literal(peel_refs(&bin.right));
                    let added = extract_int_literal(peel_refs(&add.right));
                    if right.is_some() && right == added {
                        self.byte = right;
                    }
                }
            }
        }
        if matches!(bin.op, syn::BinOp::Mul(_)) {
            if let Some(lit) = extract_int_literal(peel_refs(&bin.right)) {
                if lit != 2 {
                    self.base = Some(lit);
                }
            }
        }
        if matches!(bin.op, syn::BinOp::Rem(_)) {
            self.mant_mod = extract_int_literal(peel_refs(&bin.right)).or(self.mant_mod);
        }
        if matches!(bin.op, syn::BinOp::Shl(_)) {
            self.exp_shift = extract_int_literal(peel_refs(&bin.right)).or(self.exp_shift);
        }
        if matches!(bin.op, syn::BinOp::Gt(_)) {
            self.size_limit = extract_int_literal(peel_refs(&bin.right)).or(self.size_limit);
        }
    }

    fn note_if(&mut self, iff: &syn::ExprIf) {
        let Expr::Binary(eq) = peel_refs(&iff.cond) else {
            return;
        };
        if matches!(eq.op, syn::BinOp::Eq(_))
            && extract_int_literal(peel_refs(&eq.right)) == Some(0)
        {
            if let Expr::Path(path) = peel_refs(&eq.left) {
                self.param = Some(path_to_string(&path.path));
            }
            if let Some(lit) = block_first_lit(&iff.then_branch) {
                if lit != 0 {
                    self.zero_bits = Some(lit);
                }
            }
        }
        if matches!(eq.op, syn::BinOp::Eq(_)) {
            if let Some(size) = extract_int_literal(peel_refs(&eq.right)) {
                if path_is(&eq.left, "n_size") && block_has_mul(&iff.then_branch) {
                    self.small_at = Some(self.small_at.map_or(size, |cur| cur.max(size)));
                }
            }
        }
    }
}

fn expr_mentions(expr: &Expr, name: &str) -> bool {
    match expr {
        Expr::Path(path) => path_to_string(&path.path) == name,
        Expr::Binary(bin) => expr_mentions(&bin.left, name) || expr_mentions(&bin.right, name),
        Expr::Unary(unary) => expr_mentions(&unary.expr, name),
        Expr::Paren(paren) => expr_mentions(&paren.expr, name),
        Expr::Reference(reference) => expr_mentions(&reference.expr, name),
        Expr::Block(block) => block.block.stmts.iter().any(|stmt| match stmt {
            Stmt::Expr(expr, _) => expr_mentions(expr, name),
            Stmt::Local(local) => local
                .init
                .as_ref()
                .is_some_and(|init| expr_mentions(&init.expr, name)),
            _ => false,
        }),
        Expr::If(iff) => {
            expr_mentions(&iff.cond, name)
                || iff.then_branch.stmts.iter().any(|stmt| match stmt {
                    Stmt::Expr(expr, _) => expr_mentions(expr, name),
                    _ => false,
                })
                || iff
                    .else_branch
                    .as_ref()
                    .is_some_and(|(_, els)| expr_mentions(els, name))
        }
        _ => false,
    }
}

fn block_first_lit(block: &Block) -> Option<i64> {
    for stmt in &block.stmts {
        let Stmt::Expr(expr, _) = stmt else {
            continue;
        };
        if let Some(lit) = extract_int_literal(peel_refs(expr)) {
            return Some(lit);
        }
    }
    None
}

fn block_has_mul(block: &Block) -> bool {
    fn expr_mul(expr: &Expr) -> bool {
        match expr {
            Expr::Binary(bin) => {
                matches!(bin.op, syn::BinOp::Mul(_)) || expr_mul(&bin.left) || expr_mul(&bin.right)
            }
            Expr::Paren(paren) => expr_mul(&paren.expr),
            Expr::Block(block) => block_has_mul(&block.block),
            _ => false,
        }
    }
    block.stmts.iter().any(|stmt| match stmt {
        Stmt::Expr(expr, _) => expr_mul(expr),
        _ => false,
    })
}

fn parse_compress_target(block: &Block) -> Option<CompressTarget> {
    let mut scan = CompressScan::default();
    scan.walk_block(block);
    if !scan.saw_high {
        return None;
    }
    let byte = scan.byte?;
    if byte <= 0 || byte >= 62 || scan.sign_shift != Some(byte) {
        return None;
    }
    if scan.mul_byte != Some(byte) || scan.shr_byte != Some(byte) {
        return None;
    }
    let small_at = scan.small_at?;
    if small_at <= 0
        || small_at > 32
        || scan.sub_lit != Some(small_at)
        || scan.right_lit != Some(small_at)
    {
        return None;
    }
    let mant_mask = scan.mant_mask?;
    if mant_mask <= 0 || !((mant_mask as u64).wrapping_add(1)).is_power_of_two() {
        return None;
    }
    let exp_shift = scan.exp_shift?;
    if !(0..64).contains(&exp_shift) {
        return None;
    }
    let sign_mask = scan.sign_mask?;
    if sign_mask < 0 || (sign_mask > 0 && !(sign_mask as u64).is_power_of_two()) {
        return None;
    }
    let base = 1i64 << byte;
    Some(CompressTarget {
        param: scan.param?,
        zero_bits: scan.zero_bits?,
        byte,
        base,
        small_at,
        sign_mask,
        sign_shift: byte,
        mant_mask,
        exp_shift,
        size_limit: scan.size_limit?,
    })
}

#[derive(Default)]
struct CompressScan {
    param: Option<String>,
    zero_bits: Option<i64>,
    byte: Option<i64>,
    mul_byte: Option<i64>,
    shr_byte: Option<i64>,
    small_at: Option<i64>,
    sub_lit: Option<i64>,
    right_lit: Option<i64>,
    sign_mask: Option<i64>,
    sign_shift: Option<i64>,
    mant_mask: Option<i64>,
    exp_shift: Option<i64>,
    size_limit: Option<i64>,
    saw_high: bool,
}

impl CompressScan {
    fn walk_block(&mut self, block: &Block) {
        for stmt in &block.stmts {
            self.walk_stmt(stmt);
        }
    }

    fn walk_stmt(&mut self, stmt: &Stmt) {
        match stmt {
            Stmt::Local(local) => {
                if let Some(init) = &local.init {
                    self.walk_expr(&init.expr);
                }
            }
            Stmt::Expr(expr, _) => self.walk_expr(expr),
            Stmt::Macro(_) | Stmt::Item(_) => {}
        }
    }

    fn walk_expr(&mut self, expr: &Expr) {
        match expr {
            Expr::If(iff) => {
                self.note_zero_if(iff);
                self.note_small_if(iff);
                self.note_limit_if(iff);
                self.walk_expr(&iff.cond);
                self.walk_block(&iff.then_branch);
                if let Some((_, else_branch)) = &iff.else_branch {
                    self.walk_expr(else_branch);
                }
            }
            Expr::While(wh) => {
                self.note_while(wh);
                self.walk_expr(&wh.cond);
                self.walk_block(&wh.body);
            }
            Expr::Binary(bin) => {
                self.note_or_shift(bin);
                self.note_sub(bin);
                self.note_mul(bin);
                self.walk_expr(&bin.left);
                self.walk_expr(&bin.right);
            }
            Expr::MethodCall(call) => {
                if call.method == "highest_set_bit" {
                    self.saw_high = true;
                }
                if call.method == "div_ceil" {
                    if let Some(arg) = call.args.first() {
                        self.byte = extract_int_literal(peel_refs(arg)).or(self.byte);
                    }
                }
                self.walk_expr(&call.receiver);
                for arg in &call.args {
                    self.walk_expr(arg);
                }
            }
            Expr::Cast(cast) => {
                self.note_mant_cast(&cast.expr);
                self.walk_expr(&cast.expr);
            }
            Expr::Call(call) => {
                self.walk_expr(&call.func);
                for arg in &call.args {
                    self.walk_expr(arg);
                }
            }
            Expr::Return(ret) => {
                if let Some(inner) = &ret.expr {
                    self.walk_expr(inner);
                }
            }
            Expr::Block(block) => self.walk_block(&block.block),
            Expr::Paren(paren) => self.walk_expr(&paren.expr),
            Expr::Reference(reference) => self.walk_expr(&reference.expr),
            Expr::Unary(unary) => self.walk_expr(&unary.expr),
            Expr::Try(try_expr) => self.walk_expr(&try_expr.expr),
            Expr::Assign(assign) => {
                self.walk_expr(&assign.left);
                self.walk_expr(&assign.right);
            }
            _ => {}
        }
    }

    fn note_zero_if(&mut self, iff: &syn::ExprIf) {
        let Expr::MethodCall(call) = peel_refs(&iff.cond) else {
            return;
        };
        if call.method != "is_zero" {
            return;
        }
        let Expr::Path(path) = peel_refs(&call.receiver) else {
            return;
        };
        let Some(bits) = ok_literal_in_block(&iff.then_branch) else {
            return;
        };
        self.param = Some(path_to_string(&path.path));
        self.zero_bits = Some(bits);
    }

    fn note_small_if(&mut self, iff: &syn::ExprIf) {
        let Expr::Binary(bin) = peel_refs(&iff.cond) else {
            return;
        };
        if !matches!(bin.op, syn::BinOp::Le(_)) {
            return;
        }
        let Some(lit) = extract_int_literal(peel_refs(&bin.right)) else {
            return;
        };
        self.small_at = Some(lit);
    }

    fn note_limit_if(&mut self, iff: &syn::ExprIf) {
        let Expr::Binary(bin) = peel_refs(&iff.cond) else {
            return;
        };
        if !matches!(bin.op, syn::BinOp::Gt(_)) {
            return;
        }
        if !block_returns_err(&iff.then_branch) {
            return;
        }
        let Some(lit) = extract_int_literal(peel_refs(&bin.right)) else {
            return;
        };
        self.size_limit = Some(lit);
    }

    fn note_while(&mut self, wh: &syn::ExprWhile) {
        let Expr::Binary(ne) = peel_refs(&wh.cond) else {
            return;
        };
        if !matches!(ne.op, syn::BinOp::Ne(_)) {
            return;
        }
        let Expr::Binary(and) = peel_refs(&ne.left) else {
            return;
        };
        if !matches!(and.op, syn::BinOp::BitAnd(_)) {
            return;
        }
        let Some(mask) = extract_int_literal(peel_refs(&and.right)) else {
            return;
        };
        self.sign_mask = Some(mask);
        for stmt in &wh.body.stmts {
            let Stmt::Expr(expr, _) = stmt else {
                continue;
            };
            let Expr::Binary(bin) = peel_refs(expr) else {
                continue;
            };
            if matches!(bin.op, syn::BinOp::ShrAssign(_)) {
                if let Some(step) = extract_int_literal(peel_refs(&bin.right)) {
                    self.sign_shift = Some(step);
                }
            }
        }
    }

    fn note_or_shift(&mut self, bin: &syn::ExprBinary) {
        if !matches!(bin.op, syn::BinOp::BitOr(_)) {
            return;
        }
        let Expr::Binary(shl) = peel_refs(&bin.left) else {
            return;
        };
        if !matches!(shl.op, syn::BinOp::Shl(_)) {
            return;
        }
        if let Some(shift) = extract_int_literal(peel_refs(&shl.right)) {
            self.exp_shift = Some(shift);
        }
    }

    fn note_mul(&mut self, bin: &syn::ExprBinary) {
        if !matches!(bin.op, syn::BinOp::Mul(_)) {
            return;
        }
        if extract_int_literal(peel_refs(&bin.left)).is_some() {
            self.mul_byte = extract_int_literal(peel_refs(&bin.left));
        } else if extract_int_literal(peel_refs(&bin.right)).is_some() {
            self.shr_byte = extract_int_literal(peel_refs(&bin.right));
        }
    }

    fn note_sub(&mut self, bin: &syn::ExprBinary) {
        if !matches!(bin.op, syn::BinOp::Sub(_)) {
            return;
        }
        if let Some(lit) = extract_int_literal(peel_refs(&bin.left)) {
            self.sub_lit = Some(lit);
        }
        if let Some(lit) = extract_int_literal(peel_refs(&bin.right)) {
            self.right_lit = Some(lit);
        }
    }

    fn note_mant_cast(&mut self, expr: &Expr) {
        let Expr::Binary(bin) = peel_refs(expr) else {
            return;
        };
        if !matches!(bin.op, syn::BinOp::BitAnd(_)) {
            return;
        }
        if let Some(mask) = extract_int_literal(peel_refs(&bin.right)) {
            self.mant_mask = Some(mask);
        }
    }
}

fn ok_literal_in_block(block: &Block) -> Option<i64> {
    for stmt in &block.stmts {
        let Stmt::Expr(expr, _) = stmt else {
            continue;
        };
        let inner = match expr {
            Expr::Return(ret) => ret.expr.as_deref()?,
            other => other,
        };
        let Expr::Call(call) = peel_refs(inner) else {
            continue;
        };
        let Expr::Path(path) = peel_refs(&call.func) else {
            continue;
        };
        if path_to_string(&path.path).rsplit("::").next() != Some("Ok") {
            continue;
        }
        let arg = call.args.first()?;
        if let Some(lit) = extract_int_literal(peel_refs(arg)) {
            return Some(lit);
        }
    }
    None
}

fn block_returns_err(block: &Block) -> bool {
    for stmt in &block.stmts {
        let Stmt::Expr(expr, _) = stmt else {
            continue;
        };
        let inner = match expr {
            Expr::Return(ret) => ret.expr.as_deref().unwrap_or(expr),
            other => other,
        };
        let Expr::Call(call) = peel_refs(inner) else {
            continue;
        };
        let Expr::Path(path) = peel_refs(&call.func) else {
            continue;
        };
        if path_to_string(&path.path).rsplit("::").next() == Some("Err") {
            return true;
        }
    }
    false
}

fn cast_shift(expr: &Expr) -> Option<(String, i64, u32)> {
    let Expr::Cast(cast) = expr else {
        return None;
    };
    let (bits, signed) = int_cast_width(&cast.ty)?;
    if signed || bits == 0 || bits > 16 {
        return None;
    }
    let Expr::Binary(bin) = peel_refs(&cast.expr) else {
        return None;
    };
    if !matches!(bin.op, syn::BinOp::Shr(_)) {
        return None;
    }
    let Expr::Path(path) = &*bin.left else {
        return None;
    };
    let shift = extract_int_literal(&bin.right)?;
    if shift <= 0 || shift > 63 {
        return None;
    }
    Some((path_to_string(&path.path), shift, bits))
}

fn bitand_mask(expr: &Expr) -> Option<(String, i64)> {
    let Expr::Binary(bin) = expr else {
        return None;
    };
    if !matches!(bin.op, syn::BinOp::BitAnd(_)) {
        return None;
    }
    let Expr::Path(path) = &*bin.left else {
        return None;
    };
    let mask = extract_int_literal(&bin.right)?;
    Some((path_to_string(&path.path), mask))
}

fn rejected_range(if_expr: &syn::ExprIf, exponent: &str) -> Option<(i64, i64)> {
    let Expr::Unary(unary) = &*if_expr.cond else {
        return None;
    };
    if !matches!(unary.op, syn::UnOp::Not(_)) {
        return None;
    }
    let Expr::MethodCall(call) = &*unary.expr else {
        return None;
    };
    if call.method != "contains" {
        return None;
    }
    let receiver = peel_refs(&call.receiver);
    let Expr::Range(range) = receiver else {
        return None;
    };
    if !matches!(range.limits, syn::RangeLimits::Closed(_)) {
        return None;
    }
    let lo = extract_int_literal(range.start.as_deref()?)?;
    let hi = extract_int_literal(range.end.as_deref()?)?;
    let arg = peel_refs(call.args.first()?);
    let Expr::Path(path) = arg else {
        return None;
    };
    if path_to_string(&path.path) != exponent {
        return None;
    }
    if !returns_err(&if_expr.then_branch) {
        return None;
    }
    Some((lo, hi))
}

fn zero_mantissa_guard(if_expr: &syn::ExprIf, mantissa: &str) -> bool {
    let Expr::Binary(bin) = &*if_expr.cond else {
        return false;
    };
    if !matches!(bin.op, syn::BinOp::Eq(_)) {
        return false;
    }
    let Expr::Path(path) = &*bin.left else {
        return false;
    };
    path_to_string(&path.path) == mantissa
        && extract_int_literal(&bin.right) == Some(0)
        && returns_ok(&if_expr.then_branch)
}

fn shift_if(if_expr: &syn::ExprIf, exponent: &str) -> Option<(i64, i64, i64)> {
    let Expr::Binary(bin) = &*if_expr.cond else {
        return None;
    };
    if !matches!(bin.op, syn::BinOp::Le(_)) {
        return None;
    }
    let Expr::Path(path) = &*bin.left else {
        return None;
    };
    if path_to_string(&path.path) != exponent {
        return None;
    }
    let bias = extract_int_literal(&bin.right)?;
    let else_branch = if_expr.else_branch.as_ref()?.1.as_ref();
    let Expr::Block(else_block) = else_branch else {
        return None;
    };
    let (mul, limit) = shift_limit(&else_block.block, exponent, bias)?;
    let then_mul = shift_mul_in_block(&if_expr.then_branch, exponent, bias)?;
    if then_mul != mul {
        return None;
    }
    Some((bias, mul, limit))
}

fn shift_mul_in_block(block: &Block, exponent: &str, bias: i64) -> Option<i64> {
    for stmt in &block.stmts {
        let Stmt::Local(local) = stmt else {
            continue;
        };
        let init = &local.init.as_ref()?.expr;
        if let Some(mul) = byte_mul(init, exponent, bias) {
            return Some(mul);
        }
    }
    None
}

fn shift_limit(block: &Block, exponent: &str, bias: i64) -> Option<(i64, i64)> {
    let mul = shift_mul_in_block(block, exponent, bias)?;
    for stmt in &block.stmts {
        let Stmt::Expr(Expr::If(inner), _) = stmt else {
            continue;
        };
        let Expr::Binary(bin) = &*inner.cond else {
            continue;
        };
        if !matches!(bin.op, syn::BinOp::Ge(_)) {
            continue;
        }
        let limit = extract_int_literal(&bin.right)?;
        if returns_err(&inner.then_branch) {
            return Some((mul, limit));
        }
    }
    None
}

/// `8 * (bias - exponent)` or `8 * (exponent - bias)`.
fn byte_mul(expr: &Expr, exponent: &str, bias: i64) -> Option<i64> {
    let Expr::Binary(bin) = expr else {
        return None;
    };
    if !matches!(bin.op, syn::BinOp::Mul(_)) {
        return None;
    }
    let (lit, other) = if let Some(n) = extract_int_literal(&bin.left) {
        (n, &*bin.right)
    } else if let Some(n) = extract_int_literal(&bin.right) {
        (n, &*bin.left)
    } else {
        return None;
    };
    let other = match other {
        Expr::Paren(paren) => &*paren.expr,
        Expr::Cast(cast) => &*cast.expr,
        other => other,
    };
    let Expr::Binary(sub) = other else {
        return None;
    };
    if !matches!(sub.op, syn::BinOp::Sub(_)) {
        return None;
    }
    let left_bias = extract_int_literal(&sub.left) == Some(bias);
    let right_exp = path_is(&sub.right, exponent);
    let left_exp = path_is(&sub.left, exponent) || cast_path_is(&sub.left, exponent);
    let right_bias = extract_int_literal(&sub.right) == Some(bias);
    if (left_bias && right_exp) || (left_exp && right_bias) {
        Some(lit)
    } else {
        None
    }
}

fn path_is(expr: &Expr, name: &str) -> bool {
    let Expr::Path(path) = peel_refs(expr) else {
        return false;
    };
    path_to_string(&path.path) == name
}

fn cast_path_is(expr: &Expr, name: &str) -> bool {
    let Expr::Cast(cast) = expr else {
        return false;
    };
    path_is(&cast.expr, name)
}

fn returns_err(block: &Block) -> bool {
    block.stmts.iter().any(|stmt| match stmt {
        Stmt::Expr(Expr::Return(ret), _) => call_base(ret.expr.as_deref()) == Some("Err"),
        _ => false,
    })
}

fn returns_ok(block: &Block) -> bool {
    block.stmts.iter().any(|stmt| match stmt {
        Stmt::Expr(Expr::Return(ret), _) => call_base(ret.expr.as_deref()) == Some("Ok"),
        Stmt::Expr(expr, None) => call_base(Some(expr)) == Some("Ok"),
        _ => false,
    })
}

fn call_base(expr: Option<&Expr>) -> Option<&str> {
    let Expr::Call(call) = expr? else {
        return None;
    };
    let name = call_expr_to_name(&call.func).ok()?;
    Some(match name.rsplit("::").next() {
        Some(base) => {
            // Leak-free: return only by matching known bases.
            if base == "Err" || base == "Ok" {
                if base == "Err" { "Err" } else { "Ok" }
            } else {
                return None;
            }
        }
        None => return None,
    })
}

fn is_with_capacity(expr: &Expr) -> bool {
    let Expr::Call(call) = expr else {
        return false;
    };
    call_expr_to_name(&call.func)
        .ok()
        .is_some_and(|name| name.split("::").last() == Some("with_capacity"))
}

fn peel_refs(expr: &Expr) -> &Expr {
    match expr {
        Expr::Reference(reference) => peel_refs(&reference.expr),
        Expr::Paren(paren) => peel_refs(&paren.expr),
        other => other,
    }
}

/// `Hash` is `[u8; N]` in the primitives alias. A fixed array is its own length.
fn fixed_byte_len(ty: &syn::Type) -> Option<u32> {
    let ty = match ty {
        syn::Type::Reference(reference) => &reference.elem,
        other => other,
    };
    if let syn::Type::Array(array) = ty {
        if !is_u8_type(&array.elem) {
            return None;
        }
        return extract_int_literal(&array.len).and_then(|n| u32::try_from(n).ok());
    }
    if type_ident(ty).as_deref() == Some("Hash") {
        return hash_alias_bytes();
    }
    None
}

fn hash_alias_bytes() -> Option<u32> {
    if !crate::parser::spec_expr::consensus_workspace_present() {
        return None;
    }
    let path =
        std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../blvm-primitives/src/types.rs");
    let src = std::fs::read_to_string(path).ok()?;
    let key = "type Hash = [u8;";
    let rest = src.get(src.find(key)? + key.len()..)?;
    rest.split(']').next()?.trim().parse().ok()
}

struct SigopLimit {
    active: String,
    has_coinbase: bool,
    ge: bool,
    cap: i64,
}

/// The sigop-cap function: skip, then the count call, then the comparison.
fn parse_sigop_limit(block: &Block) -> Option<SigopLimit> {
    if block.stmts.len() != 4 {
        return None;
    }
    let skip_if = stmt_if(&block.stmts[0])?;
    if skip_if.else_branch.is_some() {
        return None;
    }
    let (active, has_coinbase) = parse_sigop_skip(&skip_if.cond)?;
    if !expr_ok_none(block_only_return(&skip_if.then_branch)?) {
        return None;
    }
    let Stmt::Local(local) = &block.stmts[1] else {
        return None;
    };
    let count_name = local_name(&local.pat)?;
    let init = local.init.as_ref()?;
    let Expr::Try(tried) = &*init.expr else {
        return None;
    };
    let Expr::Call(call) = &*tried.expr else {
        return None;
    };
    let callee = call_expr_to_name(&call.func).ok()?;
    if !callee.ends_with("get_transaction_sigop_count_for_bip54") {
        return None;
    }
    let over_if = stmt_if(&block.stmts[2])?;
    if over_if.else_branch.is_some() {
        return None;
    }
    let ge = parse_sigop_over(&over_if.cond, &count_name)?;
    if !expr_ok_some(block_only_return(&over_if.then_branch)?) {
        return None;
    }
    let Stmt::Expr(tail, None) = &block.stmts[3] else {
        return None;
    };
    if !expr_ok_none(tail) {
        return None;
    }
    Some(SigopLimit {
        active,
        has_coinbase,
        ge,
        cap: bip54_sigop_cap_u64()?,
    })
}

fn parse_sigop_skip(cond: &Expr) -> Option<(String, bool)> {
    if let Some(name) = negated_path(cond) {
        return Some((name, false));
    }
    let Expr::Binary(bin) = cond else {
        return None;
    };
    if !matches!(bin.op, syn::BinOp::Or(_)) {
        return None;
    }
    let name = negated_path(&bin.left)?;
    let Expr::Call(call) = &*bin.right else {
        return None;
    };
    let callee = call_expr_to_name(&call.func).ok()?;
    if !callee.ends_with("is_coinbase") {
        return None;
    }
    Some((name, true))
}

fn parse_sigop_over(cond: &Expr, count: &str) -> Option<bool> {
    let Expr::Binary(bin) = cond else {
        return None;
    };
    let ge = match bin.op {
        syn::BinOp::Ge(_) => true,
        syn::BinOp::Gt(_) => false,
        _ => return None,
    };
    if path_ident(&bin.left)?.as_str() != count {
        return None;
    }
    let right = path_to_string(expr_path(&bin.right)?);
    if !right.ends_with("BIP54_MAX_SIGOPS_PER_TX") {
        return None;
    }
    Some(ge)
}

fn negated_path(expr: &Expr) -> Option<String> {
    let Expr::Unary(unary) = expr else {
        return None;
    };
    if !matches!(unary.op, syn::UnOp::Not(_)) {
        return None;
    }
    path_ident(&unary.expr)
}

fn path_ident(expr: &Expr) -> Option<String> {
    let path = expr_path(expr)?;
    path.get_ident().map(|ident| ident.to_string())
}

fn expr_path(expr: &Expr) -> Option<&syn::Path> {
    let Expr::Path(path) = expr else {
        return None;
    };
    Some(&path.path)
}

fn stmt_if(stmt: &Stmt) -> Option<&syn::ExprIf> {
    let Stmt::Expr(Expr::If(iff), _) = stmt else {
        return None;
    };
    Some(iff)
}

fn block_only_return(block: &Block) -> Option<&Expr> {
    if block.stmts.len() != 1 {
        return None;
    }
    let Stmt::Expr(Expr::Return(ret), _) = &block.stmts[0] else {
        return None;
    };
    ret.expr.as_deref()
}

fn expr_ok_none(expr: &Expr) -> bool {
    let Expr::Call(call) = expr else {
        return false;
    };
    let Ok(name) = call_expr_to_name(&call.func) else {
        return false;
    };
    if !name.ends_with("Ok") || call.args.len() != 1 {
        return false;
    }
    path_ident(&call.args[0]).as_deref() == Some("None")
}

fn expr_ok_some(expr: &Expr) -> bool {
    let Expr::Call(call) = expr else {
        return false;
    };
    let Ok(name) = call_expr_to_name(&call.func) else {
        return false;
    };
    if !name.ends_with("Ok") || call.args.len() != 1 {
        return false;
    }
    let Expr::Call(inner) = &call.args[0] else {
        return false;
    };
    call_expr_to_name(&inner.func)
        .ok()
        .is_some_and(|inner_name| inner_name.ends_with("Some"))
}

/// `MEDIAN_TIME_BLOCKS` as written next to `get_median_time_past`.
fn median_blocks_u64() -> Option<i64> {
    if !crate::parser::spec_expr::consensus_workspace_present() {
        return None;
    }
    let path =
        std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../blvm-consensus/src/bip113.rs");
    let src = std::fs::read_to_string(path).ok()?;
    let needle = "const MEDIAN_TIME_BLOCKS:";
    let rest = src.get(src.find(needle)? + needle.len()..)?;
    let expr = rest
        .get(rest.find('=')? + 1..)?
        .split([';', '\n'])
        .next()?
        .trim();
    let value: i64 = expr.replace(['_', ' '], "").parse().ok()?;
    (1..=16).contains(&value).then_some(value)
}

struct MedianTime {
    param: String,
    window: i64,
    sorts: bool,
    lower: bool,
}

/// Empty slice, tail window, optional sort, then `n / 2` or `n / 2 - 1`.
fn parse_median_time(block: &Block) -> Option<MedianTime> {
    let mut saw_empty = false;
    let mut saw_tail = false;
    let mut saw_min = false;
    let mut saw_for = false;
    let mut saw_timestamp = false;
    let mut sorts = false;
    let mut saw_index = false;
    let mut lower = false;
    let mut param = None;
    walk_median(
        block,
        &mut saw_empty,
        &mut saw_tail,
        &mut saw_min,
        &mut saw_for,
        &mut saw_timestamp,
        &mut sorts,
        &mut saw_index,
        &mut lower,
        &mut param,
    );
    if !(saw_empty && saw_tail && saw_min && saw_for && saw_timestamp && saw_index) {
        return None;
    }
    Some(MedianTime {
        param: param?,
        window: median_blocks_u64()?,
        sorts,
        lower,
    })
}

#[allow(clippy::too_many_arguments)]
fn walk_median(
    block: &Block,
    saw_empty: &mut bool,
    saw_tail: &mut bool,
    saw_min: &mut bool,
    saw_for: &mut bool,
    saw_timestamp: &mut bool,
    sorts: &mut bool,
    saw_index: &mut bool,
    lower: &mut bool,
    param: &mut Option<String>,
) {
    for stmt in &block.stmts {
        match stmt {
            Stmt::Local(local) => {
                if let Some(init) = &local.init {
                    walk_median_expr(
                        &init.expr,
                        saw_empty,
                        saw_tail,
                        saw_min,
                        saw_for,
                        saw_timestamp,
                        sorts,
                        saw_index,
                        lower,
                        param,
                    );
                }
            }
            Stmt::Expr(expr, _) => walk_median_expr(
                expr,
                saw_empty,
                saw_tail,
                saw_min,
                saw_for,
                saw_timestamp,
                sorts,
                saw_index,
                lower,
                param,
            ),
            Stmt::Item(_) | Stmt::Macro(_) => {}
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn walk_median_expr(
    expr: &Expr,
    saw_empty: &mut bool,
    saw_tail: &mut bool,
    saw_min: &mut bool,
    saw_for: &mut bool,
    saw_timestamp: &mut bool,
    sorts: &mut bool,
    saw_index: &mut bool,
    lower: &mut bool,
    param: &mut Option<String>,
) {
    match expr {
        Expr::MethodCall(call) => {
            match call.method.to_string().as_str() {
                "is_empty" => {
                    *saw_empty = true;
                    if let Some(name) = path_ident(&call.receiver) {
                        *param = Some(name);
                    }
                }
                "saturating_sub" => {
                    if call.args.len() == 1 && path_ends(&call.args[0], "MEDIAN_TIME_BLOCKS") {
                        *saw_tail = true;
                    }
                }
                "min" => {
                    if call.args.len() == 1 && path_ends(&call.args[0], "MEDIAN_TIME_BLOCKS") {
                        *saw_min = true;
                    }
                }
                "sort_unstable" => *sorts = true,
                _ => {}
            }
            walk_median_expr(
                &call.receiver,
                saw_empty,
                saw_tail,
                saw_min,
                saw_for,
                saw_timestamp,
                sorts,
                saw_index,
                lower,
                param,
            );
            for arg in &call.args {
                walk_median_expr(
                    arg,
                    saw_empty,
                    saw_tail,
                    saw_min,
                    saw_for,
                    saw_timestamp,
                    sorts,
                    saw_index,
                    lower,
                    param,
                );
            }
        }
        Expr::Field(field) => {
            if matches!(&field.member, syn::Member::Named(name) if name == "timestamp") {
                *saw_timestamp = true;
            }
            walk_median_expr(
                &field.base,
                saw_empty,
                saw_tail,
                saw_min,
                saw_for,
                saw_timestamp,
                sorts,
                saw_index,
                lower,
                param,
            );
        }
        Expr::Index(index) => {
            if let Some(is_lower) = half_index(&index.index) {
                *saw_index = true;
                *lower = is_lower;
            }
            walk_median_expr(
                &index.expr,
                saw_empty,
                saw_tail,
                saw_min,
                saw_for,
                saw_timestamp,
                sorts,
                saw_index,
                lower,
                param,
            );
        }
        Expr::ForLoop(loop_expr) => {
            *saw_for = true;
            walk_median_expr(
                &loop_expr.expr,
                saw_empty,
                saw_tail,
                saw_min,
                saw_for,
                saw_timestamp,
                sorts,
                saw_index,
                lower,
                param,
            );
            walk_median(
                &loop_expr.body,
                saw_empty,
                saw_tail,
                saw_min,
                saw_for,
                saw_timestamp,
                sorts,
                saw_index,
                lower,
                param,
            );
        }
        Expr::If(iff) => {
            walk_median_expr(
                &iff.cond,
                saw_empty,
                saw_tail,
                saw_min,
                saw_for,
                saw_timestamp,
                sorts,
                saw_index,
                lower,
                param,
            );
            walk_median(
                &iff.then_branch,
                saw_empty,
                saw_tail,
                saw_min,
                saw_for,
                saw_timestamp,
                sorts,
                saw_index,
                lower,
                param,
            );
            if let Some((_, else_branch)) = &iff.else_branch {
                walk_median_expr(
                    else_branch,
                    saw_empty,
                    saw_tail,
                    saw_min,
                    saw_for,
                    saw_timestamp,
                    sorts,
                    saw_index,
                    lower,
                    param,
                );
            }
        }
        Expr::Block(block) => walk_median(
            &block.block,
            saw_empty,
            saw_tail,
            saw_min,
            saw_for,
            saw_timestamp,
            sorts,
            saw_index,
            lower,
            param,
        ),
        Expr::Return(ret) => {
            if let Some(value) = &ret.expr {
                walk_median_expr(
                    value,
                    saw_empty,
                    saw_tail,
                    saw_min,
                    saw_for,
                    saw_timestamp,
                    sorts,
                    saw_index,
                    lower,
                    param,
                );
            }
        }
        Expr::Assign(assign) => {
            walk_median_expr(
                &assign.left,
                saw_empty,
                saw_tail,
                saw_min,
                saw_for,
                saw_timestamp,
                sorts,
                saw_index,
                lower,
                param,
            );
            walk_median_expr(
                &assign.right,
                saw_empty,
                saw_tail,
                saw_min,
                saw_for,
                saw_timestamp,
                sorts,
                saw_index,
                lower,
                param,
            );
        }
        Expr::Reference(reference) => walk_median_expr(
            &reference.expr,
            saw_empty,
            saw_tail,
            saw_min,
            saw_for,
            saw_timestamp,
            sorts,
            saw_index,
            lower,
            param,
        ),
        Expr::Binary(bin) => {
            walk_median_expr(
                &bin.left,
                saw_empty,
                saw_tail,
                saw_min,
                saw_for,
                saw_timestamp,
                sorts,
                saw_index,
                lower,
                param,
            );
            walk_median_expr(
                &bin.right,
                saw_empty,
                saw_tail,
                saw_min,
                saw_for,
                saw_timestamp,
                sorts,
                saw_index,
                lower,
                param,
            );
        }
        Expr::Call(call) => {
            for arg in &call.args {
                walk_median_expr(
                    arg,
                    saw_empty,
                    saw_tail,
                    saw_min,
                    saw_for,
                    saw_timestamp,
                    sorts,
                    saw_index,
                    lower,
                    param,
                );
            }
        }
        Expr::Repeat(repeat) => walk_median_expr(
            &repeat.expr,
            saw_empty,
            saw_tail,
            saw_min,
            saw_for,
            saw_timestamp,
            sorts,
            saw_index,
            lower,
            param,
        ),
        _ => {}
    }
}

fn half_index(expr: &Expr) -> Option<bool> {
    if let Expr::Binary(bin) = expr {
        if matches!(bin.op, syn::BinOp::Sub(_)) && is_div_two(&bin.left) && is_lit(&bin.right, 1) {
            return Some(true);
        }
        if matches!(bin.op, syn::BinOp::Div(_)) && is_lit(&bin.right, 2) {
            return Some(false);
        }
    }
    None
}

fn is_div_two(expr: &Expr) -> bool {
    let Expr::Binary(bin) = expr else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Div(_)) && is_lit(&bin.right, 2)
}

fn is_lit(expr: &Expr, value: i64) -> bool {
    let Expr::Lit(lit) = expr else {
        return false;
    };
    let syn::Lit::Int(int) = &lit.lit else {
        return false;
    };
    int.base10_parse::<i64>().ok() == Some(value)
}

fn path_ends(expr: &Expr, suffix: &str) -> bool {
    let Expr::Path(path) = expr else {
        return false;
    };
    path_to_string(&path.path).ends_with(suffix)
}

struct StripAnnex {
    witness: String,
    min: i64,
    tag: i64,
}

/// `TAPROOT_ANNEX_TAG` as written next to `strip_taproot_annex`.
fn annex_tag_u64() -> Option<i64> {
    if !crate::parser::spec_expr::consensus_workspace_present() {
        return None;
    }
    let path =
        std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../blvm-consensus/src/taproot.rs");
    let src = std::fs::read_to_string(path).ok()?;
    let needle = "const TAPROOT_ANNEX_TAG:";
    let rest = src.get(src.find(needle)? + needle.len()..)?;
    let expr = rest
        .get(rest.find('=')? + 1..)?
        .split([';', '\n'])
        .next()?
        .trim();
    let value = if let Some(hex) = expr.strip_prefix("0x").or_else(|| expr.strip_prefix("0X")) {
        i64::from_str_radix(hex, 16).ok()?
    } else {
        expr.replace(['_', ' '], "").parse().ok()?
    };
    (0..=255).contains(&value).then_some(value)
}

/// Stack length, annex tag, the dropped tail, and the annex hash.
fn parse_strip_annex(block: &Block) -> Option<StripAnnex> {
    let mut seen = StripSeen::default();
    walk_strip_block(block, &mut seen);
    if !(seen.witness.is_some() && seen.min.is_some() && seen.tag && seen.hash && seen.slice) {
        return None;
    }
    Some(StripAnnex {
        witness: seen.witness?,
        min: seen.min?,
        tag: seen.tag_lit.unwrap_or(annex_tag_u64()?),
    })
}

#[derive(Default)]
struct StripSeen {
    witness: Option<String>,
    min: Option<i64>,
    tag: bool,
    tag_lit: Option<i64>,
    hash: bool,
    slice: bool,
}

fn walk_strip_block(block: &Block, seen: &mut StripSeen) {
    for stmt in &block.stmts {
        match stmt {
            Stmt::Local(local) => {
                if let Some(init) = &local.init {
                    walk_strip_expr(&init.expr, seen);
                }
            }
            Stmt::Expr(expr, _) => walk_strip_expr(expr, seen),
            Stmt::Item(_) | Stmt::Macro(_) => {}
        }
    }
}

fn walk_strip_expr(expr: &Expr, seen: &mut StripSeen) {
    match expr {
        Expr::Binary(bin) => {
            if matches!(bin.op, syn::BinOp::Ge(_)) {
                if let Expr::MethodCall(call) = &*bin.left {
                    if call.method == "len" {
                        if let Some(param) = path_ident(&call.receiver) {
                            seen.witness = Some(param);
                        }
                        if let Some(value) = lit_i64(&bin.right) {
                            seen.min = Some(value);
                        }
                    }
                }
            }
            if matches!(bin.op, syn::BinOp::Eq(_)) && path_ident(&bin.left).as_deref() == Some("b")
            {
                if path_ends(&bin.right, "TAPROOT_ANNEX_TAG") {
                    seen.tag = true;
                } else if let Some(value) = lit_i64(&bin.right) {
                    seen.tag = true;
                    seen.tag_lit = Some(value);
                }
            }
            walk_strip_expr(&bin.left, seen);
            walk_strip_expr(&bin.right, seen);
        }
        Expr::MethodCall(call) => {
            if call.method == "len" {
                if let Some(param) = path_ident(&call.receiver) {
                    seen.witness = Some(param);
                }
            }
            walk_strip_expr(&call.receiver, seen);
            for arg in &call.args {
                walk_strip_expr(arg, seen);
            }
        }
        Expr::Call(call) => {
            if call_expr_to_name(&call.func)
                .ok()
                .is_some_and(|name| name.ends_with("compute_taproot_annex_sighash_hash"))
            {
                seen.hash = true;
            }
            for arg in &call.args {
                walk_strip_expr(arg, seen);
            }
        }
        Expr::Index(index) => {
            if matches!(*index.index, Expr::Range(_)) {
                seen.slice = true;
            }
            walk_strip_expr(&index.expr, seen);
            walk_strip_expr(&index.index, seen);
        }
        Expr::Range(range) => {
            seen.slice = true;
            if let Some(start) = &range.start {
                walk_strip_expr(start, seen);
            }
            if let Some(end) = &range.end {
                walk_strip_expr(end, seen);
            }
        }
        Expr::Closure(closure) => walk_strip_expr(&closure.body, seen),
        Expr::If(iff) => {
            walk_strip_expr(&iff.cond, seen);
            walk_strip_block(&iff.then_branch, seen);
            if let Some((_, else_branch)) = &iff.else_branch {
                walk_strip_expr(else_branch, seen);
            }
        }
        Expr::Block(block) => walk_strip_block(&block.block, seen),
        Expr::Return(ret) => {
            if let Some(value) = &ret.expr {
                walk_strip_expr(value, seen);
            }
        }
        Expr::Tuple(tuple) => {
            for elem in &tuple.elems {
                walk_strip_expr(elem, seen);
            }
        }
        Expr::Reference(reference) => walk_strip_expr(&reference.expr, seen),
        Expr::Unary(unary) => walk_strip_expr(&unary.expr, seen),
        Expr::Paren(paren) => walk_strip_expr(&paren.expr, seen),
        Expr::Group(group) => walk_strip_expr(&group.expr, seen),
        Expr::Field(field) => walk_strip_expr(&field.base, seen),
        Expr::Cast(cast) => walk_strip_expr(&cast.expr, seen),
        Expr::Repeat(repeat) => walk_strip_expr(&repeat.expr, seen),
        _ => {}
    }
}

fn lit_i64(expr: &Expr) -> Option<i64> {
    let Expr::Lit(lit) = expr else {
        return None;
    };
    let syn::Lit::Int(int) = &lit.lit else {
        return None;
    };
    int.base10_parse::<i64>().ok()
}

struct BlockProof {
    zero_out: i64,
    plus: bool,
}

/// `expand_target` as written in the proof-of-work source.
fn expand_target_spec() -> Option<CompactTarget> {
    if !crate::parser::spec_expr::consensus_workspace_present() {
        return None;
    }
    let path =
        std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../blvm-consensus/src/pow.rs");
    let src = std::fs::read_to_string(path).ok()?;
    let file = syn::parse_file(&src).ok()?;
    let func = file.items.into_iter().find_map(|item| match item {
        syn::Item::Fn(func) if func.sig.ident == "expand_target" => Some(func),
        _ => None,
    })?;
    parse_compact_target(&func.block)
}

/// Zero-target result, then `~target / (target + 1)`, plus one when that add remains.
fn parse_block_proof(block: &Block) -> Option<BlockProof> {
    let mut seen = ProofSeen::default();
    walk_proof_block(block, &mut seen);
    if !(seen.expand && seen.work && seen.zero_out.is_some()) {
        return None;
    }
    Some(BlockProof {
        zero_out: seen.zero_out?,
        plus: seen.plus,
    })
}

#[derive(Default)]
struct ProofSeen {
    expand: bool,
    work: bool,
    zero_out: Option<i64>,
    plus: bool,
}

fn walk_proof_block(block: &Block, seen: &mut ProofSeen) {
    for stmt in &block.stmts {
        match stmt {
            Stmt::Local(local) => {
                if let Some(init) = &local.init {
                    walk_proof_expr(&init.expr, seen);
                }
            }
            Stmt::Expr(expr, _) => walk_proof_expr(expr, seen),
            Stmt::Item(_) | Stmt::Macro(_) => {}
        }
    }
}

fn walk_proof_expr(expr: &Expr, seen: &mut ProofSeen) {
    match expr {
        Expr::Try(try_expr) => {
            if let Expr::Call(call) = &*try_expr.expr {
                if call_expr_to_name(&call.func)
                    .ok()
                    .is_some_and(|name| name.ends_with("expand_target"))
                {
                    seen.expand = true;
                }
            }
            walk_proof_expr(&try_expr.expr, seen);
        }
        Expr::If(iff) => {
            if let Expr::MethodCall(call) = &*iff.cond {
                if call.method == "is_zero" {
                    seen.zero_out = u256_unit(&iff.then_branch);
                }
            }
            walk_proof_expr(&iff.cond, seen);
            walk_proof_block(&iff.then_branch, seen);
            if let Some((_, else_branch)) = &iff.else_branch {
                walk_proof_expr(else_branch, seen);
            }
        }
        Expr::MethodCall(call) => {
            if call.method == "div" {
                if let Expr::MethodCall(inner) = &*call.receiver {
                    if inner.method == "not" {
                        seen.work = true;
                    }
                }
            }
            if call.method == "checked_add"
                && call.args.len() == 1
                && expr_ends_one(&call.args[0])
                && path_ident(&call.receiver).as_deref() == Some("quotient")
            {
                seen.plus = true;
            }
            walk_proof_expr(&call.receiver, seen);
            for arg in &call.args {
                walk_proof_expr(arg, seen);
            }
        }
        Expr::Call(call) => {
            for arg in &call.args {
                walk_proof_expr(arg, seen);
            }
        }
        Expr::Return(ret) => {
            if let Some(value) = &ret.expr {
                walk_proof_expr(value, seen);
            }
        }
        Expr::Block(block) => walk_proof_block(&block.block, seen),
        Expr::Tuple(tuple) => {
            for elem in &tuple.elems {
                walk_proof_expr(elem, seen);
            }
        }
        _ => {}
    }
}

fn expr_ends_one(expr: &Expr) -> bool {
    match expr {
        Expr::Path(_) => path_ends(expr, "one"),
        Expr::Call(call) => call_expr_to_name(&call.func)
            .ok()
            .is_some_and(|name| name.ends_with("one")),
        _ => false,
    }
}

fn u256_unit(block: &Block) -> Option<i64> {
    let stmt = block.stmts.first()?;
    let expr = match stmt {
        Stmt::Expr(expr, _) => expr,
        _ => return None,
    };
    let expr = match expr {
        Expr::Return(ret) => ret.expr.as_deref()?,
        other => other,
    };
    let Expr::Call(call) = expr else {
        return None;
    };
    if !call_expr_to_name(&call.func)
        .ok()
        .is_some_and(|name| name.ends_with("Ok"))
        || call.args.len() != 1
    {
        return None;
    }
    let Expr::Call(inner) = &call.args[0] else {
        return None;
    };
    let name = call_expr_to_name(&inner.func).ok()?;
    if name.ends_with("zero") {
        Some(0)
    } else if name.ends_with("one") {
        Some(1)
    } else {
        None
    }
}

struct Bip34 {
    /// `if !prefix` rejects. The `false &&` edit rejects when the prefix matches.
    negated: bool,
    /// Inactive fork returns valid. The `false` edit removes that skip.
    skips: bool,
}

fn parse_bip34(block: &Block) -> Option<Bip34> {
    let mut seen = Bip34Seen::default();
    walk_bip34_block(block, &mut seen);
    if !(seen.coinbase && seen.first && seen.negated.is_some() && seen.skips.is_some()) {
        return None;
    }
    Some(Bip34 {
        negated: seen.negated?,
        skips: seen.skips?,
    })
}

#[derive(Default)]
struct Bip34Seen {
    coinbase: bool,
    first: bool,
    negated: Option<bool>,
    skips: Option<bool>,
}

fn walk_bip34_block(block: &Block, seen: &mut Bip34Seen) {
    for stmt in &block.stmts {
        match stmt {
            Stmt::Local(local) => {
                if let Some(init) = &local.init {
                    walk_bip34_expr(&init.expr, seen);
                }
            }
            Stmt::Expr(expr, _) => walk_bip34_expr(expr, seen),
            Stmt::Item(_) | Stmt::Macro(_) => {}
        }
    }
}

fn walk_bip34_expr(expr: &Expr, seen: &mut Bip34Seen) {
    match expr {
        Expr::If(iff) => {
            note_bip34_if(iff, seen);
            walk_bip34_expr(&iff.cond, seen);
            walk_bip34_block(&iff.then_branch, seen);
            if let Some((_, else_branch)) = &iff.else_branch {
                walk_bip34_expr(else_branch, seen);
            }
        }
        Expr::MethodCall(call) => {
            if call.method == "first" {
                seen.first = true;
            }
            walk_bip34_expr(&call.receiver, seen);
            for arg in &call.args {
                walk_bip34_expr(arg, seen);
            }
        }
        Expr::Call(call) => {
            if call_ends(&call.func, "is_coinbase") {
                seen.coinbase = true;
            }
            for arg in &call.args {
                walk_bip34_expr(arg, seen);
            }
        }
        Expr::Let(let_expr) => walk_bip34_expr(&let_expr.expr, seen),
        Expr::Block(block) => walk_bip34_block(&block.block, seen),
        Expr::Return(ret) => {
            if let Some(value) = &ret.expr {
                walk_bip34_expr(value, seen);
            }
        }
        Expr::Unary(unary) => walk_bip34_expr(&unary.expr, seen),
        Expr::Binary(bin) => {
            walk_bip34_expr(&bin.left, seen);
            walk_bip34_expr(&bin.right, seen);
        }
        Expr::Reference(reference) => walk_bip34_expr(&reference.expr, seen),
        Expr::Field(field) => walk_bip34_expr(&field.base, seen),
        Expr::Index(index) => {
            walk_bip34_expr(&index.expr, seen);
            walk_bip34_expr(&index.index, seen);
        }
        _ => {}
    }
}

fn note_bip34_if(iff: &syn::ExprIf, seen: &mut Bip34Seen) {
    if returns_ok_bool(&iff.then_branch, false) {
        if let Expr::Unary(unary) = &*iff.cond {
            if matches!(unary.op, syn::UnOp::Not(_))
                && expr_is_call(&unary.expr, "script_sig_starts_with_height")
            {
                seen.negated = Some(true);
            }
        }
        if let Expr::Binary(bin) = &*iff.cond {
            if matches!(bin.op, syn::BinOp::And(_))
                && is_not_false(&bin.left)
                && expr_is_call(&bin.right, "script_sig_starts_with_height")
            {
                seen.negated = Some(false);
            }
        }
    }
    if returns_ok_bool(&iff.then_branch, true) {
        if is_false_lit(&iff.cond) {
            seen.skips = Some(false);
        }
        if let Expr::Unary(unary) = &*iff.cond {
            if matches!(unary.op, syn::UnOp::Not(_)) && is_bip34_active_call(&unary.expr) {
                seen.skips = Some(true);
            }
        }
    }
}

fn returns_ok_bool(block: &Block, value: bool) -> bool {
    let Some(Stmt::Expr(expr, _)) = block.stmts.first() else {
        return false;
    };
    ok_bool_expr(expr, value)
}

fn ok_bool_expr(expr: &Expr, value: bool) -> bool {
    let expr = if let Expr::Return(ret) = expr {
        let Some(inner) = ret.expr.as_deref() else {
            return false;
        };
        inner
    } else {
        expr
    };
    let Expr::Call(call) = expr else {
        return false;
    };
    if !call_ends(&call.func, "Ok") || call.args.len() != 1 {
        return false;
    }
    is_bool_lit(&call.args[0], value)
}

fn is_bool_lit(expr: &Expr, value: bool) -> bool {
    let Expr::Lit(lit) = expr else {
        return false;
    };
    matches!(&lit.lit, syn::Lit::Bool(bit) if bit.value == value)
}

fn is_false_lit(expr: &Expr) -> bool {
    is_bool_lit(expr, false)
}

fn is_not_false(expr: &Expr) -> bool {
    let Expr::Unary(unary) = expr else {
        return false;
    };
    matches!(unary.op, syn::UnOp::Not(_)) && is_false_lit(&unary.expr)
}

fn is_bip34_active_call(expr: &Expr) -> bool {
    let Expr::MethodCall(call) = expr else {
        return false;
    };
    call.method == "is_fork_active" && call.args.iter().any(|arg| path_ends(arg, "Bip34"))
}

fn expr_is_call(expr: &Expr, suffix: &str) -> bool {
    let Expr::Call(call) = expr else {
        return false;
    };
    call_ends(&call.func, suffix)
}

fn call_ends(func: &Expr, suffix: &str) -> bool {
    call_expr_to_name(func)
        .ok()
        .is_some_and(|name| name.ends_with(suffix))
}

struct Bip30 {
    skips: bool,
    threshold: i64,
    heights: [i64; 2],
}

fn parse_bip30(block: &Block) -> Option<Bip30> {
    let mut seen = Bip30Seen::default();
    walk_bip30_block(block, &mut seen);
    if !(seen.header_hash
        && seen.repeat
        && seen.coinbase
        && seen.txid
        && seen.index
        && seen.tx_arm
        && seen.first
        && seen.scan
        && seen.hash_eq)
    {
        return None;
    }
    let (left, right) = seen.heights?;
    Some(Bip30 {
        skips: seen.skips?,
        threshold: seen.threshold?,
        heights: [left, right],
    })
}

#[derive(Default)]
struct Bip30Seen {
    skips: Option<bool>,
    threshold: Option<i64>,
    heights: Option<(i64, i64)>,
    header_hash: bool,
    repeat: bool,
    coinbase: bool,
    txid: bool,
    index: bool,
    tx_arm: bool,
    first: bool,
    scan: bool,
    hash_eq: bool,
}

fn walk_bip30_block(block: &Block, seen: &mut Bip30Seen) {
    for stmt in &block.stmts {
        match stmt {
            Stmt::Local(local) => {
                if let Some(init) = &local.init {
                    walk_bip30_expr(&init.expr, seen);
                }
            }
            Stmt::Expr(expr, _) => walk_bip30_expr(expr, seen),
            Stmt::Item(_) | Stmt::Macro(_) => {}
        }
    }
}

fn walk_bip30_expr(expr: &Expr, seen: &mut Bip30Seen) {
    match expr {
        Expr::If(iff) => {
            note_bip30_if(iff, seen);
            walk_bip30_expr(&iff.cond, seen);
            walk_bip30_block(&iff.then_branch, seen);
            if let Some((_, else_branch)) = &iff.else_branch {
                walk_bip30_expr(else_branch, seen);
            }
        }
        Expr::Let(let_expr) => {
            if pat_is_some(&let_expr.pat) {
                if path_ends(&let_expr.expr, "bip30_index") {
                    seen.index = true;
                } else {
                    seen.tx_arm = true;
                }
            }
            walk_bip30_expr(&let_expr.expr, seen);
        }
        Expr::ForLoop(fl) => {
            seen.scan = true;
            walk_bip30_block(&fl.body, seen);
        }
        Expr::Closure(closure) => walk_bip30_expr(&closure.body, seen),
        Expr::MethodCall(call) => {
            if call.method == "first" {
                seen.first = true;
            }
            walk_bip30_expr(&call.receiver, seen);
            for arg in &call.args {
                walk_bip30_expr(arg, seen);
            }
        }
        Expr::Call(call) => {
            if call_ends(&call.func, "is_coinbase") {
                seen.coinbase = true;
            }
            if call_ends(&call.func, "block_header_hash") {
                seen.header_hash = true;
            }
            if call_ends(&call.func, "is_bip30_repeat_block") {
                seen.repeat = true;
            }
            if call_ends(&call.func, "calculate_tx_id") {
                seen.txid = true;
            }
            for arg in &call.args {
                walk_bip30_expr(arg, seen);
            }
        }
        Expr::Binary(bin) => {
            if matches!(bin.op, syn::BinOp::Or(_)) {
                if let (Some(left), Some(right)) =
                    (height_eq_lit(&bin.left), height_eq_lit(&bin.right))
                {
                    seen.heights = Some((left, right));
                }
            }
            if matches!(bin.op, syn::BinOp::Gt(_)) && path_is(&bin.left, "c") {
                if let Some(threshold) = lit_i64(&bin.right) {
                    seen.threshold = Some(threshold);
                }
            }
            if matches!(bin.op, syn::BinOp::Eq(_))
                && (expr_is_hash_field(&bin.left) || expr_is_hash_field(&bin.right))
            {
                seen.hash_eq = true;
            }
            walk_bip30_expr(&bin.left, seen);
            walk_bip30_expr(&bin.right, seen);
        }
        Expr::Block(block) => walk_bip30_block(&block.block, seen),
        Expr::Return(ret) => {
            if let Some(value) = &ret.expr {
                walk_bip30_expr(value, seen);
            }
        }
        Expr::Unary(unary) => walk_bip30_expr(&unary.expr, seen),
        Expr::Reference(reference) => walk_bip30_expr(&reference.expr, seen),
        Expr::Field(field) => walk_bip30_expr(&field.base, seen),
        Expr::Index(index) => {
            walk_bip30_expr(&index.expr, seen);
            walk_bip30_expr(&index.index, seen);
        }
        Expr::Paren(paren) => walk_bip30_expr(&paren.expr, seen),
        Expr::Group(group) => walk_bip30_expr(&group.expr, seen),
        _ => {}
    }
}

fn note_bip30_if(iff: &syn::ExprIf, seen: &mut Bip30Seen) {
    if !returns_ok_bool(&iff.then_branch, true) {
        return;
    }
    if is_false_lit(&iff.cond) {
        seen.skips = Some(false);
    }
    if let Expr::Unary(unary) = &*iff.cond {
        if matches!(unary.op, syn::UnOp::Not(_)) && is_bip30_active_call(&unary.expr) {
            seen.skips = Some(true);
        }
    }
}

fn is_bip30_active_call(expr: &Expr) -> bool {
    let Expr::MethodCall(call) = expr else {
        return false;
    };
    call.method == "is_fork_active" && call.args.iter().any(|arg| path_ends(arg, "Bip30"))
}

fn height_eq_lit(expr: &Expr) -> Option<i64> {
    let Expr::Binary(bin) = expr else {
        return None;
    };
    if !matches!(bin.op, syn::BinOp::Eq(_)) || !path_is(&bin.left, "height") {
        return None;
    }
    lit_i64(&bin.right)
}

fn pat_is_some(pat: &syn::Pat) -> bool {
    let syn::Pat::TupleStruct(tuple) = pat else {
        return false;
    };
    path_to_string(&tuple.path).ends_with("Some")
}

fn expr_is_hash_field(expr: &Expr) -> bool {
    let Expr::Field(field) = expr else {
        return false;
    };
    match &field.member {
        syn::Member::Named(name) => name == "hash",
        syn::Member::Unnamed(_) => false,
    }
}

/// Height and digest pairs from `is_bip30_repeat_block` and its constants.
fn bip30_repeat_digests() -> Option<Vec<(i64, Vec<u8>)>> {
    if !crate::parser::spec_expr::consensus_workspace_present() {
        return None;
    }
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../blvm-consensus/src/bip_validation.rs");
    let src = std::fs::read_to_string(path).ok()?;
    let file = syn::parse_file(&src).ok()?;
    let mut pairs = Vec::new();
    let mut bytes = std::collections::HashMap::<String, Vec<u8>>::new();
    for item in &file.items {
        match item {
            syn::Item::Fn(func) if func.sig.ident == "is_bip30_repeat_block" => {
                collect_bip30_pairs(&func.block, &mut pairs);
            }
            syn::Item::Const(item) => {
                if let Some(buf) = const_byte_array(&item.expr) {
                    bytes.insert(item.ident.to_string(), buf);
                }
            }
            _ => {}
        }
    }
    let mut out = Vec::new();
    for (height, name) in pairs {
        out.push((height, bytes.get(&name)?.clone()));
    }
    if out.len() == 2 { Some(out) } else { None }
}

fn collect_bip30_pairs(block: &Block, pairs: &mut Vec<(i64, String)>) {
    for stmt in &block.stmts {
        let Stmt::Expr(expr, _) = stmt else {
            continue;
        };
        let Expr::Match(matched) = expr else {
            continue;
        };
        for arm in &matched.arms {
            let Some(height) = pat_lit_i64(&arm.pat) else {
                continue;
            };
            let Some(name) = eq_const_name(&arm.body) else {
                continue;
            };
            pairs.push((height, name));
        }
    }
}

fn pat_lit_i64(pat: &syn::Pat) -> Option<i64> {
    let syn::Pat::Lit(expr_lit) = pat else {
        return None;
    };
    let syn::Lit::Int(int) = &expr_lit.lit else {
        return None;
    };
    int.base10_parse::<i64>().ok()
}

fn eq_const_name(expr: &Expr) -> Option<String> {
    let Expr::Binary(bin) = expr else {
        return None;
    };
    if !matches!(bin.op, syn::BinOp::Eq(_)) {
        return None;
    }
    ref_path_last(&bin.right).or_else(|| ref_path_last(&bin.left))
}

fn ref_path_last(expr: &Expr) -> Option<String> {
    let expr = match expr {
        Expr::Reference(reference) => &*reference.expr,
        other => other,
    };
    let Expr::Path(path) = expr else {
        return None;
    };
    path_to_string(&path.path)
        .rsplit("::")
        .next()
        .map(str::to_string)
}

fn const_byte_array(expr: &Expr) -> Option<Vec<u8>> {
    let Expr::Array(array) = expr else {
        return None;
    };
    let mut buf = Vec::new();
    for elem in &array.elems {
        let value = lit_i64(elem)?;
        if !(0..=255).contains(&value) {
            return None;
        }
        buf.push(value as u8);
    }
    if buf.len() == 32 { Some(buf) } else { None }
}

struct FlagOr {
    fork: String,
    bit: i64,
}

struct ScriptFlags {
    baseline: i64,
    replace: bool,
    ors: Vec<FlagOr>,
}

struct ScriptException {
    network: i64,
    hash: Vec<u8>,
    value: i64,
}

fn parse_script_flags(block: &Block) -> Option<ScriptFlags> {
    let mut seen = ScriptFlagSeen::default();
    walk_script_flags_block(block, &mut seen, None);
    if !seen.lookup || seen.baseline.is_empty() || seen.ors.is_empty() {
        return None;
    }
    let mut baseline = 0i64;
    for name in &seen.baseline {
        baseline |= script_flag_value(name)?;
    }
    Some(ScriptFlags {
        baseline,
        replace: seen.replace,
        ors: seen.ors,
    })
}

#[derive(Default)]
struct ScriptFlagSeen {
    baseline: Vec<String>,
    replace: bool,
    ors: Vec<FlagOr>,
    lookup: bool,
}

fn walk_script_flags_block(block: &Block, seen: &mut ScriptFlagSeen, fork: Option<&str>) {
    for stmt in &block.stmts {
        match stmt {
            Stmt::Local(local) => {
                if pat_is_ident(&local.pat, "flags") {
                    if let Some(init) = &local.init {
                        seen.baseline = bitor_paths(&init.expr);
                    }
                }
                if let Some(init) = &local.init {
                    walk_script_flags_expr(&init.expr, seen, fork);
                }
            }
            Stmt::Expr(expr, _) => walk_script_flags_expr(expr, seen, fork),
            Stmt::Item(_) | Stmt::Macro(_) => {}
        }
    }
}

fn walk_script_flags_expr(expr: &Expr, seen: &mut ScriptFlagSeen, fork: Option<&str>) {
    match expr {
        Expr::If(iff) => {
            let nested = fork_name(&iff.cond).or(fork.map(str::to_string));
            walk_script_flags_expr(&iff.cond, seen, fork);
            walk_script_flags_block(&iff.then_branch, seen, nested.as_deref());
            if let Some((_, else_branch)) = &iff.else_branch {
                walk_script_flags_expr(else_branch, seen, fork);
            }
        }
        Expr::Let(let_expr) => {
            if expr_is_call(&let_expr.expr, "script_flag_exceptions_lookup") {
                seen.lookup = true;
            }
            walk_script_flags_expr(&let_expr.expr, seen, fork);
        }
        Expr::Assign(assign) => {
            if path_is(&assign.left, "flags") && path_is(&assign.right, "v") {
                seen.replace = true;
            }
            walk_script_flags_expr(&assign.left, seen, fork);
            walk_script_flags_expr(&assign.right, seen, fork);
        }
        Expr::Binary(bin) => {
            if matches!(bin.op, syn::BinOp::BitOrAssign(_))
                && path_is(&bin.left, "flags")
                && let Some(fork) = fork
                && let Some(bit) = lit_i64(&bin.right)
            {
                seen.ors.push(FlagOr {
                    fork: fork.to_string(),
                    bit,
                });
            }
            walk_script_flags_expr(&bin.left, seen, fork);
            walk_script_flags_expr(&bin.right, seen, fork);
        }
        Expr::Call(call) => {
            if call_ends(&call.func, "script_flag_exceptions_lookup") {
                seen.lookup = true;
            }
            for arg in &call.args {
                walk_script_flags_expr(arg, seen, fork);
            }
        }
        Expr::MethodCall(call) => {
            walk_script_flags_expr(&call.receiver, seen, fork);
            for arg in &call.args {
                walk_script_flags_expr(arg, seen, fork);
            }
        }
        Expr::Block(block) => walk_script_flags_block(&block.block, seen, fork),
        Expr::Unary(unary) => walk_script_flags_expr(&unary.expr, seen, fork),
        Expr::Reference(reference) => walk_script_flags_expr(&reference.expr, seen, fork),
        Expr::Paren(paren) => walk_script_flags_expr(&paren.expr, seen, fork),
        Expr::Group(group) => walk_script_flags_expr(&group.expr, seen, fork),
        _ => {}
    }
}

fn pat_is_ident(pat: &syn::Pat, name: &str) -> bool {
    let syn::Pat::Ident(ident) = pat else {
        return false;
    };
    ident.ident == name
}

fn bitor_paths(expr: &Expr) -> Vec<String> {
    match expr {
        Expr::Binary(bin) if matches!(bin.op, syn::BinOp::BitOr(_)) => {
            let mut names = bitor_paths(&bin.left);
            names.extend(bitor_paths(&bin.right));
            names
        }
        Expr::Path(path) => vec![path_to_string(&path.path)],
        _ => Vec::new(),
    }
}

fn fork_name(expr: &Expr) -> Option<String> {
    let Expr::MethodCall(call) = expr else {
        return None;
    };
    if call.method != "is_fork_active" {
        return None;
    }
    call.args.iter().find_map(|arg| {
        let Expr::Path(path) = arg else {
            return None;
        };
        path_to_string(&path.path)
            .rsplit("::")
            .next()
            .map(str::to_string)
    })
}

fn script_flag_value(name: &str) -> Option<i64> {
    let base = name.rsplit("::").next().unwrap_or(name);
    if !crate::parser::spec_expr::consensus_workspace_present() {
        return None;
    }
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../blvm-consensus/src/script/flags.rs");
    let src = std::fs::read_to_string(path).ok()?;
    let file = syn::parse_file(&src).ok()?;
    for item in file.items {
        let syn::Item::Const(item) = item else {
            continue;
        };
        if item.ident == base {
            return eval_flag_bits(&item.expr);
        }
    }
    None
}

fn eval_flag_bits(expr: &Expr) -> Option<i64> {
    if let Some(value) = lit_i64(expr) {
        return Some(value);
    }
    let Expr::Binary(bin) = expr else {
        return None;
    };
    let left = eval_flag_bits(&bin.left)?;
    let right = eval_flag_bits(&bin.right)?;
    match bin.op {
        syn::BinOp::BitOr(_) => Some(left | right),
        syn::BinOp::Shl(_) if (0..63).contains(&right) => Some(left << right),
        _ => None,
    }
}

fn script_flag_table() -> Option<Vec<ScriptException>> {
    if !crate::parser::spec_expr::consensus_workspace_present() {
        return None;
    }
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../blvm-consensus/src/block/script_cache.rs");
    let src = std::fs::read_to_string(path).ok()?;
    let file = syn::parse_file(&src).ok()?;
    let mut hexes = std::collections::HashMap::<String, Vec<u8>>::new();
    let mut rows = Vec::new();
    for item in &file.items {
        match item {
            syn::Item::Static(item) => {
                if let Some(bytes) = static_rpc_hash(&item.expr) {
                    hexes.insert(item.ident.to_string(), bytes);
                }
            }
            syn::Item::Fn(func) if func.sig.ident == "script_flag_exceptions_lookup" => {
                collect_exception_rows(&func.block, &mut rows);
            }
            _ => {}
        }
    }
    let mut out = Vec::new();
    for (network, name, value) in rows {
        out.push(ScriptException {
            network,
            hash: hexes.get(&name)?.clone(),
            value,
        });
    }
    if out.is_empty() { None } else { Some(out) }
}

fn static_rpc_hash(expr: &Expr) -> Option<Vec<u8>> {
    let mut found = None;
    find_hex_lit(expr, &mut found);
    let text = found?;
    if text.len() != 64 || text.len() % 2 != 0 {
        return None;
    }
    let mut bytes = Vec::new();
    let chars: Vec<u8> = text.bytes().collect();
    for pair in chars.chunks(2) {
        let hi = hex_val(pair[0])?;
        let lo = hex_val(pair[1])?;
        bytes.push((hi << 4) | lo);
    }
    bytes.reverse();
    if bytes.len() == 32 { Some(bytes) } else { None }
}

fn find_hex_lit(expr: &Expr, found: &mut Option<String>) {
    if found.is_some() {
        return;
    }
    match expr {
        Expr::Lit(lit) => {
            if let syn::Lit::Str(text) = &lit.lit {
                if text.value().len() == 64 {
                    *found = Some(text.value());
                }
            }
        }
        Expr::Call(call) => {
            for arg in &call.args {
                find_hex_lit(arg, found);
            }
        }
        Expr::Closure(closure) => find_hex_lit(&closure.body, found),
        Expr::MethodCall(call) => {
            find_hex_lit(&call.receiver, found);
            for arg in &call.args {
                find_hex_lit(arg, found);
            }
        }
        Expr::Block(block) => {
            for stmt in &block.block.stmts {
                if let Stmt::Expr(expr, _) = stmt {
                    find_hex_lit(expr, found);
                }
            }
        }
        _ => {}
    }
}

fn hex_val(byte: u8) -> Option<u8> {
    match byte {
        b'0'..=b'9' => Some(byte - b'0'),
        b'a'..=b'f' => Some(byte - b'a' + 10),
        b'A'..=b'F' => Some(byte - b'A' + 10),
        _ => None,
    }
}

fn collect_exception_rows(block: &Block, rows: &mut Vec<(i64, String, i64)>) {
    for stmt in &block.stmts {
        let Stmt::Expr(expr, _) = stmt else {
            continue;
        };
        let Expr::Match(matched) = expr else {
            continue;
        };
        for arm in &matched.arms {
            let Some(network) = network_tag(&arm.pat) else {
                continue;
            };
            collect_exception_arm(&arm.body, network, rows);
        }
    }
}

fn network_tag(pat: &syn::Pat) -> Option<i64> {
    let syn::Pat::Path(path) = pat else {
        return None;
    };
    match path_to_string(&path.path).rsplit("::").next()? {
        "Mainnet" => Some(1),
        "Testnet" => Some(2),
        _ => None,
    }
}

fn collect_exception_arm(expr: &Expr, network: i64, rows: &mut Vec<(i64, String, i64)>) {
    if let Expr::Block(block) = expr {
        for stmt in &block.block.stmts {
            if let Stmt::Expr(inner, _) = stmt {
                collect_exception_arm(inner, network, rows);
            }
        }
        return;
    }
    let Expr::If(iff) = expr else {
        return;
    };
    if let Some((name, value)) = exception_arm(&iff.cond, &iff.then_branch) {
        rows.push((network, name, value));
    }
    if let Some((_, else_branch)) = &iff.else_branch {
        collect_exception_arm(else_branch, network, rows);
    }
}

fn exception_arm(cond: &Expr, then_branch: &Block) -> Option<(String, i64)> {
    let Expr::Binary(bin) = cond else {
        return None;
    };
    if !matches!(bin.op, syn::BinOp::Eq(_)) {
        return None;
    }
    let name = static_path_name(&bin.right).or_else(|| static_path_name(&bin.left))?;
    let Stmt::Expr(expr, _) = then_branch.stmts.first()? else {
        return None;
    };
    let expr = match expr {
        Expr::Return(ret) => ret.expr.as_deref()?,
        other => other,
    };
    let Expr::Call(call) = expr else {
        return None;
    };
    if !call_ends(&call.func, "Some") || call.args.len() != 1 {
        return None;
    }
    Some((name, eval_flag_bits(&call.args[0])?))
}

fn static_path_name(expr: &Expr) -> Option<String> {
    let expr = match expr {
        Expr::Reference(reference) => &*reference.expr,
        other => other,
    };
    let expr = match expr {
        Expr::Unary(unary) if matches!(unary.op, syn::UnOp::Deref(_)) => &*unary.expr,
        other => other,
    };
    let Expr::Path(path) = expr else {
        return None;
    };
    path_to_string(&path.path)
        .rsplit("::")
        .next()
        .map(str::to_string)
}

struct OpDup {
    gate: Option<i64>,
    empty_push: bool,
}

/// The `OP_DUP` arm: copy `stack.last()`, or push an empty element. A leading
/// `stack.len() < N` reject is the census length gate.
fn parse_op_dup(block: &Block) -> Option<OpDup> {
    let (gate, dup) = match block.stmts.as_slice() {
        [gate, dup] => (Some(dup_gate(gate)?), dup),
        [dup] => (None, dup),
        _ => return None,
    };
    let Stmt::Expr(expr, None) = dup else {
        return None;
    };
    let Expr::If(iff) = expr else {
        return None;
    };
    let Expr::Let(binder) = &*iff.cond else {
        return None;
    };
    if !pat_some_item(&binder.pat) || !stack_last_cloned(&binder.expr) {
        return None;
    }
    let empty_push = dup_then(&iff.then_branch)?;
    let else_body = &iff.else_branch.as_ref()?.1;
    if !ok_false_expr(else_body) {
        return None;
    }
    Some(OpDup { gate, empty_push })
}

struct OpSwap {
    bound: i64,
    push_top: [bool; 2],
}

/// The `OP_SWAP` arm: pop `top` then `second`, then push those two names.
/// The bound is the `stack.len() >= N` gate. Each push is one of those names.
fn parse_op_swap(block: &Block) -> Option<OpSwap> {
    let [stmt] = block.stmts.as_slice() else {
        return None;
    };
    let Stmt::Expr(Expr::If(iff), None) = stmt else {
        return None;
    };
    let bound = stack_len_ge(&iff.cond)?;
    let else_body = &iff.else_branch.as_ref()?.1;
    if !ok_false_expr(else_body) {
        return None;
    }
    let [top, second, push_0, push_1, ok] = iff.then_branch.stmts.as_slice() else {
        return None;
    };
    if !pop_unwrap_binding(top, "top") || !pop_unwrap_binding(second, "second") {
        return None;
    }
    let Stmt::Expr(ok_expr, None) = ok else {
        return None;
    };
    if !ok_bool_expr(ok_expr, true) {
        return None;
    }
    Some(OpSwap {
        bound,
        push_top: [stack_push_top(push_0)?, stack_push_top(push_1)?],
    })
}

fn stack_len_ge(expr: &Expr) -> Option<i64> {
    let Expr::Binary(bin) = expr else {
        return None;
    };
    if !matches!(bin.op, syn::BinOp::Ge(_)) {
        return None;
    }
    let Expr::MethodCall(call) = &*bin.left else {
        return None;
    };
    if call.method != "len" || !call.args.is_empty() || !path_ends_recv(&call.receiver, "stack") {
        return None;
    }
    lit_i64(&bin.right)
}

fn pop_unwrap_binding(stmt: &Stmt, name: &str) -> bool {
    let Stmt::Local(local) = stmt else {
        return false;
    };
    let syn::Pat::Ident(pat) = &local.pat else {
        return false;
    };
    if pat.ident != name {
        return false;
    }
    let Some(init) = &local.init else {
        return false;
    };
    let Expr::MethodCall(unwrap) = peel_paren(&init.expr) else {
        return false;
    };
    unwrap.method == "unwrap" && unwrap.args.is_empty() && stack_pop(&unwrap.receiver)
}

fn stack_push_top(stmt: &Stmt) -> Option<bool> {
    let Stmt::Expr(Expr::MethodCall(call), Some(_)) = stmt else {
        return None;
    };
    if call.method != "push" || !path_ends_recv(&call.receiver, "stack") {
        return None;
    }
    let arg = call.args.first()?;
    let Expr::Path(path) = arg else {
        return None;
    };
    match path
        .path
        .segments
        .last()
        .map(|seg| seg.ident.to_string())
        .as_deref()
    {
        Some("top") => Some(true),
        Some("second") => Some(false),
        _ => None,
    }
}

struct Op2Dup {
    bound: i64,
    push_top: [bool; 2],
}

/// The `OP_2DUP` arm: copy `stack[len - 1]` into `top` and `stack[len - 2]`
/// into `second`, then push those names. The bound is `stack.len() >= N`.
fn parse_op_2dup(block: &Block) -> Option<Op2Dup> {
    let [stmt] = block.stmts.as_slice() else {
        return None;
    };
    let Stmt::Expr(Expr::If(iff), None) = stmt else {
        return None;
    };
    let bound = stack_len_ge(&iff.cond)?;
    let else_body = &iff.else_branch.as_ref()?.1;
    if !ok_false_expr(else_body) {
        return None;
    }
    let [top, second, push_0, push_1, ok] = iff.then_branch.stmts.as_slice() else {
        return None;
    };
    if !index_clone_binding(top, "top", 1) || !index_clone_binding(second, "second", 2) {
        return None;
    }
    let Stmt::Expr(ok_expr, None) = ok else {
        return None;
    };
    if !ok_bool_expr(ok_expr, true) {
        return None;
    }
    Some(Op2Dup {
        bound,
        push_top: [stack_push_top(push_0)?, stack_push_top(push_1)?],
    })
}

fn index_clone_binding(stmt: &Stmt, name: &str, depth: i64) -> bool {
    let Stmt::Local(local) = stmt else {
        return false;
    };
    let syn::Pat::Ident(pat) = &local.pat else {
        return false;
    };
    if pat.ident != name {
        return false;
    }
    let Some(init) = &local.init else {
        return false;
    };
    let Expr::MethodCall(cloned) = peel_paren(&init.expr) else {
        return false;
    };
    if cloned.method != "clone" || !cloned.args.is_empty() {
        return false;
    }
    let Expr::Index(index) = peel_paren(&cloned.receiver) else {
        return false;
    };
    if !path_ends_recv(&index.expr, "stack") {
        return false;
    }
    let Expr::Binary(bin) = peel_paren(&index.index) else {
        return false;
    };
    if !matches!(bin.op, syn::BinOp::Sub(_)) {
        return false;
    }
    let Expr::MethodCall(len) = &*bin.left else {
        return false;
    };
    len.method == "len"
        && len.args.is_empty()
        && path_ends_recv(&len.receiver, "stack")
        && lit_i64(&bin.right) == Some(depth)
}

struct Op2Rot {
    bound: i64,
    push_sixth: [bool; 2],
}

/// The `OP_2ROT` arm: remove `stack.len() - 6` into `sixth` and `stack.len() - 5`
/// into `fifth`, then push those names. The bound is `stack.len() >= N`.
fn parse_op_2rot(block: &Block) -> Option<Op2Rot> {
    let [stmt] = block.stmts.as_slice() else {
        return None;
    };
    let Stmt::Expr(Expr::If(iff), None) = stmt else {
        return None;
    };
    let bound = stack_len_ge(&iff.cond)?;
    let else_body = &iff.else_branch.as_ref()?.1;
    if !ok_false_expr(else_body) {
        return None;
    }
    let [sixth, fifth, push_0, push_1, ok] = iff.then_branch.stmts.as_slice() else {
        return None;
    };
    if !remove_at_depth(sixth, "sixth", 6) || !remove_at_depth(fifth, "fifth", 5) {
        return None;
    }
    let Stmt::Expr(ok_expr, None) = ok else {
        return None;
    };
    if !ok_bool_expr(ok_expr, true) {
        return None;
    }
    Some(Op2Rot {
        bound,
        push_sixth: [stack_push_sixth(push_0)?, stack_push_sixth(push_1)?],
    })
}

fn remove_at_depth(stmt: &Stmt, name: &str, depth: i64) -> bool {
    let Stmt::Local(local) = stmt else {
        return false;
    };
    let syn::Pat::Ident(pat) = &local.pat else {
        return false;
    };
    if pat.ident != name {
        return false;
    }
    let Some(init) = &local.init else {
        return false;
    };
    let Expr::MethodCall(removed) = peel_paren(&init.expr) else {
        return false;
    };
    if removed.method != "remove" || !path_ends_recv(&removed.receiver, "stack") {
        return false;
    }
    let Some(arg) = removed.args.first() else {
        return false;
    };
    let Expr::Binary(bin) = peel_paren(arg) else {
        return false;
    };
    if !matches!(bin.op, syn::BinOp::Sub(_)) {
        return false;
    }
    let Expr::MethodCall(len) = &*bin.left else {
        return false;
    };
    len.method == "len"
        && len.args.is_empty()
        && path_ends_recv(&len.receiver, "stack")
        && lit_i64(&bin.right) == Some(depth)
}

fn stack_push_sixth(stmt: &Stmt) -> Option<bool> {
    let Stmt::Expr(Expr::MethodCall(call), Some(_)) = stmt else {
        return None;
    };
    if call.method != "push" || !path_ends_recv(&call.receiver, "stack") {
        return None;
    }
    let arg = call.args.first()?;
    let Expr::Path(path) = arg else {
        return None;
    };
    match path
        .path
        .segments
        .last()
        .map(|seg| seg.ident.to_string())
        .as_deref()
    {
        Some("sixth") => Some(true),
        Some("fifth") => Some(false),
        _ => None,
    }
}

struct Op2Swap {
    bound: i64,
    pushes: [u8; 4],
}

/// The `OP_2SWAP` arm: pop `top`, `second`, `third`, and `fourth`, then push
/// those names. The bound is `stack.len() >= N`.
fn parse_op_2swap(block: &Block) -> Option<Op2Swap> {
    let [stmt] = block.stmts.as_slice() else {
        return None;
    };
    let Stmt::Expr(Expr::If(iff), None) = stmt else {
        return None;
    };
    let bound = stack_len_ge(&iff.cond)?;
    let else_body = &iff.else_branch.as_ref()?.1;
    if !ok_false_expr(else_body) {
        return None;
    }
    let [
        top,
        second,
        third,
        fourth,
        push_0,
        push_1,
        push_2,
        push_3,
        ok,
    ] = iff.then_branch.stmts.as_slice()
    else {
        return None;
    };
    if !pop_unwrap_binding(top, "top")
        || !pop_unwrap_binding(second, "second")
        || !pop_unwrap_binding(third, "third")
        || !pop_unwrap_binding(fourth, "fourth")
    {
        return None;
    }
    let Stmt::Expr(ok_expr, None) = ok else {
        return None;
    };
    if !ok_bool_expr(ok_expr, true) {
        return None;
    }
    Some(Op2Swap {
        bound,
        pushes: [
            stack_push_slot(push_0)?,
            stack_push_slot(push_1)?,
            stack_push_slot(push_2)?,
            stack_push_slot(push_3)?,
        ],
    })
}

fn stack_push_slot(stmt: &Stmt) -> Option<u8> {
    let Stmt::Expr(Expr::MethodCall(call), Some(_)) = stmt else {
        return None;
    };
    if call.method != "push" || !path_ends_recv(&call.receiver, "stack") {
        return None;
    }
    let arg = call.args.first()?;
    let Expr::Path(path) = arg else {
        return None;
    };
    match path
        .path
        .segments
        .last()
        .map(|seg| seg.ident.to_string())
        .as_deref()
    {
        Some("top") => Some(0),
        Some("second") => Some(1),
        Some("third") => Some(2),
        Some("fourth") => Some(3),
        _ => None,
    }
}

struct Op3Dup {
    bound: i64,
    pushes: [u8; 3],
}

/// The `OP_3DUP` arm: copy `stack[len - 1]`, `stack[len - 2]`, and
/// `stack[len - 3]` into `top`, `second`, and `third`, then push those names.
/// The bound is `stack.len() >= N`.
fn parse_op_3dup(block: &Block) -> Option<Op3Dup> {
    let [stmt] = block.stmts.as_slice() else {
        return None;
    };
    let Stmt::Expr(Expr::If(iff), None) = stmt else {
        return None;
    };
    let bound = stack_len_ge(&iff.cond)?;
    let else_body = &iff.else_branch.as_ref()?.1;
    if !ok_false_expr(else_body) {
        return None;
    }
    let [top, second, third, push_0, push_1, push_2, ok] = iff.then_branch.stmts.as_slice() else {
        return None;
    };
    if !index_clone_binding(top, "top", 1)
        || !index_clone_binding(second, "second", 2)
        || !index_clone_binding(third, "third", 3)
    {
        return None;
    }
    let Stmt::Expr(ok_expr, None) = ok else {
        return None;
    };
    if !ok_bool_expr(ok_expr, true) {
        return None;
    }
    Some(Op3Dup {
        bound,
        pushes: [
            stack_push_triple(push_0)?,
            stack_push_triple(push_1)?,
            stack_push_triple(push_2)?,
        ],
    })
}

fn stack_push_triple(stmt: &Stmt) -> Option<u8> {
    let slot = stack_push_slot(stmt)?;
    if slot > 2 { None } else { Some(slot) }
}

struct OpRot {
    bound: i64,
    pushes: [u8; 3],
}

/// The `OP_ROT` arm: pop `top`, `second`, and `third`, then push those names.
/// The bound is `stack.len() >= N`.
fn parse_op_rot(block: &Block) -> Option<OpRot> {
    let [stmt] = block.stmts.as_slice() else {
        return None;
    };
    let Stmt::Expr(Expr::If(iff), None) = stmt else {
        return None;
    };
    let bound = stack_len_ge(&iff.cond)?;
    let else_body = &iff.else_branch.as_ref()?.1;
    if !ok_false_expr(else_body) {
        return None;
    }
    let [top, second, third, push_0, push_1, push_2, ok] = iff.then_branch.stmts.as_slice() else {
        return None;
    };
    if !pop_unwrap_binding(top, "top")
        || !pop_unwrap_binding(second, "second")
        || !pop_unwrap_binding(third, "third")
    {
        return None;
    }
    let Stmt::Expr(ok_expr, None) = ok else {
        return None;
    };
    if !ok_bool_expr(ok_expr, true) {
        return None;
    }
    Some(OpRot {
        bound,
        pushes: [
            stack_push_triple(push_0)?,
            stack_push_triple(push_1)?,
            stack_push_triple(push_2)?,
        ],
    })
}

struct OpTuck {
    bound: i64,
    pushes: [u8; 3],
}

/// The `OP_TUCK` arm: pop `top` and `second`, then push those names. A
/// `.clone()` on a push is the same item. The bound is `stack.len() >= N`.
fn parse_op_tuck(block: &Block) -> Option<OpTuck> {
    let [stmt] = block.stmts.as_slice() else {
        return None;
    };
    let Stmt::Expr(Expr::If(iff), None) = stmt else {
        return None;
    };
    let bound = stack_len_ge(&iff.cond)?;
    let else_body = &iff.else_branch.as_ref()?.1;
    if !ok_false_expr(else_body) {
        return None;
    }
    let [top, second, push_0, push_1, push_2, ok] = iff.then_branch.stmts.as_slice() else {
        return None;
    };
    if !pop_unwrap_binding(top, "top") || !pop_unwrap_binding(second, "second") {
        return None;
    }
    let Stmt::Expr(ok_expr, None) = ok else {
        return None;
    };
    if !ok_bool_expr(ok_expr, true) {
        return None;
    }
    Some(OpTuck {
        bound,
        pushes: [
            stack_push_pair(push_0)?,
            stack_push_pair(push_1)?,
            stack_push_pair(push_2)?,
        ],
    })
}

fn stack_push_pair(stmt: &Stmt) -> Option<u8> {
    let Stmt::Expr(Expr::MethodCall(call), Some(_)) = stmt else {
        return None;
    };
    if call.method != "push" || !path_ends_recv(&call.receiver, "stack") {
        return None;
    }
    let arg = push_item(call.args.first()?)?;
    let Expr::Path(path) = arg else {
        return None;
    };
    match path
        .path
        .segments
        .last()
        .map(|seg| seg.ident.to_string())
        .as_deref()
    {
        Some("top") => Some(0),
        Some("second") => Some(1),
        _ => None,
    }
}

fn push_item(expr: &Expr) -> Option<&Expr> {
    let expr = peel_paren(expr);
    if let Expr::MethodCall(call) = expr {
        if call.method == "clone" && call.args.is_empty() {
            return Some(peel_paren(&call.receiver));
        }
    }
    Some(expr)
}

struct OpNip {
    bound: i64,
    push_top: bool,
}

/// The `OP_NIP` arm: pop `top`, discard the next pop, then push `top` or
/// `second`. `second` is that discarded item. The bound is `stack.len() >= N`.
fn parse_op_nip(block: &Block) -> Option<OpNip> {
    let [stmt] = block.stmts.as_slice() else {
        return None;
    };
    let Stmt::Expr(Expr::If(iff), None) = stmt else {
        return None;
    };
    let bound = stack_len_ge(&iff.cond)?;
    let else_body = &iff.else_branch.as_ref()?.1;
    if !ok_false_expr(else_body) {
        return None;
    }
    let [top, dropped, push, ok] = iff.then_branch.stmts.as_slice() else {
        return None;
    };
    if !pop_unwrap_binding(top, "top") || !bare_stack_pop(dropped) {
        return None;
    }
    let Stmt::Expr(ok_expr, None) = ok else {
        return None;
    };
    if !ok_bool_expr(ok_expr, true) {
        return None;
    }
    Some(OpNip {
        bound,
        push_top: stack_push_pair(push)? == 0,
    })
}

fn bare_stack_pop(stmt: &Stmt) -> bool {
    let Stmt::Expr(expr, Some(_)) = stmt else {
        return false;
    };
    stack_pop(expr)
}

struct OpIfDup {
    gate: Option<i64>,
    empty_push: bool,
}

/// The `OP_IFDUP` arm: copy `stack.last()` when `cast_to_bool` of that item is
/// true. A leading `stack.len() < N` reject is the census length gate. An
/// empty push is not the item.
fn parse_op_ifdup(block: &Block) -> Option<OpIfDup> {
    let (gate, dup) = match block.stmts.as_slice() {
        [gate, dup] => (Some(dup_gate(gate)?), dup),
        [dup] => (None, dup),
        _ => return None,
    };
    let Stmt::Expr(Expr::If(iff), None) = dup else {
        return None;
    };
    let Expr::Let(binder) = &*iff.cond else {
        return None;
    };
    if !pat_some_item(&binder.pat) || !stack_last_cloned(&binder.expr) {
        return None;
    }
    let [guard, ok] = iff.then_branch.stmts.as_slice() else {
        return None;
    };
    let empty_push = ifdup_push(guard)?;
    let Stmt::Expr(ok_expr, None) = ok else {
        return None;
    };
    if !ok_bool_expr(ok_expr, true) {
        return None;
    }
    let else_body = &iff.else_branch.as_ref()?.1;
    if !ok_false_expr(else_body) {
        return None;
    }
    Some(OpIfDup { gate, empty_push })
}

fn ifdup_push(stmt: &Stmt) -> Option<bool> {
    let Stmt::Expr(Expr::If(iff), _) = stmt else {
        return None;
    };
    if iff.else_branch.is_some() || !cast_to_bool_of_item(&iff.cond) {
        return None;
    }
    let [push] = iff.then_branch.stmts.as_slice() else {
        return None;
    };
    let Stmt::Expr(expr, Some(_)) = push else {
        return None;
    };
    dup_push(expr)
}

fn cast_to_bool_of_item(expr: &Expr) -> bool {
    let Expr::Call(call) = expr else {
        return false;
    };
    if !call_ends(&call.func, "cast_to_bool") || call.args.len() != 1 {
        return false;
    }
    let Expr::Reference(refer) = &call.args[0] else {
        return false;
    };
    path_ends(&refer.expr, "item")
}

struct OpPick {
    gate: Option<i64>,
    max_num: i64,
    minimal_bit: i64,
    /// Production `len - offset - n` after the inactive cfg is dropped.
    offset: i64,
}

/// The `OP_PICK` arm. The kept production block copies `stack[len - offset - n]`.
fn parse_op_pick(block: &Block) -> Option<OpPick> {
    let (gate, arm) = match block.stmts.as_slice() {
        [gate, arm] => (Some(dup_gate(gate)?), arm),
        [arm] => (None, arm),
        _ => return None,
    };
    let Stmt::Expr(Expr::If(iff), None) = arm else {
        return None;
    };
    if !pop_some_named(iff, "n_bytes") {
        return None;
    }
    let else_body = &iff.else_branch.as_ref()?.1;
    if !ok_false_expr(else_body) {
        return None;
    }
    let stmts = iff.then_branch.stmts.as_slice();
    let (minimal, decode, range, n_let, len_let, prod, ok) = match stmts {
        [minimal, decode, range, n_let, len_let, prod, ok] => {
            (minimal, decode, range, n_let, len_let, prod, ok)
        }
        [minimal, decode, range, n_let, len_let, prod, alt, ok] => {
            alt_pick(alt)?;
            (minimal, decode, range, n_let, len_let, prod, ok)
        }
        _ => return None,
    };
    if !minimaldata_reject(minimal) || !pick_range_reject(range) || !cast_local(n_let, "n", "n_val")
    {
        return None;
    }
    if !len_of_stack(len_let) {
        return None;
    }
    let max_num = decode_named(decode, "n_val", "n_bytes")?;
    let offset = kept_production_pick(prod)?;
    let Stmt::Expr(ok_expr, None) = ok else {
        return None;
    };
    if !ok_bool_expr(ok_expr, true) {
        return None;
    }
    Some(OpPick {
        gate,
        max_num,
        minimal_bit: minimaldata_bit()?,
        offset,
    })
}

struct OpRoll {
    gate: Option<i64>,
    max_num: i64,
    minimal_bit: i64,
    /// Production `len - offset - n` after the inactive cfg is dropped.
    offset: i64,
}

/// The `OP_ROLL` arm. The kept production block removes `stack[len - offset - n]`
/// and pushes that item.
fn parse_op_roll(block: &Block) -> Option<OpRoll> {
    let (gate, arm) = match block.stmts.as_slice() {
        [gate, arm] => (Some(dup_gate(gate)?), arm),
        [arm] => (None, arm),
        _ => return None,
    };
    let Stmt::Expr(Expr::If(iff), None) = arm else {
        return None;
    };
    if !pop_some_named(iff, "n_bytes") {
        return None;
    }
    let else_body = &iff.else_branch.as_ref()?.1;
    if !ok_false_expr(else_body) {
        return None;
    }
    let stmts = iff.then_branch.stmts.as_slice();
    let (minimal, decode, range, n_let, len_let, prod, ok) = match stmts {
        [minimal, decode, range, n_let, len_let, prod, ok] => {
            (minimal, decode, range, n_let, len_let, prod, ok)
        }
        [minimal, decode, range, n_let, len_let, prod, alt, ok] => {
            alt_roll(alt)?;
            (minimal, decode, range, n_let, len_let, prod, ok)
        }
        _ => return None,
    };
    if !minimaldata_reject(minimal) || !pick_range_reject(range) || !cast_local(n_let, "n", "n_val")
    {
        return None;
    }
    if !len_of_stack(len_let) {
        return None;
    }
    let max_num = decode_named(decode, "n_val", "n_bytes")?;
    let offset = kept_production_roll(prod)?;
    let Stmt::Expr(ok_expr, None) = ok else {
        return None;
    };
    if !ok_bool_expr(ok_expr, true) {
        return None;
    }
    Some(OpRoll {
        gate,
        max_num,
        minimal_bit: minimaldata_bit()?,
        offset,
    })
}

fn kept_production_roll(stmt: &Stmt) -> Option<i64> {
    let Stmt::Expr(Expr::Block(block), _) = stmt else {
        return None;
    };
    production_roll(&block.block)
}

fn production_roll(block: &Block) -> Option<i64> {
    let [idx_let, item_let, push] = block.stmts.as_slice() else {
        return None;
    };
    let idx_init = local_init(idx_let, "idx")?;
    let (base, offset) = minus_named(idx_init, "n")?;
    if !path_ends(base, "len") {
        return None;
    }
    let item_init = local_init(item_let, "item")?;
    if !stack_remove(item_init, "idx") || !push_named(push, "item") {
        return None;
    }
    Some(offset)
}

/// The inactive `cfg(not(production))` copy of the roll.
fn alt_roll(stmt: &Stmt) -> Option<i64> {
    let Stmt::Expr(Expr::Block(block), _) = stmt else {
        return None;
    };
    let [item_let, push] = block.block.stmts.as_slice() else {
        return None;
    };
    let init = local_init(item_let, "item")?;
    let Expr::MethodCall(call) = peel_paren(init) else {
        return None;
    };
    if call.method != "remove" || call.args.len() != 1 || !path_ends_recv(&call.receiver, "stack") {
        return None;
    }
    if !push_named(push, "item") {
        return None;
    }
    let (base, offset) = minus_named(&call.args[0], "n")?;
    if !is_stack_len(base) {
        return None;
    }
    Some(offset)
}

fn stack_remove(expr: &Expr, index: &str) -> bool {
    let Expr::MethodCall(call) = peel_paren(expr) else {
        return false;
    };
    call.method == "remove"
        && call.args.len() == 1
        && path_ends_recv(&call.receiver, "stack")
        && path_ends(&call.args[0], index)
}

struct OpChecksigAdd {
    min_stack: i64,
    max_num: i64,
    minimal_bit: i64,
    addend: i64,
}

/// The `OP_CHECKSIGADD` arm. The addend is the literal in `n + addend`.
fn parse_op_checksigadd(block: &Block) -> Option<OpChecksigAdd> {
    let [
        version,
        short,
        pubkey,
        n_bytes,
        signature,
        minimal,
        decode,
        matched,
    ] = block.stmts.as_slice()
    else {
        return None;
    };
    if !not_tapscript_reject(version) || !pop_unwrap(pubkey, "pubkey_bytes") {
        return None;
    }
    if !pop_unwrap(n_bytes, "n_bytes") || !pop_unwrap(signature, "signature_bytes") {
        return None;
    }
    if !minimaldata_reject(minimal) {
        return None;
    }
    let min_stack = short_stack_err(short)?;
    let max_num = decode_named(decode, "n", "n_bytes")?;
    let addend = checksigadd_match(matched)?;
    Some(OpChecksigAdd {
        min_stack,
        max_num,
        minimal_bit: minimaldata_bit()?,
        addend,
    })
}

fn not_tapscript_reject(stmt: &Stmt) -> bool {
    let Stmt::Expr(Expr::If(iff), _) = stmt else {
        return false;
    };
    if iff.else_branch.is_some() || !returns_err(&iff.then_branch) {
        return false;
    }
    let Expr::Binary(bin) = peel_paren(&iff.cond) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Ne(_))
        && path_ends(&bin.left, "sigversion")
        && path_ends(&bin.right, "Tapscript")
}

fn short_stack_err(stmt: &Stmt) -> Option<i64> {
    let Stmt::Expr(Expr::If(iff), _) = stmt else {
        return None;
    };
    if iff.else_branch.is_some() || !returns_err(&iff.then_branch) {
        return None;
    }
    stack_len_lt(&iff.cond)
}

fn pop_unwrap(stmt: &Stmt, name: &str) -> bool {
    let Some(init) = local_init(stmt, name) else {
        return false;
    };
    let Expr::MethodCall(unwrap) = peel_paren(init) else {
        return false;
    };
    if unwrap.method != "unwrap" || !unwrap.args.is_empty() {
        return false;
    }
    let Expr::MethodCall(pop) = &*unwrap.receiver else {
        return false;
    };
    pop.method == "pop" && pop.args.is_empty() && path_ends_recv(&pop.receiver, "stack")
}

fn checksigadd_match(stmt: &Stmt) -> Option<i64> {
    let Stmt::Expr(Expr::Match(matched), _) = stmt else {
        return None;
    };
    let Expr::Try(tried) = peel_paren(&matched.expr) else {
        return None;
    };
    let Expr::Call(call) = peel_paren(&tried.expr) else {
        return None;
    };
    if !call_ends(&call.func, "eval_checksig_tapscript") || call.args.len() != 4 {
        return None;
    }
    if !path_ends(&call.args[0], "ctx") || !path_ends(&call.args[1], "flags") {
        return None;
    }
    if !ref_named(&call.args[2], "signature_bytes") || !ref_named(&call.args[3], "pubkey_bytes") {
        return None;
    }
    let [none_arm, some_arm] = matched.arms.as_slice() else {
        return None;
    };
    if none_arm.guard.is_some() || some_arm.guard.is_some() {
        return None;
    }
    if !pat_is_none(&none_arm.pat) || !ok_bool_expr(&none_arm.body, false) {
        return None;
    }
    if !pat_some_named(&some_arm.pat, "ok") {
        return None;
    }
    some_push_addend(&some_arm.body)
}

fn ref_named(expr: &Expr, name: &str) -> bool {
    let Expr::Reference(refer) = expr else {
        return false;
    };
    path_ends(&refer.expr, name)
}

fn some_push_addend(expr: &Expr) -> Option<i64> {
    let Expr::Block(block) = expr else {
        return None;
    };
    let [pushed_let, push, ret] = block.block.stmts.as_slice() else {
        return None;
    };
    let addend = pushed_addend(local_init(pushed_let, "pushed")?)?;
    if !push_encoded(push) {
        return None;
    }
    let Stmt::Expr(ret_expr, _) = ret else {
        return None;
    };
    if !ok_bool_expr(ret_expr, true) {
        return None;
    }
    Some(addend)
}

fn pushed_addend(expr: &Expr) -> Option<i64> {
    let Expr::If(iff) = peel_paren(expr) else {
        return None;
    };
    if !path_ends(&iff.cond, "ok") {
        return None;
    }
    let addend = block_n_plus(&iff.then_branch)?;
    let else_body = iff.else_branch.as_ref()?.1.as_ref();
    if !block_is_path(else_body, "n") {
        return None;
    }
    Some(addend)
}

fn block_n_plus(block: &Block) -> Option<i64> {
    let [stmt] = block.stmts.as_slice() else {
        return None;
    };
    let Stmt::Expr(expr, _) = stmt else {
        return None;
    };
    let Expr::Binary(bin) = peel_paren(expr) else {
        return None;
    };
    if !matches!(bin.op, syn::BinOp::Add(_)) || !path_ends(&bin.left, "n") {
        return None;
    }
    lit_i64(&bin.right)
}

fn block_is_path(expr: &Expr, name: &str) -> bool {
    match expr {
        Expr::Block(block) => {
            let [stmt] = block.block.stmts.as_slice() else {
                return false;
            };
            let Stmt::Expr(inner, _) = stmt else {
                return false;
            };
            path_ends(inner, name)
        }
        other => path_ends(other, name),
    }
}

fn push_encoded(stmt: &Stmt) -> bool {
    let Stmt::Expr(expr, Some(_)) = stmt else {
        return false;
    };
    let Expr::MethodCall(call) = expr else {
        return false;
    };
    if call.method != "push" || call.args.len() != 1 || !path_ends_recv(&call.receiver, "stack") {
        return false;
    }
    let Expr::Call(to_stack) = peel_paren(&call.args[0]) else {
        return false;
    };
    if !call_ends(&to_stack.func, "to_stack_element") || to_stack.args.len() != 1 {
        return false;
    }
    let Expr::Reference(refer) = &to_stack.args[0] else {
        return false;
    };
    let Expr::Call(encode) = peel_paren(&refer.expr) else {
        return false;
    };
    call_ends(&encode.func, "script_num_encode")
        && encode.args.len() == 1
        && path_ends(&encode.args[0], "pushed")
}

struct OpChecksigVerify {
    min_stack: i64,
    ecdsa: String,
}

/// The `OP_CHECKSIGVERIFY` arm. `ecdsa` is `eval_checksig_ecdsa` until the
/// census rename.
fn parse_op_checksigverify(block: &Block) -> Option<OpChecksigVerify> {
    let [stmt] = block.stmts.as_slice() else {
        return None;
    };
    let Stmt::Expr(Expr::If(iff), _) = stmt else {
        return None;
    };
    let min_stack = stack_len_ge(&iff.cond)?;
    let else_body = iff.else_branch.as_ref()?.1.as_ref();
    if !ok_false_expr(else_body) {
        return None;
    }
    let [pubkey, signature, tapscript, empty, tried, ok] = iff.then_branch.stmts.as_slice() else {
        return None;
    };
    if !pop_unwrap(pubkey, "pubkey_bytes") || !pop_unwrap(signature, "signature_bytes") {
        return None;
    }
    if !tapscript_verify(tapscript) || !empty_sig_false(empty) {
        return None;
    }
    let ecdsa = ecdsa_try(tried)?;
    let Stmt::Expr(ok_expr, _) = ok else {
        return None;
    };
    if !ok_named(ok_expr, "is_valid") {
        return None;
    }
    Some(OpChecksigVerify { min_stack, ecdsa })
}

fn tapscript_verify(stmt: &Stmt) -> bool {
    let Stmt::Expr(Expr::If(iff), _) = stmt else {
        return false;
    };
    if iff.else_branch.is_some() || !is_tapscript(&iff.cond) {
        return false;
    }
    let [ret] = iff.then_branch.stmts.as_slice() else {
        return false;
    };
    let Stmt::Expr(Expr::Return(ret_expr), _) = ret else {
        return false;
    };
    let Some(expr) = ret_expr.expr.as_deref() else {
        return false;
    };
    let Expr::Match(matched) = peel_paren(expr) else {
        return false;
    };
    let Expr::Try(tried) = peel_paren(&matched.expr) else {
        return false;
    };
    let Expr::Call(call) = peel_paren(&tried.expr) else {
        return false;
    };
    if !call_ends(&call.func, "eval_checksig_tapscript") || call.args.len() != 4 {
        return false;
    }
    if !path_ends(&call.args[0], "ctx") || !path_ends(&call.args[1], "flags") {
        return false;
    }
    if !ref_named(&call.args[2], "signature_bytes") || !ref_named(&call.args[3], "pubkey_bytes") {
        return false;
    }
    let [some_true, other] = matched.arms.as_slice() else {
        return false;
    };
    some_true.guard.is_none()
        && other.guard.is_none()
        && pat_some_true(&some_true.pat)
        && ok_bool_expr(&some_true.body, true)
        && matches!(other.pat, syn::Pat::Wild(_))
        && ok_bool_expr(&other.body, false)
}

fn is_tapscript(expr: &Expr) -> bool {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Eq(_))
        && path_ends(&bin.left, "sigversion")
        && path_ends(&bin.right, "Tapscript")
}

fn pat_some_true(pat: &syn::Pat) -> bool {
    let syn::Pat::TupleStruct(tuple) = pat else {
        return false;
    };
    if !path_to_string(&tuple.path).ends_with("Some") || tuple.elems.len() != 1 {
        return false;
    }
    let syn::Pat::Lit(lit) = &tuple.elems[0] else {
        return false;
    };
    matches!(&lit.lit, syn::Lit::Bool(bit) if bit.value)
}

fn empty_sig_false(stmt: &Stmt) -> bool {
    let Stmt::Expr(Expr::If(iff), _) = stmt else {
        return false;
    };
    if iff.else_branch.is_some() {
        return false;
    }
    let Expr::MethodCall(call) = peel_paren(&iff.cond) else {
        return false;
    };
    call.method == "is_empty"
        && call.args.is_empty()
        && path_ends_recv(&call.receiver, "signature_bytes")
        && returns_ok_bool(&iff.then_branch, false)
}

fn ecdsa_try(stmt: &Stmt) -> Option<String> {
    let init = local_init(stmt, "is_valid")?;
    let Expr::Try(tried) = peel_paren(init) else {
        return None;
    };
    let Expr::Call(call) = peel_paren(&tried.expr) else {
        return None;
    };
    if call.args.len() != 5 {
        return None;
    }
    if !path_ends(&call.args[0], "ctx") || !path_ends(&call.args[1], "flags") {
        return None;
    }
    if !ref_named(&call.args[2], "signature_bytes") || !ref_named(&call.args[3], "pubkey_bytes") {
        return None;
    }
    if !path_ends(&call.args[4], "redeem_script_for_sighash") {
        return None;
    }
    let name = call_expr_to_name(&call.func).ok()?;
    let base = name.rsplit("::").next()?.to_string();
    if base == "eval_checksig_ecdsa" || base == "eval_checksig_gone" {
        Some(base)
    } else {
        None
    }
}

fn ok_named(expr: &Expr, name: &str) -> bool {
    let Expr::Call(call) = peel_paren(expr) else {
        return false;
    };
    call_ends(&call.func, "Ok") && call.args.len() == 1 && path_ends(&call.args[0], name)
}

enum MerkleCheck {
    Before,
    After,
    None,
}

fn parse_merkle(block: &Block) -> Option<MerkleCheck> {
    let [flag, loop_stmt, tail] = block.stmts.as_slice() else {
        return None;
    };
    if !mutated_false(flag) || !merkle_ok(tail) {
        return None;
    }
    let Stmt::Expr(Expr::While(whl), _) = loop_stmt else {
        return None;
    };
    if !len_gt_one(&whl.cond, "hashes") {
        return None;
    }
    merkle_mode(&whl.body.stmts)
}

fn mutated_false(stmt: &Stmt) -> bool {
    let Some(init) = local_init(stmt, "mutated") else {
        return false;
    };
    is_bool_lit(init, false)
}

fn len_gt_one(expr: &Expr, name: &str) -> bool {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    if !matches!(bin.op, syn::BinOp::Gt(_)) || lit_i64(&bin.right) != Some(1) {
        return false;
    }
    let Expr::MethodCall(call) = peel_paren(&bin.left) else {
        return false;
    };
    call.method == "len" && path_ends_recv(&call.receiver, name)
}

fn merkle_ok(stmt: &Stmt) -> bool {
    let Stmt::Expr(expr, None) = stmt else {
        return false;
    };
    let Expr::Call(ok) = peel_paren(expr) else {
        return false;
    };
    if !call_ends(&ok.func, "Ok") || ok.args.len() != 1 {
        return false;
    }
    let Expr::Tuple(tuple) = peel_paren(&ok.args[0]) else {
        return false;
    };
    if tuple.elems.len() != 2 || !path_ends(&tuple.elems[1], "mutated") {
        return false;
    }
    let Expr::Index(index) = peel_paren(&tuple.elems[0]) else {
        return false;
    };
    path_ends(&index.expr, "hashes") && lit_i64(&index.index) == Some(0)
}

fn merkle_mode(stmts: &[Stmt]) -> Option<MerkleCheck> {
    let mut kinds = Vec::new();
    for stmt in stmts {
        if dup_for(stmt) {
            kinds.push("dup");
        } else if pad_if(stmt) {
            kinds.push("pad");
        } else if next_level_let(stmt) {
            kinds.push("next");
        } else if hash_for(stmt) {
            kinds.push("hash");
        } else if hashes_assign(stmt) {
            kinds.push("assign");
        } else {
            return None;
        }
    }
    match kinds.as_slice() {
        ["dup", "pad", "next", "hash", "assign"] => Some(MerkleCheck::Before),
        ["pad", "dup", "next", "hash", "assign"] => Some(MerkleCheck::After),
        ["pad", "next", "hash", "assign"] => Some(MerkleCheck::None),
        _ => None,
    }
}

fn dup_for(stmt: &Stmt) -> bool {
    let Stmt::Expr(Expr::ForLoop(lp), _) = stmt else {
        return false;
    };
    let Expr::MethodCall(step) = peel_paren(&lp.expr) else {
        return false;
    };
    step.method == "step_by"
        && step.args.len() == 1
        && lit_i64(&step.args[0]) == Some(2)
        && block_sets_mutated(&lp.body)
}

fn block_sets_mutated(block: &Block) -> bool {
    block.stmts.iter().any(|stmt| {
        let Stmt::Expr(Expr::If(iff), _) = stmt else {
            return false;
        };
        assigns_true(&iff.then_branch, "mutated")
    })
}

fn assigns_true(block: &Block, name: &str) -> bool {
    block.stmts.iter().any(|stmt| {
        let Stmt::Expr(Expr::Assign(assign), _) = stmt else {
            return false;
        };
        path_ends(&assign.left, name) && is_bool_lit(&assign.right, true)
    })
}

fn pad_if(stmt: &Stmt) -> bool {
    let Stmt::Expr(Expr::If(iff), _) = stmt else {
        return false;
    };
    odd_len(&iff.cond, "hashes") && pushes_last(&iff.then_branch, "hashes")
}

fn odd_len(expr: &Expr, name: &str) -> bool {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    if !matches!(bin.op, syn::BinOp::Ne(_)) || lit_i64(&bin.right) != Some(0) {
        return false;
    }
    let Expr::Binary(and) = peel_paren(&bin.left) else {
        return false;
    };
    if !matches!(and.op, syn::BinOp::BitAnd(_)) || lit_i64(&and.right) != Some(1) {
        return false;
    }
    let Expr::MethodCall(call) = peel_paren(&and.left) else {
        return false;
    };
    call.method == "len" && path_ends_recv(&call.receiver, name)
}

fn pushes_last(block: &Block, name: &str) -> bool {
    block.stmts.iter().any(|stmt| {
        let Stmt::Expr(Expr::MethodCall(call), _) = stmt else {
            return false;
        };
        call.method == "push"
            && path_ends_recv(&call.receiver, name)
            && call.args.len() == 1
            && last_index(&call.args[0], name)
    })
}

fn last_index(expr: &Expr, name: &str) -> bool {
    let Expr::Index(index) = peel_paren(expr) else {
        return false;
    };
    if !path_ends(&index.expr, name) {
        return false;
    }
    let Expr::Binary(bin) = peel_paren(&index.index) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Sub(_))
        && lit_i64(&bin.right) == Some(1)
        && method_on(&bin.left, "len", name)
}

fn next_level_let(stmt: &Stmt) -> bool {
    local_init(stmt, "next_level").is_some()
}

fn hash_for(stmt: &Stmt) -> bool {
    let Stmt::Expr(Expr::ForLoop(lp), _) = stmt else {
        return false;
    };
    let Expr::MethodCall(chunks) = peel_paren(&lp.expr) else {
        return false;
    };
    chunks.method == "chunks"
        && chunks.args.len() == 1
        && lit_i64(&chunks.args[0]) == Some(2)
        && block_mentions_call_name(&lp.body, "double_sha256_hash")
}

fn block_mentions_call_name(block: &Block, name: &str) -> bool {
    block
        .stmts
        .iter()
        .any(|stmt| stmt_mentions_call(stmt, name))
}

fn hashes_assign(stmt: &Stmt) -> bool {
    let Stmt::Expr(Expr::Assign(assign), _) = stmt else {
        return false;
    };
    let Expr::Unary(star) = peel_paren(&assign.left) else {
        return false;
    };
    matches!(star.op, syn::UnOp::Deref(_))
        && path_ends(&star.expr, "hashes")
        && path_ends(&assign.right, "next_level")
}

enum ChainAdd {
    Sum,
    Keep,
    PlusOne,
}

fn parse_chain_work(block: &Block) -> Option<ChainAdd> {
    let [init, loop_stmt, tail] = block.stmts.as_slice() else {
        return None;
    };
    if !total_work_zero(init) || !ok_total_work(tail) {
        return None;
    }
    chain_for(loop_stmt)
}

fn total_work_zero(stmt: &Stmt) -> bool {
    local_init(stmt, "total_work").is_some_and(|init| expr_is_call(init, "zero"))
}

fn ok_total_work(stmt: &Stmt) -> bool {
    let Stmt::Expr(expr, None) = stmt else {
        return false;
    };
    let Expr::Call(ok) = peel_paren(expr) else {
        return false;
    };
    call_ends(&ok.func, "Ok") && ok.args.len() == 1 && path_ends(&ok.args[0], "total_work")
}

fn chain_for(stmt: &Stmt) -> Option<ChainAdd> {
    let Stmt::Expr(Expr::ForLoop(lp), _) = stmt else {
        return None;
    };
    if !path_ends(&lp.expr, "chain") {
        return None;
    }
    let [work, old, assign, assert_] = lp.body.stmts.as_slice() else {
        return None;
    };
    if !work_try(work) || !old_total_copy(old) || !is_debug_assert(assert_) {
        return None;
    }
    chain_assign(assign)
}

fn work_try(stmt: &Stmt) -> bool {
    let Some(init) = local_init(stmt, "work_contribution") else {
        return false;
    };
    let Expr::Try(tried) = peel_paren(init) else {
        return false;
    };
    let Expr::Call(call) = peel_paren(&tried.expr) else {
        return false;
    };
    call_ends(&call.func, "work_for_bits") && call.args.len() == 1
}

fn old_total_copy(stmt: &Stmt) -> bool {
    local_init(stmt, "old_total").is_some_and(|init| path_ends(init, "total_work"))
}

fn is_debug_assert(stmt: &Stmt) -> bool {
    let Stmt::Macro(mac) = stmt else {
        return false;
    };
    mac.mac
        .path
        .segments
        .last()
        .is_some_and(|seg| seg.ident == "debug_assert")
}

fn chain_assign(stmt: &Stmt) -> Option<ChainAdd> {
    let Stmt::Expr(Expr::Assign(assign), _) = stmt else {
        return None;
    };
    if !path_ends(&assign.left, "total_work") {
        return None;
    }
    if path_ends(&assign.right, "old_total") {
        return Some(ChainAdd::Keep);
    }
    let Expr::MethodCall(call) = peel_paren(&assign.right) else {
        return None;
    };
    if call.method != "saturating_add"
        || call.args.len() != 1
        || !path_ends(&call.receiver, "total_work")
    {
        return None;
    }
    if path_ends(&call.args[0], "work_contribution") {
        return Some(ChainAdd::Sum);
    }
    let Expr::MethodCall(inner) = peel_paren(&call.args[0]) else {
        return None;
    };
    if inner.method == "saturating_add"
        && inner.args.len() == 1
        && path_ends(&inner.receiver, "work_contribution")
        && expr_is_call(&inner.args[0], "one")
    {
        Some(ChainAdd::PlusOne)
    } else {
        None
    }
}

struct Retarget {
    shift: i64,
    reads: [i64; 4],
    writes: [i64; 4],
}

fn parse_retarget(block: &Block) -> Option<Retarget> {
    let [mul_stmt, div_stmt] = block.stmts.as_slice() else {
        return None;
    };
    let shift = parse_mul_body(let_block(mul_stmt, "_mul")?)?;
    let (reads, writes) = parse_div_body(let_block(div_stmt, "_div")?)?;
    Some(Retarget {
        shift,
        reads,
        writes,
    })
}

fn let_block<'a>(stmt: &'a Stmt, name: &str) -> Option<&'a Block> {
    let Expr::Block(block) = peel_paren(local_init(stmt, name)?) else {
        return None;
    };
    Some(&block.block)
}

fn parse_mul_body(block: &Block) -> Option<i64> {
    let mut saw_unroll = false;
    let mut shift = None;
    let mut saw_some = false;
    if block.stmts.len() < 3
        || !zero_lit(&block.stmts[0], "carry")
        || !call_zero(&block.stmts[1], "result")
    {
        return None;
    }
    for stmt in block.stmts.iter().skip(2) {
        if is_some_result(stmt) {
            if saw_some {
                return None;
            }
            saw_some = true;
            continue;
        }
        if saw_some {
            return None;
        }
        let inner = block_stmt(stmt)?;
        if let Some(got) = mul_unroll(inner) {
            if saw_unroll || shift.is_some_and(|prev| prev != got) {
                return None;
            }
            saw_unroll = true;
            shift = Some(got);
        } else if let Some(got) = mul_loop_shift(inner) {
            if shift.is_some_and(|prev| prev != got) {
                return None;
            }
            shift = Some(got);
        } else {
            return None;
        }
    }
    shift.filter(|_| saw_unroll && saw_some)
}

fn parse_div_body(block: &Block) -> Option<([i64; 4], [i64; 4])> {
    if block.stmts.len() < 4 || !div0_if(&block.stmts[0]) {
        return None;
    }
    if !zero_lit(&block.stmts[1], "remainder") || !call_zero(&block.stmts[2], "result") {
        return None;
    }
    let mut reads = [0; 4];
    let mut writes = [0; 4];
    let mut saw_unroll = false;
    let mut saw_loop = false;
    let mut asserts = 0;
    let mut saw_tail = false;
    for stmt in block.stmts.iter().skip(3) {
        if is_result_tail(stmt) {
            saw_tail = true;
            continue;
        }
        if saw_tail {
            return None;
        }
        if is_debug_assert(stmt) {
            asserts += 1;
            continue;
        }
        let inner = block_stmt(stmt)?;
        if let Some((read, write)) = div_unroll(inner) {
            if saw_unroll {
                return None;
            }
            saw_unroll = true;
            reads = read;
            writes = write;
        } else if div_loop(inner) {
            if saw_loop {
                return None;
            }
            saw_loop = true;
        } else {
            return None;
        }
    }
    if saw_unroll && asserts == 2 && saw_tail {
        Some((reads, writes))
    } else {
        None
    }
}

fn mul_unroll(block: &Block) -> Option<i64> {
    if block.stmts.len() != 13 {
        return None;
    }
    let mut shift = None;
    for i in 0..4 {
        let read = product_let(&block.stmts[i * 3])?;
        let stored = limb_store(&block.stmts[i * 3 + 1], "product")?;
        let got = carry_shift(&block.stmts[i * 3 + 2])?;
        if read != i as i64 || stored != i as i64 {
            return None;
        }
        if shift.is_some_and(|prev| prev != got) {
            return None;
        }
        shift = Some(got);
    }
    if overflow_if(&block.stmts[12]) {
        shift.filter(|got| *got == 32 || *got == 64)
    } else {
        None
    }
}

fn mul_loop_shift(block: &Block) -> Option<i64> {
    if block.stmts.len() != 1 {
        return None;
    }
    let Stmt::Expr(Expr::ForLoop(lp), _) = &block.stmts[0] else {
        return None;
    };
    let shift = lp.body.stmts.iter().find_map(carry_shift)?;
    if block_returns_none(&lp.body) && (shift == 32 || shift == 64) {
        Some(shift)
    } else {
        None
    }
}

fn div_unroll(block: &Block) -> Option<([i64; 4], [i64; 4])> {
    if block.stmts.len() != 20 {
        return None;
    }
    let mut reads = [0; 4];
    let mut writes = [0; 4];
    for i in 0..4 {
        let (read, write) = div_step(&block.stmts[i * 5..i * 5 + 5])?;
        reads[i] = read;
        writes[i] = write;
    }
    Some((reads, writes))
}

fn div_step(stmts: &[Stmt]) -> Option<(i64, i64)> {
    let read = dividend_let(&stmts[0])?;
    if !quotient_let(&stmts[1]) || !remainder_mod(&stmts[2]) || !is_debug_assert(&stmts[3]) {
        return None;
    }
    Some((read, limb_store(&stmts[4], "quotient")?))
}

fn div_loop(block: &Block) -> bool {
    block.stmts.len() == 1
        && matches!(block.stmts[0], Stmt::Expr(Expr::ForLoop(_), _))
        && block_has_shl(&block.stmts[0])
}

fn product_let(stmt: &Stmt) -> Option<i64> {
    let Expr::Binary(add) = peel_paren(local_init(stmt, "product")?) else {
        return None;
    };
    if !matches!(add.op, syn::BinOp::Add(_)) || !path_ends(&add.right, "carry") {
        return None;
    }
    let Expr::Binary(mul) = peel_paren(&add.left) else {
        return None;
    };
    if !matches!(mul.op, syn::BinOp::Mul(_)) {
        return None;
    }
    let left = cast_to(&mul.left, "u128")?;
    cast_to(&mul.right, "u128")?;
    let (base, idx) = field_index(left)?;
    if base == "this" || base == "self" {
        Some(idx)
    } else {
        None
    }
}

fn dividend_let(stmt: &Stmt) -> Option<i64> {
    let Expr::Binary(or) = peel_paren(local_init(stmt, "dividend")?) else {
        return None;
    };
    if !matches!(or.op, syn::BinOp::BitOr(_)) {
        return None;
    }
    let Expr::Binary(shl) = peel_paren(&or.left) else {
        return None;
    };
    if !matches!(shl.op, syn::BinOp::Shl(_))
        || !path_ends(&shl.left, "remainder")
        || lit_i64(&shl.right) != Some(64)
    {
        return None;
    }
    let (base, idx) = field_index(cast_to(&or.right, "u128")?)?;
    if base == "this" || base == "self" {
        Some(idx)
    } else {
        None
    }
}

fn quotient_let(stmt: &Stmt) -> bool {
    let Some(init) = local_init(stmt, "quotient") else {
        return false;
    };
    let Expr::Binary(bin) = peel_paren(init) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Div(_))
        && path_ends(&bin.left, "dividend")
        && cast_to(&bin.right, "u128").is_some()
}

fn remainder_mod(stmt: &Stmt) -> bool {
    let Stmt::Expr(Expr::Assign(assign), _) = stmt else {
        return false;
    };
    if !path_ends(&assign.left, "remainder") {
        return false;
    }
    let Expr::Binary(bin) = peel_paren(&assign.right) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Rem(_))
        && path_ends(&bin.left, "dividend")
        && cast_to(&bin.right, "u128").is_some()
}

fn carry_shift(stmt: &Stmt) -> Option<i64> {
    let Stmt::Expr(Expr::Assign(assign), _) = stmt else {
        return None;
    };
    if !path_ends(&assign.left, "carry") {
        return None;
    }
    let Expr::Binary(shr) = peel_paren(&assign.right) else {
        return None;
    };
    if !matches!(shr.op, syn::BinOp::Shr(_)) || !path_ends(&shr.left, "product") {
        return None;
    }
    lit_i64(&shr.right)
}

fn limb_store(stmt: &Stmt, value: &str) -> Option<i64> {
    let Stmt::Expr(Expr::Assign(assign), _) = stmt else {
        return None;
    };
    let (base, idx) = field_index(&assign.left)?;
    if base != "result" {
        return None;
    }
    let inner = cast_to(&assign.right, "u64")?;
    if path_ends(inner, value) {
        Some(idx)
    } else {
        None
    }
}

fn field_index(expr: &Expr) -> Option<(String, i64)> {
    let Expr::Index(index) = peel_paren(expr) else {
        return None;
    };
    let Expr::Field(field) = peel_paren(&index.expr) else {
        return None;
    };
    if !matches!(field.member, syn::Member::Unnamed(ref idx) if idx.index == 0) {
        return None;
    }
    let Expr::Path(path) = peel_paren(&field.base) else {
        return None;
    };
    let name = path.path.segments.last()?.ident.to_string();
    Some((name, lit_i64(&index.index)?))
}

fn cast_to<'a>(expr: &'a Expr, ty_name: &str) -> Option<&'a Expr> {
    let Expr::Cast(cast) = peel_paren(expr) else {
        return None;
    };
    let syn::Type::Path(path) = &*cast.ty else {
        return None;
    };
    if path.path.segments.last()?.ident == ty_name {
        Some(&cast.expr)
    } else {
        None
    }
}

fn overflow_if(stmt: &Stmt) -> bool {
    let Stmt::Expr(Expr::If(iff), _) = stmt else {
        return false;
    };
    let Expr::Binary(bin) = peel_paren(&iff.cond) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Gt(_))
        && path_ends(&bin.left, "carry")
        && lit_i64(&bin.right) == Some(0)
        && block_returns_none(&iff.then_branch)
}

fn div0_if(stmt: &Stmt) -> bool {
    let Stmt::Expr(Expr::If(iff), _) = stmt else {
        return false;
    };
    let Expr::Binary(bin) = peel_paren(&iff.cond) else {
        return false;
    };
    let name_ok = path_ends(&bin.left, "div_rhs") || path_ends(&bin.left, "rhs");
    if !matches!(bin.op, syn::BinOp::Eq(_)) || !name_ok || lit_i64(&bin.right) != Some(0) {
        return false;
    }
    iff.then_branch.stmts.iter().any(|stmt| {
        let Stmt::Expr(Expr::Return(ret), _) = stmt else {
            return false;
        };
        ret.expr.as_deref().is_some_and(is_max_u256)
    })
}

fn is_max_u256(expr: &Expr) -> bool {
    let Expr::Call(call) = peel_paren(expr) else {
        return false;
    };
    if !path_ends(&call.func, "U256") || call.args.len() != 1 {
        return false;
    }
    let Expr::Repeat(rep) = peel_paren(&call.args[0]) else {
        return false;
    };
    lit_i64(&rep.len) == Some(4) && path_ends(&rep.expr, "MAX")
}

fn block_returns_none(block: &Block) -> bool {
    block.stmts.iter().any(|stmt| match stmt {
        Stmt::Expr(Expr::If(iff), _) => block_returns_none(&iff.then_branch),
        Stmt::Expr(Expr::Return(ret), _) => ret
            .expr
            .as_ref()
            .is_some_and(|expr| path_ends(expr, "None")),
        _ => false,
    })
}

fn block_has_shl(stmt: &Stmt) -> bool {
    let Stmt::Expr(Expr::ForLoop(lp), _) = stmt else {
        return false;
    };
    lp.body
        .stmts
        .iter()
        .any(|inner| local_init(inner, "dividend").is_some_and(|expr| mentions(expr, "remainder")))
}

fn block_stmt(stmt: &Stmt) -> Option<&Block> {
    let Stmt::Expr(Expr::Block(block), _) = stmt else {
        return None;
    };
    Some(&block.block)
}

fn zero_lit(stmt: &Stmt, name: &str) -> bool {
    local_init(stmt, name).is_some_and(|expr| lit_i64(expr) == Some(0))
}

fn call_zero(stmt: &Stmt, name: &str) -> bool {
    local_init(stmt, name).is_some_and(|expr| expr_is_call(expr, "zero"))
}

fn is_some_result(stmt: &Stmt) -> bool {
    let Stmt::Expr(expr, _) = stmt else {
        return false;
    };
    let Expr::Call(call) = peel_paren(expr) else {
        return false;
    };
    call_ends(&call.func, "Some") && call.args.len() == 1 && path_ends(&call.args[0], "result")
}

fn is_result_tail(stmt: &Stmt) -> bool {
    let Stmt::Expr(expr, None) = stmt else {
        return false;
    };
    path_ends(expr, "result")
}

struct NestedWeight {
    factor: i64,
    subtract: bool,
}

fn parse_nested_weight(block: &Block) -> Option<NestedWeight> {
    let [prefix, total, loop_stmt, tail] = block.stmts.as_slice() else {
        return None;
    };
    if !prefix_let(prefix) || !ok_total_weight(tail) {
        return None;
    }
    let factor = mul_factor(total)?;
    let subtract = weight_loop(loop_stmt)?;
    Some(NestedWeight { factor, subtract })
}

fn prefix_let(stmt: &Stmt) -> bool {
    let Some(init) = local_init(stmt, "prefix") else {
        return false;
    };
    let Expr::Try(tried) = peel_paren(init) else {
        return false;
    };
    let Expr::Call(call) = peel_paren(&tried.expr) else {
        return false;
    };
    if !call_ends(&call.func, "add_size")
        || call.args.len() != 2
        || lit_i64(&call.args[0]) != Some(80)
    {
        return false;
    }
    let Expr::Call(size) = peel_paren(&call.args[1]) else {
        return false;
    };
    call_ends(&size.func, "compact_size_len") && size.args.len() == 1 && len_as_u64(&size.args[0])
}

fn len_as_u64(expr: &Expr) -> bool {
    let Expr::Cast(cast) = peel_paren(expr) else {
        return false;
    };
    let syn::Type::Path(path) = &*cast.ty else {
        return false;
    };
    if path
        .path
        .segments
        .last()
        .is_none_or(|seg| seg.ident != "u64")
    {
        return false;
    }
    let Expr::MethodCall(call) = peel_paren(&cast.expr) else {
        return false;
    };
    if call.method != "len" || !call.args.is_empty() {
        return false;
    }
    let Expr::Field(field) = peel_paren(&call.receiver) else {
        return false;
    };
    matches!(field.member, syn::Member::Named(ref name) if name == "transactions")
}

fn mul_factor(stmt: &Stmt) -> Option<i64> {
    let init = local_init(stmt, "total_weight")?;
    let call = ok_or_else_recv(init)?;
    if call.method != "checked_mul" || call.args.len() != 1 || !path_ends(&call.receiver, "prefix")
    {
        return None;
    }
    let factor = lit_i64(&call.args[0])?;
    if factor == 4 || factor == 0 {
        Some(factor)
    } else {
        None
    }
}

fn ok_or_else_recv(expr: &Expr) -> Option<&syn::ExprMethodCall> {
    let Expr::Try(tried) = peel_paren(expr) else {
        return None;
    };
    let Expr::MethodCall(call) = peel_paren(&tried.expr) else {
        return None;
    };
    if call.method != "ok_or_else"
        || call.args.len() != 1
        || !path_ends(&call.args[0], "weight_overflow")
    {
        return None;
    }
    let Expr::MethodCall(inner) = peel_paren(&call.receiver) else {
        return None;
    };
    Some(inner)
}

fn weight_loop(stmt: &Stmt) -> Option<bool> {
    let Stmt::Expr(Expr::ForLoop(lp), _) = stmt else {
        return None;
    };
    if !path_ends_method(&lp.expr, "enumerate") {
        return None;
    }
    let [stacks, assign] = lp.body.stmts.as_slice() else {
        return None;
    };
    if !stacks_let(stacks) {
        return None;
    }
    let Stmt::Expr(Expr::Assign(assign), _) = assign else {
        return None;
    };
    if !path_ends(&assign.left, "total_weight") {
        return None;
    }
    let call = ok_or_else_recv(&assign.right)?;
    if !path_ends(&call.receiver, "total_weight") || call.args.len() != 1 {
        return None;
    }
    let subtract = if call.method == "checked_add" {
        false
    } else if call.method == "checked_sub" {
        true
    } else {
        return None;
    };
    let Expr::Try(tried) = peel_paren(&call.args[0]) else {
        return None;
    };
    let Expr::Call(weight) = peel_paren(&tried.expr) else {
        return None;
    };
    if call_ends(&weight.func, "transaction_weight_from_stacks") && weight.args.len() == 2 {
        Some(subtract)
    } else {
        None
    }
}

fn path_ends_method(expr: &Expr, name: &str) -> bool {
    let Expr::MethodCall(call) = peel_paren(expr) else {
        return false;
    };
    call.method == name
}

fn stacks_let(stmt: &Stmt) -> bool {
    let Some(init) = local_init(stmt, "stacks") else {
        return false;
    };
    let Expr::MethodCall(map) = peel_paren(init) else {
        return false;
    };
    if map.method != "map" {
        return false;
    }
    let Expr::MethodCall(get) = peel_paren(&map.receiver) else {
        return false;
    };
    get.method == "get" && path_ends_recv(&get.receiver, "witnesses")
}

fn ok_total_weight(stmt: &Stmt) -> bool {
    let Stmt::Expr(expr, None) = stmt else {
        return false;
    };
    let Expr::Call(ok) = peel_paren(expr) else {
        return false;
    };
    call_ends(&ok.func, "Ok") && ok.args.len() == 1 && path_ends(&ok.args[0], "total_weight")
}

struct BlockWeight {
    subtract: bool,
    zero_tx: bool,
}

fn parse_block_weight(block: &Block) -> Option<BlockWeight> {
    let [prefix, total, loop_stmt, tail] = block.stmts.as_slice() else {
        return None;
    };
    if !prefix_let(prefix) || mul_factor(total)? != 4 || !ok_total_weight(tail) {
        return None;
    }
    let (subtract, zero_tx) = block_weight_loop(loop_stmt)?;
    Some(BlockWeight { subtract, zero_tx })
}

fn block_weight_loop(stmt: &Stmt) -> Option<(bool, bool)> {
    let Stmt::Expr(Expr::ForLoop(lp), _) = stmt else {
        return None;
    };
    if !path_ends_method(&lp.expr, "enumerate") {
        return None;
    }
    let [witness, assign] = lp.body.stmts.as_slice() else {
        return None;
    };
    if !witness_choice(witness) {
        return None;
    }
    let Stmt::Expr(Expr::Assign(assign), _) = assign else {
        return None;
    };
    if !path_ends(&assign.left, "total_weight") {
        return None;
    }
    let call = ok_or_else_recv(&assign.right)?;
    if !path_ends(&call.receiver, "total_weight") || call.args.len() != 1 {
        return None;
    }
    let subtract = if call.method == "checked_add" {
        false
    } else if call.method == "checked_sub" {
        true
    } else {
        return None;
    };
    let zero_tx = tx_weight_is_zero(&call.args[0])?;
    Some((subtract, zero_tx))
}

fn tx_weight_is_zero(expr: &Expr) -> Option<bool> {
    if lit_i64(expr) == Some(0) {
        return Some(true);
    }
    let Expr::Try(tried) = peel_paren(expr) else {
        return None;
    };
    let Expr::Call(call) = peel_paren(&tried.expr) else {
        return None;
    };
    if call_ends(&call.func, "calculate_transaction_weight") && call.args.len() == 2 {
        Some(false)
    } else {
        None
    }
}

fn witness_choice(stmt: &Stmt) -> bool {
    let Some(init) = local_init(stmt, "witness") else {
        return false;
    };
    let Expr::If(iff) = peel_paren(init) else {
        return false;
    };
    let Expr::Binary(bin) = peel_paren(&iff.cond) else {
        return false;
    };
    if !matches!(bin.op, syn::BinOp::Lt(_)) || !path_ends(&bin.left, "i") {
        return false;
    }
    let Expr::MethodCall(len) = peel_paren(&bin.right) else {
        return false;
    };
    if len.method != "len" || !path_ends(&len.receiver, "witnesses") {
        return false;
    }
    some_indexed_witness(&iff.then_branch) && else_is_none(iff.else_branch.as_ref())
}

fn some_indexed_witness(block: &Block) -> bool {
    let [stmt] = block.stmts.as_slice() else {
        return false;
    };
    let Stmt::Expr(expr, None) = stmt else {
        return false;
    };
    let Expr::Call(call) = peel_paren(expr) else {
        return false;
    };
    if !call_ends(&call.func, "Some") || call.args.len() != 1 {
        return false;
    }
    let Expr::Reference(refer) = peel_paren(&call.args[0]) else {
        return false;
    };
    let Expr::Index(index) = peel_paren(&refer.expr) else {
        return false;
    };
    path_ends(&index.expr, "witnesses") && path_ends(&index.index, "i")
}

fn else_is_none(else_branch: Option<&(syn::token::Else, Box<Expr>)>) -> bool {
    let Some((_, expr)) = else_branch else {
        return false;
    };
    let Expr::Block(block) = peel_paren(expr) else {
        return false;
    };
    let [stmt] = block.block.stmts.as_slice() else {
        return false;
    };
    let Stmt::Expr(expr, None) = stmt else {
        return false;
    };
    path_ends(peel_paren(expr), "None")
}

struct WitnessCommit {
    limit: i64,
    equal: bool,
}

fn parse_witness_commit(block: &Block) -> Option<WitnessCommit> {
    let [commit_stmt, nonce_stmt] = block.stmts.as_slice() else {
        return None;
    };
    let equal = commit_body(let_block(commit_stmt, "_commit")?)?;
    let limit = nonce_body(let_block(nonce_stmt, "_nonce")?)?;
    Some(WitnessCommit { limit, equal })
}

fn commit_body(block: &Block) -> Option<bool> {
    let stmts = &block.stmts;
    if stmts.len() < 7 {
        return None;
    }
    if !let_some_call(
        &stmts[0],
        "commitment",
        "last_witness_commitment_in_coinbase_outputs",
        true,
    ) || !let_some_call(
        &stmts[1],
        "reserved_nonce",
        "coinbase_reserved_nonce",
        false,
    ) || !repeat_let(&stmts[2], "preimage", 64)
        || !copy_range(&stmts[3], "preimage", None, Some(32), "witness_merkle_root")
        || !copy_range(&stmts[4], "preimage", Some(32), None, "reserved_nonce")
        || !sha_let(&stmts[5])
    {
        return None;
    }
    let mut equal = None;
    for stmt in stmts.iter().skip(6) {
        if let Some(got) = ok_compare(stmt) {
            if equal.is_some() {
                return None;
            }
            equal = Some(got);
        } else if !is_debug_if(stmt) {
            return None;
        }
    }
    equal
}

fn nonce_body(block: &Block) -> Option<i64> {
    let [first, gate, nonce, copy, tail] = block.stmts.as_slice() else {
        return None;
    };
    if !first_stack(first)
        || !repeat_let(nonce, "nonce", 32)
        || !nonce_copy(copy)
        || !some_nonce(tail)
    {
        return None;
    }
    nonce_limit(gate)
}

fn let_some_call(stmt: &Stmt, name: &str, call: &str, ok_true: bool) -> bool {
    let Stmt::Local(local) = stmt else {
        return false;
    };
    let Some(init) = &local.init else {
        return false;
    };
    let Some((_, else_expr)) = &init.diverge else {
        return false;
    };
    some_pat(&local.pat, name)
        && call_named(&init.expr, call)
        && diverge_ok(else_expr) == Some(ok_true)
}

fn some_pat(pat: &syn::Pat, name: &str) -> bool {
    let syn::Pat::TupleStruct(tuple) = pat else {
        return false;
    };
    if !path_to_string(&tuple.path).ends_with("Some") || tuple.elems.len() != 1 {
        return false;
    }
    let syn::Pat::Ident(ident) = &tuple.elems[0] else {
        return false;
    };
    ident.ident == name
}

fn diverge_ok(expr: &Expr) -> Option<bool> {
    let Expr::Block(block) = peel_paren(expr) else {
        return None;
    };
    let [stmt] = block.block.stmts.as_slice() else {
        return None;
    };
    let Stmt::Expr(Expr::Return(ret), _) = stmt else {
        return None;
    };
    ok_lit(ret.expr.as_deref()?)
}

fn ok_lit(expr: &Expr) -> Option<bool> {
    let Expr::Call(call) = peel_paren(expr) else {
        return None;
    };
    if !call_ends(&call.func, "Ok") || call.args.len() != 1 {
        return None;
    }
    if is_bool_lit(&call.args[0], true) {
        Some(true)
    } else if is_bool_lit(&call.args[0], false) {
        Some(false)
    } else {
        None
    }
}

fn repeat_let(stmt: &Stmt, name: &str, len: i64) -> bool {
    local_init(stmt, name).is_some_and(|expr| {
        let Expr::Repeat(rep) = peel_paren(expr) else {
            return false;
        };
        lit_i64(&rep.len) == Some(len)
    })
}

fn copy_range(stmt: &Stmt, base: &str, start: Option<i64>, end: Option<i64>, arg: &str) -> bool {
    let Stmt::Expr(Expr::MethodCall(call), _) = stmt else {
        return false;
    };
    if call.method != "copy_from_slice"
        || call.args.len() != 1
        || bare_path(&call.args[0]).as_deref() != Some(arg)
    {
        return false;
    }
    let Expr::Index(index) = peel_paren(&call.receiver) else {
        return false;
    };
    if !path_ends(&index.expr, base) {
        return false;
    }
    let Expr::Range(range) = peel_paren(&index.index) else {
        return false;
    };
    let got_start = range.start.as_ref().and_then(|expr| lit_i64(expr));
    let got_end = range.end.as_ref().and_then(|expr| lit_i64(expr));
    got_start == start && got_end == end
}

fn sha_let(stmt: &Stmt) -> bool {
    local_init(stmt, "expected_commitment").is_some_and(|expr| call_named(expr, "sha256d_bytes"))
}

fn ok_compare(stmt: &Stmt) -> Option<bool> {
    let Stmt::Expr(expr, None) = stmt else {
        return None;
    };
    let Expr::Call(call) = peel_paren(expr) else {
        return None;
    };
    if !call_ends(&call.func, "Ok") || call.args.len() != 1 {
        return None;
    }
    let Expr::Binary(bin) = peel_paren(&call.args[0]) else {
        return None;
    };
    let names = path_ends(&bin.left, "commitment") && path_ends(&bin.right, "expected_commitment");
    if !names {
        return None;
    }
    match bin.op {
        syn::BinOp::Eq(_) => Some(true),
        syn::BinOp::Ne(_) => Some(false),
        _ => None,
    }
}

fn is_debug_if(stmt: &Stmt) -> bool {
    matches!(stmt, Stmt::Expr(Expr::If(_), _))
}

fn first_stack(stmt: &Stmt) -> bool {
    let Some(init) = local_init(stmt, "stack") else {
        return false;
    };
    let Expr::Try(tried) = peel_paren(init) else {
        return false;
    };
    let Expr::MethodCall(call) = peel_paren(&tried.expr) else {
        return false;
    };
    call.method == "first" && path_ends_recv(&call.receiver, "coinbase_witnesses")
}

fn nonce_limit(stmt: &Stmt) -> Option<i64> {
    let Stmt::Expr(Expr::If(iff), _) = stmt else {
        return None;
    };
    let Expr::Binary(or) = peel_paren(&iff.cond) else {
        return None;
    };
    if !matches!(or.op, syn::BinOp::Or(_)) || !len_ne(&or.left, "stack", 1) {
        return None;
    }
    let limit = index_len_ne(&or.right, "stack")?;
    if block_returns_none(&iff.then_branch) {
        Some(limit)
    } else {
        None
    }
}

fn len_ne(expr: &Expr, recv: &str, n: i64) -> bool {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    if !matches!(bin.op, syn::BinOp::Ne(_)) || lit_i64(&bin.right) != Some(n) {
        return false;
    }
    let Expr::MethodCall(call) = peel_paren(&bin.left) else {
        return false;
    };
    call.method == "len" && path_ends_recv(&call.receiver, recv)
}

fn index_len_ne(expr: &Expr, recv: &str) -> Option<i64> {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return None;
    };
    if !matches!(bin.op, syn::BinOp::Ne(_)) {
        return None;
    }
    let Expr::MethodCall(call) = peel_paren(&bin.left) else {
        return None;
    };
    if call.method != "len" {
        return None;
    }
    let Expr::Index(index) = peel_paren(&call.receiver) else {
        return None;
    };
    if path_ends(&index.expr, recv) && lit_i64(&index.index) == Some(0) {
        lit_i64(&bin.right)
    } else {
        None
    }
}

fn nonce_copy(stmt: &Stmt) -> bool {
    let Stmt::Expr(Expr::MethodCall(call), _) = stmt else {
        return false;
    };
    call.method == "copy_from_slice" && path_ends(&call.receiver, "nonce") && call.args.len() == 1
}

fn some_nonce(stmt: &Stmt) -> bool {
    let Stmt::Expr(expr, None) = stmt else {
        return false;
    };
    let Expr::Call(call) = peel_paren(expr) else {
        return false;
    };
    call_ends(&call.func, "Some") && call.args.len() == 1 && path_ends(&call.args[0], "nonce")
}

fn bare_path(expr: &Expr) -> Option<String> {
    match peel_paren(expr) {
        Expr::Reference(refer) => bare_path(&refer.expr),
        Expr::Path(path) => Some(path.path.segments.last()?.ident.to_string()),
        _ => None,
    }
}

struct WitnessSigops {
    mask: i64,
    p2sh_mask: i64,
    p2wpkh_len: i64,
}

fn parse_witness_sigops(block: &Block) -> Option<WitnessSigops> {
    let [count_stmt, input_stmt, prog_stmt] = block.stmts.as_slice() else {
        return None;
    };
    sigop_count_body(let_block(count_stmt, "_count")?)?;
    let (mask, p2sh_mask) = sigop_input_body(let_block(input_stmt, "_input")?)?;
    let p2wpkh_len = sigop_prog_body(let_block(prog_stmt, "_prog")?)?;
    Some(WitnessSigops {
        mask,
        p2sh_mask,
        p2wpkh_len,
    })
}

fn sigop_count_body(block: &Block) -> Option<()> {
    let stmts = &block.stmts;
    let rest = if matches!(stmts.first(), Some(Stmt::Item(_))) {
        &stmts[1..]
    } else {
        stmts.as_slice()
    };
    let [coin, init, loop_stmt, tail] = rest else {
        return None;
    };
    if coinbase_ok_zero(coin)
        && zero_named(init, "count")
        && sigop_input_loop(loop_stmt)
        && ok_count_tail(tail)
    {
        Some(())
    } else {
        None
    }
}

fn coinbase_ok_zero(stmt: &Stmt) -> bool {
    let Stmt::Expr(Expr::If(iff), _) = stmt else {
        return false;
    };
    call_named(&iff.cond, "is_coinbase") && block_returns_ok_zero(&iff.then_branch)
}

fn zero_named(stmt: &Stmt, name: &str) -> bool {
    local_init(stmt, name).is_some_and(|expr| lit_i64(expr) == Some(0))
}

fn sigop_input_loop(stmt: &Stmt) -> bool {
    let Stmt::Expr(Expr::ForLoop(lp), _) = stmt else {
        return false;
    };
    let syn::Pat::Tuple(tuple) = &*lp.pat else {
        return false;
    };
    if tuple.elems.len() != 2 {
        return false;
    }
    let Expr::MethodCall(enumerate) = peel_paren(&lp.expr) else {
        return false;
    };
    if enumerate.method != "enumerate" {
        return false;
    }
    let Expr::MethodCall(iter) = peel_paren(&enumerate.receiver) else {
        return false;
    };
    if iter.method != "iter" {
        return false;
    }
    let Expr::Field(field) = peel_paren(&iter.receiver) else {
        return false;
    };
    if !path_ends(&field.base, "tx")
        || !matches!(field.member, syn::Member::Named(ref name) if name == "inputs")
    {
        return false;
    }
    let [add_if] = lp.body.stmts.as_slice() else {
        return false;
    };
    sigop_saturating_add(add_if)
}

fn sigop_saturating_add(stmt: &Stmt) -> bool {
    let Stmt::Expr(Expr::If(iff), _) = stmt else {
        return false;
    };
    let Expr::Let(guard) = peel_paren(&iff.cond) else {
        return false;
    };
    if !some_pat(&guard.pat, "utxo") || !method_named(&guard.expr, "get", "utxo_lookup") {
        return false;
    }
    let [assign] = iff.then_branch.stmts.as_slice() else {
        return false;
    };
    let Stmt::Expr(Expr::Assign(asg), _) = assign else {
        return false;
    };
    if !path_ends(&asg.left, "count") {
        return false;
    }
    let Expr::MethodCall(add) = peel_paren(&asg.right) else {
        return false;
    };
    add.method == "saturating_add"
        && path_ends(&add.receiver, "count")
        && add.args.len() == 1
        && call_named(&add.args[0], "input_witness_sigops")
}

fn ok_count_tail(stmt: &Stmt) -> bool {
    let Stmt::Expr(expr, None) = stmt else {
        return false;
    };
    let Expr::Call(call) = peel_paren(expr) else {
        return false;
    };
    call_ends(&call.func, "Ok") && call.args.len() == 1 && path_ends(&call.args[0], "count")
}

fn sigop_input_body(block: &Block) -> Option<(i64, i64)> {
    let [gate, native, p2sh, tail] = block.stmts.as_slice() else {
        return None;
    };
    let mask = flag_gate(gate, true)?;
    if !returns_named_call(
        native,
        "is_version_zero_witness_program",
        "witness_program_sigops",
    ) {
        return None;
    }
    let p2sh_mask = p2sh_gate(p2sh)?;
    if lit_tail(tail, 0) {
        Some((mask, p2sh_mask))
    } else {
        None
    }
}

fn flag_gate(stmt: &Stmt, eq_zero: bool) -> Option<i64> {
    let Stmt::Expr(Expr::If(iff), _) = stmt else {
        return None;
    };
    let mask = flag_cmp(&iff.cond, eq_zero)?;
    if returns_lit(&iff.then_branch, 0) {
        Some(mask)
    } else {
        None
    }
}

fn flag_cmp(expr: &Expr, eq_zero: bool) -> Option<i64> {
    let Expr::Binary(cmp) = peel_paren(expr) else {
        return None;
    };
    let op_ok = if eq_zero {
        matches!(cmp.op, syn::BinOp::Eq(_))
    } else {
        matches!(cmp.op, syn::BinOp::Ne(_))
    };
    if !op_ok || lit_i64(&cmp.right) != Some(0) {
        return None;
    }
    let Expr::Binary(band) = peel_paren(&cmp.left) else {
        return None;
    };
    if matches!(band.op, syn::BinOp::BitAnd(_)) && path_ends(&band.left, "flags") {
        lit_i64(&band.right)
    } else {
        None
    }
}

fn returns_named_call(stmt: &Stmt, cond: &str, call: &str) -> bool {
    let Stmt::Expr(Expr::If(iff), _) = stmt else {
        return false;
    };
    call_named(&iff.cond, cond) && returns_call(&iff.then_branch, call)
}

fn returns_call(block: &Block, name: &str) -> bool {
    let [stmt] = block.stmts.as_slice() else {
        return false;
    };
    let Stmt::Expr(Expr::Return(ret), _) = stmt else {
        return false;
    };
    ret.expr
        .as_deref()
        .is_some_and(|expr| call_named(expr, name))
}

fn returns_lit(block: &Block, n: i64) -> bool {
    let [stmt] = block.stmts.as_slice() else {
        return false;
    };
    match stmt {
        Stmt::Expr(Expr::Return(ret), _) => ret.expr.as_deref().and_then(lit_i64) == Some(n),
        Stmt::Expr(expr, None) => lit_i64(expr) == Some(n),
        _ => false,
    }
}

fn lit_tail(stmt: &Stmt, n: i64) -> bool {
    let Stmt::Expr(expr, None) = stmt else {
        return false;
    };
    lit_i64(expr) == Some(n)
}

fn p2sh_gate(stmt: &Stmt) -> Option<i64> {
    let Stmt::Expr(Expr::If(iff), _) = stmt else {
        return None;
    };
    let Expr::Binary(and) = peel_paren(&iff.cond) else {
        return None;
    };
    if !matches!(and.op, syn::BinOp::And(_)) || !call_named(&and.right, "is_pay_to_script_hash") {
        return None;
    }
    let mask = flag_cmp(&and.left, false)?;
    let [inner] = iff.then_branch.stmts.as_slice() else {
        return None;
    };
    let Stmt::Expr(Expr::If(inner_if), _) = inner else {
        return None;
    };
    let Expr::Let(guard) = peel_paren(&inner_if.cond) else {
        return None;
    };
    if some_pat(&guard.pat, "redeem")
        && call_named(&guard.expr, "extract_redeem_script_from_scriptsig")
        && returns_call(&inner_if.then_branch, "witness_program_sigops")
    {
        Some(mask)
    } else {
        None
    }
}

fn sigop_prog_body(block: &Block) -> Option<i64> {
    let [pkh, wsh, tail] = block.stmts.as_slice() else {
        return None;
    };
    let len = pkh_gate(pkh)?;
    if wsh_gate(wsh) && lit_tail(tail, 0) {
        Some(len)
    } else {
        None
    }
}

fn pkh_gate(stmt: &Stmt) -> Option<i64> {
    let Stmt::Expr(Expr::If(iff), _) = stmt else {
        return None;
    };
    let len = script_shape(&iff.cond, 0x14)?;
    if returns_lit(&iff.then_branch, 1) {
        Some(len)
    } else {
        None
    }
}

fn script_shape(expr: &Expr, push: i64) -> Option<i64> {
    let Expr::Binary(and1) = peel_paren(expr) else {
        return None;
    };
    if !matches!(and1.op, syn::BinOp::And(_)) {
        return None;
    }
    let Expr::Binary(and0) = peel_paren(&and1.left) else {
        return None;
    };
    if !matches!(and0.op, syn::BinOp::And(_)) {
        return None;
    }
    let len = len_eq_recv(&and0.left, "script")?;
    if index_eq_path(&and0.right, "script", 0, "OP_0")
        && index_eq_lit(&and1.right, "script", 1, push)
    {
        Some(len)
    } else {
        None
    }
}

fn len_eq_recv(expr: &Expr, recv: &str) -> Option<i64> {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return None;
    };
    if !matches!(bin.op, syn::BinOp::Eq(_)) {
        return None;
    }
    let Expr::MethodCall(call) = peel_paren(&bin.left) else {
        return None;
    };
    if call.method == "len" && path_ends(&call.receiver, recv) {
        lit_i64(&bin.right)
    } else {
        None
    }
}

fn index_eq_path(expr: &Expr, recv: &str, idx: i64, name: &str) -> bool {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Eq(_))
        && bare_path(&bin.right).as_deref() == Some(name)
        && index_is(&bin.left, recv, idx)
}

fn index_eq_lit(expr: &Expr, recv: &str, idx: i64, n: i64) -> bool {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Eq(_))
        && lit_i64(&bin.right) == Some(n)
        && index_is(&bin.left, recv, idx)
}

fn index_is(expr: &Expr, recv: &str, idx: i64) -> bool {
    let Expr::Index(index) = peel_paren(expr) else {
        return false;
    };
    path_ends(&index.expr, recv) && lit_i64(&index.index) == Some(idx)
}

fn wsh_gate(stmt: &Stmt) -> bool {
    let Stmt::Expr(Expr::If(iff), _) = stmt else {
        return false;
    };
    if script_shape(&iff.cond, 0x20) != Some(34) {
        return false;
    }
    let [filt, last, ret] = iff.then_branch.stmts.as_slice() else {
        return false;
    };
    witness_nonempty(filt) && witness_script_last(last) && accurate_sigops(ret)
}

fn witness_nonempty(stmt: &Stmt) -> bool {
    let Stmt::Local(local) = stmt else {
        return false;
    };
    let Some(init) = &local.init else {
        return false;
    };
    let Some((_, else_expr)) = &init.diverge else {
        return false;
    };
    if !some_pat(&local.pat, "witness") || !diverge_lit(else_expr, 0) {
        return false;
    }
    let Expr::MethodCall(call) = peel_paren(&init.expr) else {
        return false;
    };
    if call.method != "filter" || !path_ends(&call.receiver, "witness") || call.args.len() != 1 {
        return false;
    }
    let Expr::Closure(clos) = peel_paren(&call.args[0]) else {
        return false;
    };
    let Expr::Unary(un) = peel_paren(&clos.body) else {
        return false;
    };
    if !matches!(un.op, syn::UnOp::Not(_)) {
        return false;
    }
    let Expr::MethodCall(empty) = peel_paren(&un.expr) else {
        return false;
    };
    empty.method == "is_empty"
}

fn witness_script_last(stmt: &Stmt) -> bool {
    let Stmt::Local(local) = stmt else {
        return false;
    };
    let Some(init) = &local.init else {
        return false;
    };
    let Some((_, else_expr)) = &init.diverge else {
        return false;
    };
    some_pat(&local.pat, "witness_script")
        && diverge_lit(else_expr, 0)
        && method_named(&init.expr, "last", "witness")
}

fn diverge_lit(expr: &Expr, n: i64) -> bool {
    let Expr::Block(block) = peel_paren(expr) else {
        return false;
    };
    returns_lit(&block.block, n)
}

fn method_named(expr: &Expr, method: &str, recv: &str) -> bool {
    let Expr::MethodCall(call) = peel_paren(expr) else {
        return false;
    };
    call.method == method && path_ends(&call.receiver, recv)
}

fn accurate_sigops(stmt: &Stmt) -> bool {
    let Stmt::Expr(Expr::Return(ret), _) = stmt else {
        return false;
    };
    let Some(expr) = ret.expr.as_deref() else {
        return false;
    };
    let Expr::Cast(cast) = peel_paren(expr) else {
        return false;
    };
    let syn::Type::Path(ty) = &*cast.ty else {
        return false;
    };
    if ty
        .path
        .segments
        .last()
        .map(|seg| seg.ident.to_string())
        .as_deref()
        != Some("u64")
    {
        return false;
    }
    let Expr::Call(call) = peel_paren(&cast.expr) else {
        return false;
    };
    call_ends(&call.func, "count_sigops_in_script")
        && call.args.len() == 2
        && path_ends(&call.args[0], "witness_script")
        && is_bool_lit(&call.args[1], true)
}

struct OpDispatch {
    limit: i64,
    subtract: bool,
}

fn parse_op_dispatch(block: &Block) -> Option<OpDispatch> {
    let [arm_stmt, add_stmt] = block.stmts.as_slice() else {
        return None;
    };
    add_arm(let_block(arm_stmt, "_arm")?)?;
    let (limit, subtract) = op_add_body(let_block(add_stmt, "_add")?)?;
    Some(OpDispatch { limit, subtract })
}

fn add_arm(block: &Block) -> Option<()> {
    let [gate, tail] = block.stmts.as_slice() else {
        return None;
    };
    if minimal_gate(gate) && op_add_call(tail) {
        Some(())
    } else {
        None
    }
}

fn minimal_gate(stmt: &Stmt) -> bool {
    let Stmt::Expr(Expr::If(iff), _) = stmt else {
        return false;
    };
    let Expr::Binary(and) = peel_paren(&iff.cond) else {
        return false;
    };
    if !matches!(and.op, syn::BinOp::And(_)) || !minimal_flag(&and.left) || !stack_ge(&and.right, 2)
    {
        return false;
    }
    let [len_stmt, check] = iff.then_branch.stmts.as_slice() else {
        return false;
    };
    stack_len_let(len_stmt) && minimal_pair(check)
}

fn minimal_flag(expr: &Expr) -> bool {
    let Expr::Binary(cmp) = peel_paren(expr) else {
        return false;
    };
    if !matches!(cmp.op, syn::BinOp::Ne(_)) || lit_i64(&cmp.right) != Some(0) {
        return false;
    }
    let Expr::Binary(band) = peel_paren(&cmp.left) else {
        return false;
    };
    matches!(band.op, syn::BinOp::BitAnd(_))
        && path_ends(&band.left, "flags")
        && path_ends(&band.right, "SCRIPT_VERIFY_MINIMALDATA")
}

fn stack_ge(expr: &Expr, n: i64) -> bool {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    if !matches!(bin.op, syn::BinOp::Ge(_)) || lit_i64(&bin.right) != Some(n) {
        return false;
    }
    let Expr::MethodCall(call) = peel_paren(&bin.left) else {
        return false;
    };
    call.method == "len" && path_ends(&call.receiver, "stack")
}

fn stack_len_let(stmt: &Stmt) -> bool {
    local_init(stmt, "len").is_some_and(|expr| {
        let Expr::MethodCall(call) = peel_paren(expr) else {
            return false;
        };
        call.method == "len" && path_ends(&call.receiver, "stack")
    })
}

fn minimal_pair(stmt: &Stmt) -> bool {
    let Stmt::Expr(Expr::If(iff), _) = stmt else {
        return false;
    };
    let Expr::Binary(or) = peel_paren(&iff.cond) else {
        return false;
    };
    if !matches!(or.op, syn::BinOp::Or(_)) {
        return false;
    }
    minimal_index(&or.left, 1)
        && minimal_index(&or.right, 2)
        && dispatch_returns_err(&iff.then_branch)
}

fn minimal_index(expr: &Expr, delta: i64) -> bool {
    let Expr::Unary(un) = peel_paren(expr) else {
        return false;
    };
    if !matches!(un.op, syn::UnOp::Not(_)) {
        return false;
    }
    let Expr::Call(call) = peel_paren(&un.expr) else {
        return false;
    };
    if !call_ends(&call.func, "script_num_is_minimally_encoded") || call.args.len() != 1 {
        return false;
    }
    let Expr::Reference(refer) = peel_paren(&call.args[0]) else {
        return false;
    };
    let Expr::Index(index) = peel_paren(&refer.expr) else {
        return false;
    };
    if !path_ends(&index.expr, "stack") {
        return false;
    }
    let Expr::Binary(sub) = peel_paren(&index.index) else {
        return false;
    };
    matches!(sub.op, syn::BinOp::Sub(_))
        && path_ends(&sub.left, "len")
        && lit_i64(&sub.right) == Some(delta)
}

fn dispatch_returns_err(block: &Block) -> bool {
    block.stmts.iter().any(|stmt| {
        let Stmt::Expr(Expr::Return(ret), _) = stmt else {
            return false;
        };
        ret.expr.as_deref().is_some_and(|expr| {
            let Expr::Call(call) = peel_paren(expr) else {
                return false;
            };
            call_ends(&call.func, "Err")
        })
    })
}

fn op_add_call(stmt: &Stmt) -> bool {
    let Stmt::Expr(expr, None) = stmt else {
        return false;
    };
    let Expr::Call(call) = peel_paren(expr) else {
        return false;
    };
    call_ends(&call.func, "op_add") && call.args.len() == 1 && path_ends(&call.args[0], "stack")
}

fn op_add_body(block: &Block) -> Option<(i64, bool)> {
    let [gate, a_stmt, b_stmt, push, tail] = block.stmts.as_slice() else {
        return None;
    };
    let limit = short_stack(gate)?;
    if !decode_pop(a_stmt, "a") || !decode_pop(b_stmt, "b") || !ok_true(tail) {
        return None;
    }
    Some((limit, push_sum(push)?))
}

fn short_stack(stmt: &Stmt) -> Option<i64> {
    let Stmt::Expr(Expr::If(iff), _) = stmt else {
        return None;
    };
    let Expr::Binary(bin) = peel_paren(&iff.cond) else {
        return None;
    };
    if !matches!(bin.op, syn::BinOp::Lt(_)) {
        return None;
    }
    let Expr::MethodCall(call) = peel_paren(&bin.left) else {
        return None;
    };
    if call.method != "len" || !path_ends(&call.receiver, "stack") {
        return None;
    }
    let limit = lit_i64(&bin.right)?;
    if dispatch_ok_bool(&iff.then_branch, false) {
        Some(limit)
    } else {
        None
    }
}

fn dispatch_ok_bool(block: &Block, value: bool) -> bool {
    let [stmt] = block.stmts.as_slice() else {
        return false;
    };
    let Stmt::Expr(Expr::Return(ret), _) = stmt else {
        return false;
    };
    let Some(expr) = ret.expr.as_deref() else {
        return false;
    };
    let Expr::Call(call) = peel_paren(expr) else {
        return false;
    };
    call_ends(&call.func, "Ok") && call.args.len() == 1 && is_bool_lit(&call.args[0], value)
}

fn decode_pop(stmt: &Stmt, name: &str) -> bool {
    let Some(init) = local_init(stmt, name) else {
        return false;
    };
    let Expr::Try(tried) = peel_paren(init) else {
        return false;
    };
    let Expr::Call(call) = peel_paren(&tried.expr) else {
        return false;
    };
    call_ends(&call.func, "script_num_decode")
        && call.args.len() == 2
        && lit_i64(&call.args[1]) == Some(4)
        && decode_pop_ref(&call.args[0])
}

fn decode_pop_ref(expr: &Expr) -> bool {
    let Expr::Reference(refer) = peel_paren(expr) else {
        return false;
    };
    let Expr::MethodCall(unwrap) = peel_paren(&refer.expr) else {
        return false;
    };
    if unwrap.method != "unwrap" {
        return false;
    }
    let Expr::MethodCall(pop) = peel_paren(&unwrap.receiver) else {
        return false;
    };
    pop.method == "pop" && path_ends(&pop.receiver, "stack")
}

fn push_sum(stmt: &Stmt) -> Option<bool> {
    let Stmt::Expr(Expr::MethodCall(push), _) = stmt else {
        return None;
    };
    if push.method != "push" || !path_ends(&push.receiver, "stack") || push.args.len() != 1 {
        return None;
    }
    let Expr::Call(to_elem) = peel_paren(&push.args[0]) else {
        return None;
    };
    if !call_ends(&to_elem.func, "to_stack_element") || to_elem.args.len() != 1 {
        return None;
    }
    let Expr::Reference(refer) = peel_paren(&to_elem.args[0]) else {
        return None;
    };
    let Expr::Call(encode) = peel_paren(&refer.expr) else {
        return None;
    };
    if !call_ends(&encode.func, "script_num_encode") || encode.args.len() != 1 {
        return None;
    }
    let Expr::Binary(bin) = peel_paren(&encode.args[0]) else {
        return None;
    };
    if !path_ends(&bin.left, "b") || !path_ends(&bin.right, "a") {
        return None;
    }
    match bin.op {
        syn::BinOp::Add(_) => Some(false),
        syn::BinOp::Sub(_) => Some(true),
        _ => None,
    }
}

struct IfChain {
    limit: i64,
    subtract: bool,
    pop: bool,
}

fn parse_if_chain(block: &Block) -> Option<IfChain> {
    let [if_stmt, arm_stmt, add_stmt, end_stmt] = block.stmts.as_slice() else {
        return None;
    };
    if_arm(let_block(if_stmt, "_if")?)?;
    add_arm(let_block(arm_stmt, "_arm")?)?;
    let (limit, subtract) = op_add_body(let_block(add_stmt, "_add")?)?;
    let pop = endif_pops(let_block(end_stmt, "_end")?)?;
    Some(IfChain {
        limit,
        subtract,
        pop,
    })
}

fn if_arm(block: &Block) -> Option<()> {
    let [skipped, empty, cond, push] = block.stmts.as_slice() else {
        return None;
    };
    if false_branch(skipped) && empty_stack(empty) && if_condition(cond) && push_executing(push) {
        Some(())
    } else {
        None
    }
}

fn false_branch(stmt: &Stmt) -> bool {
    let Stmt::Expr(Expr::If(iff), _) = stmt else {
        return false;
    };
    if !path_ends(&iff.cond, "in_false_branch") {
        return false;
    }
    let [push, inc, cont] = iff.then_branch.stmts.as_slice() else {
        return false;
    };
    push_frame(push, true) && increments_i(inc) && is_continue(cont)
}

fn push_frame(stmt: &Stmt, executing_false: bool) -> bool {
    let Stmt::Expr(expr, _) = stmt else {
        return false;
    };
    let Expr::MethodCall(call) = peel_paren(expr) else {
        return false;
    };
    if call.method != "push" || !path_ends(&call.receiver, "control_stack") || call.args.len() != 1
    {
        return false;
    }
    let Expr::Struct(frame) = peel_paren(&call.args[0]) else {
        return false;
    };
    if !path_ends_path(&frame.path, "If") || frame.fields.len() != 1 {
        return false;
    }
    let field = &frame.fields[0];
    if !matches!(field.member, syn::Member::Named(ref name) if name == "executing") {
        return false;
    }
    if executing_false {
        is_bool_lit(&field.expr, false)
    } else {
        path_ends(&field.expr, "condition")
    }
}

fn path_ends_path(path: &syn::Path, suffix: &str) -> bool {
    path.segments.last().is_some_and(|seg| seg.ident == suffix)
}

fn increments_i(stmt: &Stmt) -> bool {
    let Stmt::Expr(Expr::Binary(bin), _) = stmt else {
        return false;
    };
    matches!(bin.op, syn::BinOp::AddAssign(_))
        && path_ends(&bin.left, "i")
        && lit_i64(&bin.right) == Some(1)
}

fn is_continue(stmt: &Stmt) -> bool {
    matches!(stmt, Stmt::Expr(Expr::Continue(_), _))
}

fn empty_stack(stmt: &Stmt) -> bool {
    let Stmt::Expr(Expr::If(iff), _) = stmt else {
        return false;
    };
    let Expr::MethodCall(call) = peel_paren(&iff.cond) else {
        return false;
    };
    call.method == "is_empty"
        && path_ends(&call.receiver, "stack")
        && dispatch_returns_err(&iff.then_branch)
}

fn if_condition(stmt: &Stmt) -> bool {
    let Some(init) = local_init(stmt, "condition") else {
        return false;
    };
    let Expr::Try(tried) = peel_paren(init) else {
        return false;
    };
    let Expr::Call(call) = peel_paren(&tried.expr) else {
        return false;
    };
    call_ends(&call.func, "pop_if_condition")
        && call.args.len() == 4
        && path_ends(&call.args[0], "stack")
}

fn push_executing(stmt: &Stmt) -> bool {
    push_frame(stmt, false)
}

fn endif_pops(block: &Block) -> Option<bool> {
    let [stmt] = block.stmts.as_slice() else {
        return None;
    };
    let Stmt::Expr(Expr::If(iff), _) = stmt else {
        return None;
    };
    let Expr::MethodCall(is_none) = peel_paren(&iff.cond) else {
        return None;
    };
    if is_none.method != "is_none" || !dispatch_returns_err(&iff.then_branch) {
        return None;
    }
    let Expr::MethodCall(inner) = peel_paren(&is_none.receiver) else {
        return None;
    };
    if !path_ends(&inner.receiver, "control_stack") {
        return None;
    }
    if inner.method == "pop" {
        Some(true)
    } else if inner.method == "len" {
        Some(false)
    } else {
        None
    }
}

struct ApplyTx {
    removes: bool,
    inserts: bool,
}

/// The whole `apply_transaction_with_id` body. `removes` is the `utxo_set.remove`
/// arm. `inserts` is `utxo_set.insert`, not the later `or_insert_with` repair.
fn parse_apply_tx(block: &Block) -> Option<ApplyTx> {
    let [
        empty_in,
        empty_out,
        height,
        undo,
        initial,
        reserve,
        spend,
        outputs,
        repair,
        final_len,
        bounds,
        cap,
        ok,
    ] = block.stmts.as_slice()
    else {
        return None;
    };
    if !apply_empty_inputs(empty_in)
        || !apply_empty_outputs(empty_out)
        || !apply_height_limit(height)
        || !apply_undo_init(undo)
        || !apply_set_len(initial, "initial_utxo_count")
        || !apply_reserve(reserve)
        || !apply_repair(repair)
        || !apply_set_len(final_len, "final_utxo_count")
        || !apply_bounds(bounds)
        || !apply_u32_cap(cap)
        || !apply_ok(ok)
    {
        return None;
    }
    Some(ApplyTx {
        removes: apply_spend(spend)?,
        inserts: apply_outputs(outputs)?,
    })
}

fn apply_if(stmt: &Stmt) -> Option<&syn::ExprIf> {
    let Stmt::Expr(Expr::If(iff), _) = stmt else {
        return None;
    };
    Some(iff)
}

fn apply_empty_inputs(stmt: &Stmt) -> bool {
    let Some(iff) = apply_if(stmt) else {
        return false;
    };
    let Expr::Binary(bin) = peel_paren(&iff.cond) else {
        return false;
    };
    if !matches!(bin.op, syn::BinOp::And(_)) || !dispatch_returns_err(&iff.then_branch) {
        return false;
    }
    let Expr::MethodCall(empty) = peel_paren(&bin.left) else {
        return false;
    };
    let Expr::Unary(not) = peel_paren(&bin.right) else {
        return false;
    };
    empty.method == "is_empty"
        && tx_field(&empty.receiver, "inputs")
        && matches!(not.op, syn::UnOp::Not(_))
        && call_is_coinbase(&not.expr)
}

fn apply_empty_outputs(stmt: &Stmt) -> bool {
    let Some(iff) = apply_if(stmt) else {
        return false;
    };
    let Expr::MethodCall(empty) = peel_paren(&iff.cond) else {
        return false;
    };
    empty.method == "is_empty"
        && tx_field(&empty.receiver, "outputs")
        && dispatch_returns_err(&iff.then_branch)
}

fn apply_height_limit(stmt: &Stmt) -> bool {
    let Some(iff) = apply_if(stmt) else {
        return false;
    };
    let Expr::Binary(bin) = peel_paren(&iff.cond) else {
        return false;
    };
    if !matches!(bin.op, syn::BinOp::Gt(_)) || !path_ends(&bin.left, "height") {
        return false;
    }
    let Expr::Cast(cast) = peel_paren(&bin.right) else {
        return false;
    };
    path_ends(&cast.expr, "MAX") && dispatch_returns_err(&iff.then_branch)
}

fn apply_undo_init(stmt: &Stmt) -> bool {
    let Some(init) = local_init(stmt, "undo_entries") else {
        return false;
    };
    let Expr::If(iff) = peel_paren(init) else {
        return false;
    };
    if !path_ends(&iff.cond, "collect_undo") {
        return false;
    }
    let Some((_, else_expr)) = iff.else_branch.as_ref() else {
        return false;
    };
    let Expr::Block(else_block) = else_expr.as_ref() else {
        return false;
    };
    block_calls(&iff.then_branch, "with_capacity") && block_calls(&else_block.block, "new")
}

fn apply_set_len(stmt: &Stmt, name: &str) -> bool {
    local_init(stmt, name).is_some_and(|init| {
        let Expr::MethodCall(call) = peel_paren(init) else {
            return false;
        };
        call.method == "len" && path_ends(&call.receiver, "utxo_set")
    })
}

fn apply_reserve(stmt: &Stmt) -> bool {
    let Stmt::Expr(Expr::Block(block), _) = stmt else {
        return false;
    };
    let [estimated, guard] = block.block.stmts.as_slice() else {
        return false;
    };
    let Some(init) = local_init(estimated, "estimated_new_size") else {
        return false;
    };
    let Expr::MethodCall(sub) = peel_paren(init) else {
        return false;
    };
    if sub.method != "saturating_sub" || !block_calls(&block.block, "reserve") {
        return false;
    }
    let Some(iff) = apply_if(guard) else {
        return false;
    };
    let Expr::Binary(bin) = peel_paren(&iff.cond) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Gt(_)) && path_ends(&bin.left, "estimated_new_size")
}

fn apply_spend(stmt: &Stmt) -> Option<bool> {
    let iff = apply_if(stmt)?;
    if !not_coinbase(&iff.cond) {
        return None;
    }
    let [loop_stmt] = iff.then_branch.stmts.as_slice() else {
        return None;
    };
    let Stmt::Expr(Expr::ForLoop(lp), _) = loop_stmt else {
        return None;
    };
    if !pat_ident(&lp.pat, "input") || !ref_tx_field(&lp.expr, "inputs") {
        return None;
    }
    let [null_if, take_if] = lp.body.stmts.as_slice() else {
        return None;
    };
    let null = apply_if(null_if)?;
    if !dispatch_returns_err(&null.then_branch) || !prevout_null(&null.cond) {
        return None;
    }
    let take = apply_if(take_if)?;
    let Expr::Let(binder) = peel_paren(&take.cond) else {
        return None;
    };
    if !pat_some_named(&binder.pat, "arc") || !apply_spent_body(&take.then_branch) {
        return None;
    }
    if remove_call(&binder.expr) {
        Some(true)
    } else if path_ends(&binder.expr, "None") {
        Some(false)
    } else {
        None
    }
}

fn prevout_null(expr: &Expr) -> bool {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    if !matches!(bin.op, syn::BinOp::And(_)) {
        return false;
    }
    let Expr::Binary(hash) = peel_paren(&bin.left) else {
        return false;
    };
    let Expr::Binary(index) = peel_paren(&bin.right) else {
        return false;
    };
    matches!(hash.op, syn::BinOp::Eq(_))
        && matches!(index.op, syn::BinOp::Eq(_))
        && field_path_ends(&hash.left, "hash")
        && lit_i64(&index.right) == Some(0xffffffffu32 as i64)
}

fn apply_spent_body(block: &Block) -> bool {
    let [previous, bip, value, undo] = block.stmts.as_slice() else {
        return false;
    };
    local_init(previous, "previous_utxo").is_some()
        && apply_if(bip).is_some_and(|iff| block_calls(&iff.then_branch, "saturating_sub"))
        && apply_if(value)
            .is_some_and(|iff| money_cond(&iff.cond) && dispatch_returns_err(&iff.then_branch))
        && apply_if(undo).is_some_and(|iff| {
            path_ends(&iff.cond, "collect_undo") && block_calls(&iff.then_branch, "push")
        })
}

fn apply_outputs(stmt: &Stmt) -> Option<bool> {
    let Stmt::Expr(Expr::ForLoop(lp), _) = stmt else {
        return None;
    };
    if !pat_pair(&lp.pat, "i", "output") || !outputs_iter(&lp.expr) {
        return None;
    }
    let [value, outpoint, utxo, arc, undo, insert, bip] = lp.body.stmts.as_slice() else {
        return None;
    };
    if !apply_if(value)
        .is_some_and(|iff| money_cond(&iff.cond) && dispatch_returns_err(&iff.then_branch))
        || local_init(outpoint, "outpoint").is_none()
        || local_init(utxo, "utxo").is_none()
        || !arc_new(arc)
        || !apply_if(undo).is_some_and(|iff| {
            path_ends(&iff.cond, "collect_undo") && block_calls(&iff.then_branch, "push")
        })
        || !apply_if(bip).is_some_and(|iff| block_calls(&iff.then_branch, "or_insert"))
    {
        return None;
    }
    apply_insert(insert)
}

fn apply_insert(stmt: &Stmt) -> Option<bool> {
    if let Stmt::Expr(expr, _) = stmt {
        if let Expr::MethodCall(call) = peel_paren(expr) {
            if call.method == "insert" && path_ends(&call.receiver, "utxo_set") {
                return Some(true);
            }
        }
    }
    if local_init(stmt, "_kept").is_some_and(|init| path_ends(init, "utxo_arc")) {
        Some(false)
    } else {
        None
    }
}

fn apply_repair(stmt: &Stmt) -> bool {
    let Some(iff) = apply_if(stmt) else {
        return false;
    };
    if !not_coinbase(&iff.cond) {
        return false;
    }
    let [current, expected, guard] = iff.then_branch.stmts.as_slice() else {
        return false;
    };
    if !apply_set_len(current, "current_count") {
        return false;
    }
    let Some(init) = local_init(expected, "expected_count") else {
        return false;
    };
    let Expr::MethodCall(add) = peel_paren(init) else {
        return false;
    };
    if add.method != "saturating_add" {
        return false;
    }
    let Some(guard) = apply_if(guard) else {
        return false;
    };
    let Expr::Binary(bin) = peel_paren(&guard.cond) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Lt(_)) && block_calls(&guard.then_branch, "or_insert_with")
}

fn apply_bounds(stmt: &Stmt) -> bool {
    let Some(iff) = apply_if(stmt) else {
        return false;
    };
    if !call_is_coinbase(&iff.cond) {
        return false;
    }
    let else_expr = iff.else_branch.as_ref().map(|(_, e)| e.as_ref());
    let Some(Expr::Block(else_block)) = else_expr else {
        return false;
    };
    money_span(&iff.then_branch) && contains_lower(&else_block.block)
}

fn contains_lower(block: &Block) -> bool {
    block.stmts.iter().any(|stmt| match stmt {
        Stmt::Local(local) => local
            .init
            .as_ref()
            .is_some_and(|init| matches!(init.expr.as_ref(), Expr::Unary(_))),
        Stmt::Expr(Expr::If(iff), _) => {
            let Expr::Binary(bin) = peel_paren(&iff.cond) else {
                return false;
            };
            matches!(bin.op, syn::BinOp::Lt(_)) && dispatch_returns_err(&iff.then_branch)
        }
        _ => false,
    }) && block.stmts.len() >= 2
}

fn money_span(block: &Block) -> bool {
    let [guard] = block.stmts.as_slice() else {
        return false;
    };
    let Some(iff) = apply_if(guard) else {
        return false;
    };
    let Expr::Binary(bin) = peel_paren(&iff.cond) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Or(_)) && dispatch_returns_err(&iff.then_branch)
}

fn apply_u32_cap(stmt: &Stmt) -> bool {
    let Some(iff) = apply_if(stmt) else {
        return false;
    };
    let Expr::Binary(bin) = peel_paren(&iff.cond) else {
        return false;
    };
    if !matches!(bin.op, syn::BinOp::Gt(_)) {
        return false;
    }
    let Expr::MethodCall(len) = peel_paren(&bin.left) else {
        return false;
    };
    let Expr::Cast(cast) = peel_paren(&bin.right) else {
        return false;
    };
    len.method == "len"
        && path_ends(&len.receiver, "utxo_set")
        && path_ends(&cast.expr, "MAX")
        && dispatch_returns_err(&iff.then_branch)
}

fn apply_ok(stmt: &Stmt) -> bool {
    let Stmt::Expr(expr, None) = stmt else {
        return false;
    };
    let Expr::Call(call) = peel_paren(expr) else {
        return false;
    };
    if !call_ends(&call.func, "Ok") || call.args.len() != 1 {
        return false;
    }
    let Expr::Tuple(tuple) = peel_paren(&call.args[0]) else {
        return false;
    };
    tuple.elems.len() == 2
        && path_ends(&tuple.elems[0], "utxo_set")
        && path_ends(&tuple.elems[1], "undo_entries")
}

fn tx_field(expr: &Expr, field: &str) -> bool {
    let Expr::Field(inner) = peel_paren(expr) else {
        return false;
    };
    path_ends(&inner.base, "tx")
        && matches!(inner.member, syn::Member::Named(ref name) if name == field)
}

fn ref_tx_field(expr: &Expr, field: &str) -> bool {
    let Expr::Reference(refer) = peel_paren(expr) else {
        return false;
    };
    tx_field(&refer.expr, field)
}

fn call_is_coinbase(expr: &Expr) -> bool {
    let Expr::Call(call) = peel_paren(expr) else {
        return false;
    };
    call_ends(&call.func, "is_coinbase") && call.args.len() == 1 && path_ends(&call.args[0], "tx")
}

fn not_coinbase(expr: &Expr) -> bool {
    let Expr::Unary(not) = peel_paren(expr) else {
        return false;
    };
    matches!(not.op, syn::UnOp::Not(_)) && call_is_coinbase(&not.expr)
}

fn pat_ident(pat: &syn::Pat, name: &str) -> bool {
    let syn::Pat::Ident(ident) = pat else {
        return false;
    };
    ident.ident == name
}

fn pat_pair(pat: &syn::Pat, left: &str, right: &str) -> bool {
    let syn::Pat::Tuple(tuple) = pat else {
        return false;
    };
    tuple.elems.len() == 2 && pat_ident(&tuple.elems[0], left) && pat_ident(&tuple.elems[1], right)
}

fn outputs_iter(expr: &Expr) -> bool {
    let Expr::MethodCall(enumerate) = peel_paren(expr) else {
        return false;
    };
    if enumerate.method != "enumerate" {
        return false;
    }
    let Expr::MethodCall(iter) = peel_paren(&enumerate.receiver) else {
        return false;
    };
    iter.method == "iter" && tx_field(&iter.receiver, "outputs")
}

fn field_path_ends(expr: &Expr, field: &str) -> bool {
    let Expr::Field(inner) = peel_paren(expr) else {
        return false;
    };
    matches!(inner.member, syn::Member::Named(ref name) if name == field)
}

fn remove_call(expr: &Expr) -> bool {
    let Expr::MethodCall(call) = peel_paren(expr) else {
        return false;
    };
    call.method == "remove" && path_ends(&call.receiver, "utxo_set")
}

fn money_cond(expr: &Expr) -> bool {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    if !matches!(bin.op, syn::BinOp::Or(_)) {
        return false;
    }
    let Expr::Binary(low) = peel_paren(&bin.left) else {
        return false;
    };
    let Expr::Binary(high) = peel_paren(&bin.right) else {
        return false;
    };
    matches!(low.op, syn::BinOp::Lt(_))
        && matches!(high.op, syn::BinOp::Gt(_))
        && path_ends(&high.right, "MAX_MONEY")
}

fn arc_new(stmt: &Stmt) -> bool {
    let Some(init) = local_init(stmt, "utxo_arc") else {
        return false;
    };
    let Expr::Call(call) = peel_paren(init) else {
        return false;
    };
    call_ends(&call.func, "new") && call.args.len() == 1 && path_ends(&call.args[0], "utxo")
}

fn block_calls(block: &Block, method: &str) -> bool {
    fn walk(expr: &Expr, method: &str) -> bool {
        match expr {
            Expr::MethodCall(call) => {
                call.method == method
                    || walk(&call.receiver, method)
                    || call.args.iter().any(|arg| walk(arg, method))
            }
            Expr::Call(call) => {
                call_ends(&call.func, method) || call.args.iter().any(|arg| walk(arg, method))
            }
            Expr::If(iff) => {
                walk(&iff.cond, method)
                    || iff
                        .then_branch
                        .stmts
                        .iter()
                        .any(|stmt| stmt_calls(stmt, method))
                    || iff
                        .else_branch
                        .as_ref()
                        .is_some_and(|(_, expr)| walk(expr, method))
            }
            Expr::ForLoop(lp) => lp.body.stmts.iter().any(|stmt| stmt_calls(stmt, method)),
            Expr::Block(block) => block
                .block
                .stmts
                .iter()
                .any(|stmt| stmt_calls(stmt, method)),
            Expr::Closure(closure) => walk(&closure.body, method),
            Expr::Binary(bin) => walk(&bin.left, method) || walk(&bin.right, method),
            Expr::Unary(unary) => walk(&unary.expr, method),
            Expr::Assign(assign) => walk(&assign.left, method) || walk(&assign.right, method),
            Expr::Field(field) => walk(&field.base, method),
            Expr::Reference(refer) => walk(&refer.expr, method),
            Expr::Paren(paren) => walk(&paren.expr, method),
            _ => false,
        }
    }
    fn stmt_calls(stmt: &Stmt, method: &str) -> bool {
        match stmt {
            Stmt::Local(local) => local
                .init
                .as_ref()
                .is_some_and(|init| walk(&init.expr, method)),
            Stmt::Expr(expr, _) => walk(expr, method),
            _ => false,
        }
    }
    block.stmts.iter().any(|stmt| stmt_calls(stmt, method))
}

struct DisabledOpcode {
    gate: Option<i64>,
    disabled: bool,
    /// `ScriptErrorCode::DisabledOpcode` is variant 14 in source order.
    code: i64,
}

/// An arm whose body is `Err(ScriptErrorWithCode { code, message })`.
/// A leading `stack.len() < N` returns `Ok(false)`. `code` is `DisabledOpcode`
/// or the census rename `OkTrueBypass`.
fn parse_disabled_opcode(block: &Block) -> Option<DisabledOpcode> {
    let (gate, err) = match block.stmts.as_slice() {
        [err] => (None, err),
        [gate, err] => (Some(early_ok_false(gate)?), err),
        _ => return None,
    };
    let disabled = disabled_err(err)?;
    Some(DisabledOpcode {
        gate,
        disabled,
        code: 14,
    })
}

/// The arm calls `op_*_disabled`, and that function returns the disabled error.
/// The short-stack `Ok(false)` is the census boundary prepended to both.
fn parse_disabled_call(block: &Block, callee: &str, message: &str) -> Option<DisabledOpcode> {
    let (gate, call, body) = match block.stmts.as_slice() {
        [call, body] => (None, call, body),
        [gate, call, body] => (Some(early_ok_false(gate)?), call, body),
        _ => return None,
    };
    if !disabled_callee(call, callee) {
        return None;
    }
    let err = let_block(body, "_body")?;
    let [err_stmt] = err.stmts.as_slice() else {
        return None;
    };
    let disabled = disabled_err(err_stmt)?;
    if !err_mentions(err_stmt, message) {
        return None;
    }
    Some(DisabledOpcode {
        gate,
        disabled,
        code: 14,
    })
}

/// `OP_VER` fails with the disabled opcode only while the branch is executing.
/// A short stack returning `Ok(false)` is the census boundary.
fn parse_op_ver(block: &Block) -> Option<DisabledOpcode> {
    let (gate, stmt) = match block.stmts.as_slice() {
        [stmt] => (None, stmt),
        [gate, stmt] => (Some(early_ok_false(gate)?), stmt),
        _ => return None,
    };
    let Stmt::Expr(Expr::If(iff), _) = stmt else {
        return None;
    };
    if iff.else_branch.is_some() || !ver_not_executing(&iff.cond) {
        return None;
    }
    let [err_stmt] = iff.then_branch.stmts.as_slice() else {
        return None;
    };
    let disabled = disabled_err(err_stmt)?;
    if !err_mentions(err_stmt, "OP_VER is disabled") {
        return None;
    }
    Some(DisabledOpcode {
        gate,
        disabled,
        code: 14,
    })
}

fn ver_not_executing(expr: &Expr) -> bool {
    let Expr::Unary(not_branch) = peel_paren(expr) else {
        return false;
    };
    matches!(not_branch.op, syn::UnOp::Not(_)) && path_is(&not_branch.expr, "in_false_branch")
}

struct MultisigVerify {
    gate: Option<i64>,
    gone: bool,
}

fn parse_multisig_verify(block: &Block) -> Option<MultisigVerify> {
    let stmts = block.stmts.as_slice();
    let (gate, base) = match stmts.len() {
        4 => (None, 0),
        5 => (Some(early_ok_false(&stmts[0])?), 1),
        _ => return None,
    };
    if !msv_context(&stmts[base]) {
        return None;
    }
    let gone = msv_call(&stmts[base + 1])?;
    if !msv_not_result(&stmts[base + 2]) || !msv_verify_pop(&stmts[base + 3]) {
        return None;
    }
    Some(MultisigVerify { gate, gone })
}

fn msv_context(stmt: &Stmt) -> bool {
    let Some(init) = local_init(stmt, "ctx_checkmultisig") else {
        return false;
    };
    let Expr::Struct(ctx) = peel_paren(init) else {
        return false;
    };
    if !path_ends_path(&ctx.path, "ScriptContext") {
        return false;
    }
    let names = [
        "tx",
        "input_index",
        "prevout_values",
        "prevout_script_pubkeys",
        "block_height",
        "median_time_past",
        "network",
        "sigversion",
        "redeem_script_for_sighash",
        "script_sig_for_sighash",
        "tapscript_for_sighash",
        "tapscript_codesep_pos",
        "taproot_annex_hash",
        "tapscript_validation_weight",
        "schnorr_collector",
        "precomputed_bip143",
        "sighash_cache",
    ];
    if ctx.fields.len() != names.len() {
        return false;
    }
    ctx.fields.iter().zip(names).all(|(field, name)| {
        if !named_member(&field.member, name) {
            return false;
        }
        match name {
            "taproot_annex_hash" | "schnorr_collector" => path_is(&field.expr, "None"),
            "tapscript_validation_weight" => {
                field_of(&field.expr, "ctx", "tapscript_validation_weight")
            }
            _ => path_is(&field.expr, name),
        }
    })
}

fn msv_call(stmt: &Stmt) -> Option<bool> {
    let init = local_init(stmt, "result")?;
    let Expr::Try(tried) = peel_paren(init) else {
        return None;
    };
    let Expr::Call(call) = peel_paren(&tried.expr) else {
        return None;
    };
    if call.args.len() != 5
        || !path_is(&call.args[0], "OP_CHECKMULTISIG")
        || !path_is(&call.args[1], "stack")
        || !path_is(&call.args[2], "flags")
        || !ref_path(&call.args[3], "ctx_checkmultisig")
        || !path_is(&call.args[4], "redeem_script_for_sighash")
    {
        return None;
    }
    if call_ends(&call.func, "execute_opcode_with_context_full") {
        Some(false)
    } else if call_ends(&call.func, "gone_exec") {
        Some(true)
    } else {
        None
    }
}

fn msv_not_result(stmt: &Stmt) -> bool {
    let Stmt::Expr(Expr::If(iff), _) = stmt else {
        return false;
    };
    iff.else_branch.is_none()
        && returns_ok_bool(&iff.then_branch, false)
        && is_not_path(&iff.cond, "result")
}

fn msv_verify_pop(stmt: &Stmt) -> bool {
    let Stmt::Expr(Expr::If(iff), _) = stmt else {
        return false;
    };
    let Expr::Let(binder) = peel_paren(&iff.cond) else {
        return false;
    };
    if !msv_some_top(&binder.pat) || !pop_call(&binder.expr) {
        return false;
    }
    let Some((_, else_expr)) = &iff.else_branch else {
        return false;
    };
    msv_pop_body(&iff.then_branch) && ok_false_expr(else_expr)
}

fn msv_pop_body(block: &Block) -> bool {
    let [check, done] = block.stmts.as_slice() else {
        return false;
    };
    let Stmt::Expr(Expr::If(iff), _) = check else {
        return false;
    };
    if iff.else_branch.is_some() || !returns_ok_bool(&iff.then_branch, false) {
        return false;
    }
    let Expr::Unary(not_top) = peel_paren(&iff.cond) else {
        return false;
    };
    if !matches!(not_top.op, syn::UnOp::Not(_)) || !cast_top(&not_top.expr) {
        return false;
    }
    let Stmt::Expr(done, None) = done else {
        return false;
    };
    ok_bool_expr(done, true)
}

fn msv_some_top(pat: &syn::Pat) -> bool {
    let syn::Pat::TupleStruct(tuple) = pat else {
        return false;
    };
    path_ends_path(&tuple.path, "Some")
        && tuple.elems.len() == 1
        && matches!(&tuple.elems[0], syn::Pat::Ident(ident) if ident.ident == "top")
}

fn pop_call(expr: &Expr) -> bool {
    let Expr::MethodCall(call) = peel_paren(expr) else {
        return false;
    };
    call.method == "pop" && call.args.is_empty() && path_is(&call.receiver, "stack")
}

fn cast_top(expr: &Expr) -> bool {
    let Expr::Call(call) = peel_paren(expr) else {
        return false;
    };
    if !call_ends(&call.func, "cast_to_bool") || call.args.len() != 1 {
        return false;
    }
    ref_path(&call.args[0], "top")
}

fn is_not_path(expr: &Expr, name: &str) -> bool {
    let Expr::Unary(unary) = peel_paren(expr) else {
        return false;
    };
    matches!(unary.op, syn::UnOp::Not(_)) && path_is(&unary.expr, name)
}

#[derive(Clone, Copy)]
enum Bip143End {
    Version,
    Lock,
    Absent,
}

struct Bip143Layout {
    start: Bip143End,
    end: Bip143End,
    amount_be: bool,
}

#[derive(PartialEq)]
enum BipTok {
    Version,
    Lock,
    Prevouts,
    SeqHash,
    LetInput,
    Prevout,
    Index,
    Varint,
    Script,
    Amount(bool),
    Sequence,
    Outputs,
    Sighash,
    OkHash,
}

fn parse_bip143(block: &Block) -> Option<Bip143Layout> {
    let mut toks = Vec::new();
    for stmt in &block.stmts {
        toks.push(bip_tok(stmt)?);
    }
    let (start, mut i) = match toks.first()? {
        BipTok::Version => (Bip143End::Version, 1usize),
        BipTok::Lock => (Bip143End::Lock, 1),
        BipTok::Prevouts => (Bip143End::Absent, 0),
        _ => return None,
    };
    let mut amount_be = false;
    for kind in 0..10 {
        let tok = toks.get(i)?;
        let ok = match (kind, tok) {
            (0, BipTok::Prevouts) => true,
            (1, BipTok::SeqHash) => true,
            (2, BipTok::LetInput) => true,
            (3, BipTok::Prevout) => true,
            (4, BipTok::Index) => true,
            (5, BipTok::Varint) => true,
            (6, BipTok::Script) => true,
            (7, BipTok::Amount(be)) => {
                amount_be = *be;
                true
            }
            (8, BipTok::Sequence) => true,
            (9, BipTok::Outputs) => true,
            _ => false,
        };
        if !ok {
            return None;
        }
        i += 1;
    }
    let end = match (start, toks.get(i)?) {
        (Bip143End::Lock, BipTok::Version) => Bip143End::Version,
        (Bip143End::Version | Bip143End::Absent, BipTok::Lock) => Bip143End::Lock,
        _ => return None,
    };
    i += 1;
    if !matches!(toks.get(i)?, BipTok::Sighash) {
        return None;
    }
    i += 1;
    if !matches!(toks.get(i)?, BipTok::OkHash) {
        return None;
    }
    if i + 1 != toks.len() {
        return None;
    }
    Some(Bip143Layout {
        start,
        end,
        amount_be,
    })
}

fn bip_tok(stmt: &Stmt) -> Option<BipTok> {
    if let Some(arg) = extend_arg(stmt) {
        return extend_tok(arg);
    }
    if prevouts_if(stmt) {
        return Some(BipTok::Prevouts);
    }
    if seq_if(stmt) {
        return Some(BipTok::SeqHash);
    }
    if is_let_input(stmt) {
        return Some(BipTok::LetInput);
    }
    if is_script_varint(stmt) {
        return Some(BipTok::Varint);
    }
    if outputs_if(stmt) {
        return Some(BipTok::Outputs);
    }
    if is_ok_digest(stmt) {
        return Some(BipTok::OkHash);
    }
    None
}

fn extend_arg(stmt: &Stmt) -> Option<&Expr> {
    let Expr::MethodCall(call) = peel_paren(stmt_expr(stmt)?) else {
        return None;
    };
    if call.method != "extend_from_slice" || call.args.len() != 1 {
        return None;
    }
    if !path_is(&call.receiver, "preimage") {
        return None;
    }
    Some(&call.args[0])
}

fn extend_tok(arg: &Expr) -> Option<BipTok> {
    let inner = peel_refs(arg);
    if le_cast_field(inner, "tx", "version") {
        return Some(BipTok::Version);
    }
    if le_cast_field(inner, "tx", "lock_time") {
        return Some(BipTok::Lock);
    }
    if le_cast_field(inner, "input", "sequence") {
        return Some(BipTok::Sequence);
    }
    if le_cast_path(inner, "sighash_type") {
        return Some(BipTok::Sighash);
    }
    if let Some(be) = amount_endian(inner) {
        return Some(BipTok::Amount(be));
    }
    if is_prevout_index(inner) {
        return Some(BipTok::Index);
    }
    if is_prevout_hash(inner) {
        return Some(BipTok::Prevout);
    }
    if path_is(inner, "script_code") {
        return Some(BipTok::Script);
    }
    None
}

fn le_cast_field(expr: &Expr, root: &str, field: &str) -> bool {
    let Expr::MethodCall(call) = peel_paren(expr) else {
        return false;
    };
    if call.method != "to_le_bytes" || !call.args.is_empty() {
        return false;
    }
    let Expr::Cast(cast) = peel_paren(&call.receiver) else {
        return false;
    };
    field_of_path(&cast.expr, root, field)
}

fn le_cast_path(expr: &Expr, name: &str) -> bool {
    let Expr::MethodCall(call) = peel_paren(expr) else {
        return false;
    };
    if call.method != "to_le_bytes" || !call.args.is_empty() {
        return false;
    }
    let Expr::Cast(cast) = peel_paren(&call.receiver) else {
        return false;
    };
    path_is(&cast.expr, name)
}

fn amount_endian(expr: &Expr) -> Option<bool> {
    let Expr::MethodCall(call) = peel_paren(expr) else {
        return None;
    };
    if !path_is(&call.receiver, "amount") || !call.args.is_empty() {
        return None;
    }
    if call.method == "to_le_bytes" {
        Some(false)
    } else if call.method == "to_be_bytes" {
        Some(true)
    } else {
        None
    }
}

fn is_prevout_index(expr: &Expr) -> bool {
    let Expr::MethodCall(call) = peel_paren(expr) else {
        return false;
    };
    call.method == "to_le_bytes" && call.args.is_empty() && prevout_field(&call.receiver, "index")
}

fn is_prevout_hash(expr: &Expr) -> bool {
    prevout_field(expr, "hash")
}

fn prevout_field(expr: &Expr, field: &str) -> bool {
    let Expr::Field(outer) = peel_paren(expr) else {
        return false;
    };
    if !named_member(&outer.member, field) {
        return false;
    }
    field_of_path(&outer.base, "input", "prevout")
}

fn field_of_path(expr: &Expr, root: &str, field: &str) -> bool {
    let Expr::Field(field_expr) = peel_paren(expr) else {
        return false;
    };
    named_member(&field_expr.member, field) && path_is(&field_expr.base, root)
}

fn prevouts_if(stmt: &Stmt) -> bool {
    hash_or_zero(
        stmt,
        |cond| path_is(cond, "anyone_can_pay"),
        "hash_prevouts",
    )
}

fn seq_if(stmt: &Stmt) -> bool {
    hash_or_zero(
        stmt,
        |cond| flag_or(cond, &["anyone_can_pay", "is_none", "is_single"]),
        "hash_sequence",
    )
}

fn hash_or_zero(stmt: &Stmt, cond_ok: impl Fn(&Expr) -> bool, field: &str) -> bool {
    let Some(expr) = stmt_expr(stmt) else {
        return false;
    };
    let Expr::If(gate) = peel_paren(expr) else {
        return false;
    };
    if !cond_ok(&gate.cond) {
        return false;
    }
    let Some(then_stmt) = bip_one_stmt(&gate.then_branch) else {
        return false;
    };
    if !is_zero_extend(then_stmt) {
        return false;
    }
    let Some(branch) = gate.else_branch.as_ref() else {
        return false;
    };
    let Some(else_stmt) = else_stmt(branch) else {
        return false;
    };
    is_hashes_extend(else_stmt, field)
}

fn flag_or(expr: &Expr, names: &[&str]) -> bool {
    let mut found = Vec::new();
    if !collect_or(peel_paren(expr), &mut found) {
        return false;
    }
    found.sort();
    let mut expect: Vec<String> = names.iter().map(|name| (*name).to_string()).collect();
    expect.sort();
    found == expect
}

fn collect_or(expr: &Expr, found: &mut Vec<String>) -> bool {
    match peel_paren(expr) {
        Expr::Binary(bin) if matches!(bin.op, syn::BinOp::Or(_)) => {
            collect_or(&bin.left, found) && collect_or(&bin.right, found)
        }
        Expr::Path(path) => {
            let Some(seg) = path.path.segments.last() else {
                return false;
            };
            found.push(seg.ident.to_string());
            true
        }
        _ => false,
    }
}

fn bip_one_stmt(block: &Block) -> Option<&Stmt> {
    let [stmt] = block.stmts.as_slice() else {
        return None;
    };
    Some(stmt)
}

fn else_stmt(branch: &(syn::token::Else, Box<Expr>)) -> Option<&Stmt> {
    let Expr::Block(block) = peel_paren(&branch.1) else {
        return None;
    };
    bip_one_stmt(&block.block)
}

fn is_zero_extend(stmt: &Stmt) -> bool {
    let Some(arg) = extend_arg(stmt) else {
        return false;
    };
    let Expr::Repeat(rep) = peel_refs(arg) else {
        return false;
    };
    lit_i64(&rep.expr) == Some(0) && lit_i64(&rep.len) == Some(32)
}

fn is_hashes_extend(stmt: &Stmt, field: &str) -> bool {
    let Some(arg) = extend_arg(stmt) else {
        return false;
    };
    field_of_path(peel_refs(arg), "hashes", field)
}

fn is_let_input(stmt: &Stmt) -> bool {
    let Some((name, init)) = bip_local(stmt) else {
        return false;
    };
    if name != "input" {
        return false;
    }
    let Expr::Index(index) = peel_refs(init) else {
        return false;
    };
    field_of_path(&index.expr, "tx", "inputs") && path_is(&index.index, "input_index")
}

fn is_script_varint(stmt: &Stmt) -> bool {
    let Some(expr) = stmt_expr(stmt) else {
        return false;
    };
    let Expr::Call(call) = peel_paren(expr) else {
        return false;
    };
    if !call_ends(&call.func, "write_varint_to_vec") || call.args.len() != 2 {
        return false;
    }
    if !path_is(&call.args[0], "preimage") {
        return false;
    }
    let Expr::Cast(cast) = peel_paren(&call.args[1]) else {
        return false;
    };
    let Expr::MethodCall(len) = peel_paren(&cast.expr) else {
        return false;
    };
    len.method == "len" && path_is(&len.receiver, "script_code")
}

fn outputs_if(stmt: &Stmt) -> bool {
    let Some(expr) = stmt_expr(stmt) else {
        return false;
    };
    let Expr::If(outer) = peel_paren(expr) else {
        return false;
    };
    if !path_is(&outer.cond, "is_none") {
        return false;
    }
    let Some(then_stmt) = bip_one_stmt(&outer.then_branch) else {
        return false;
    };
    if !is_zero_extend(then_stmt) {
        return false;
    }
    let Some(branch) = outer.else_branch.as_ref() else {
        return false;
    };
    let Expr::If(single) = peel_paren(branch.1.as_ref()) else {
        return false;
    };
    if !path_is(&single.cond, "is_single") {
        return false;
    }
    if !single_in_range(&single.then_branch) {
        return false;
    }
    let Some(else_branch) = single.else_branch.as_ref() else {
        return false;
    };
    let Some(else_stmt) = else_stmt(else_branch) else {
        return false;
    };
    is_hashes_extend(else_stmt, "hash_outputs")
}

fn single_in_range(block: &Block) -> bool {
    let Some(stmt) = bip_one_stmt(block) else {
        return false;
    };
    let Some(expr) = stmt_expr(stmt) else {
        return false;
    };
    let Expr::If(inner) = peel_paren(expr) else {
        return false;
    };
    if !index_lt_outputs(&inner.cond) {
        return false;
    }
    if !output_hash_block(&inner.then_branch) {
        return false;
    }
    let Some(branch) = inner.else_branch.as_ref() else {
        return false;
    };
    let Some(else_stmt) = else_stmt(branch) else {
        return false;
    };
    is_zero_extend(else_stmt)
}

fn index_lt_outputs(expr: &Expr) -> bool {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    if !matches!(bin.op, syn::BinOp::Lt(_)) {
        return false;
    }
    if !path_is(&bin.left, "input_index") {
        return false;
    }
    let Expr::MethodCall(len) = peel_paren(&bin.right) else {
        return false;
    };
    len.method == "len" && field_of_path(&len.receiver, "tx", "outputs")
}

fn output_hash_block(block: &Block) -> bool {
    let stmts = &block.stmts;
    if stmts.len() < 3 {
        return false;
    }
    if !is_let_named(&stmts[0], "output", true) {
        return false;
    }
    if !is_path_extend(stmts.last().unwrap(), "hash_outputs") {
        return false;
    }
    let mids = &stmts[1..stmts.len() - 1];
    (mids.len() == 1 || mids.len() == 2) && mids.iter().all(output_digest_let)
}

fn is_let_named(stmt: &Stmt, name: &str, index_output: bool) -> bool {
    let Some((got, init)) = bip_local(stmt) else {
        return false;
    };
    if got != name {
        return false;
    }
    if !index_output {
        return true;
    }
    let Expr::Index(index) = peel_refs(init) else {
        return false;
    };
    field_of_path(&index.expr, "tx", "outputs") && path_is(&index.index, "input_index")
}

fn is_path_extend(stmt: &Stmt, name: &str) -> bool {
    extend_arg(stmt).is_some_and(|arg| path_is(arg, name))
}

fn output_digest_let(stmt: &Stmt) -> bool {
    let Some((name, init)) = bip_local(stmt) else {
        return false;
    };
    if name != "hash_outputs" {
        return false;
    }
    let mut marks = OutputMarks::default();
    mark_expr(init, &mut marks);
    marks.value_le && marks.varint && marks.script && marks.digest
}

#[derive(Default)]
struct OutputMarks {
    value_le: bool,
    varint: bool,
    script: bool,
    digest: bool,
}

fn mark_expr(expr: &Expr, marks: &mut OutputMarks) {
    match expr {
        Expr::Call(call) => {
            if call_ends(&call.func, "write_varint_to_vec") {
                marks.varint = true;
            }
            if call_ends(&call.func, "double_sha256") {
                marks.digest = true;
            }
            mark_expr(&call.func, marks);
            for arg in &call.args {
                mark_expr(arg, marks);
            }
        }
        Expr::MethodCall(call) => {
            if call.method == "to_le_bytes" {
                if let Expr::Field(field) = peel_refs(&call.receiver) {
                    if named_member(&field.member, "value") {
                        marks.value_le = true;
                    }
                }
            }
            if call.method == "extend_from_slice" && call.args.len() == 1 {
                if let Expr::Field(field) = peel_refs(&call.args[0]) {
                    if named_member(&field.member, "script_pubkey") {
                        marks.script = true;
                    }
                }
            }
            mark_expr(&call.receiver, marks);
            for arg in &call.args {
                mark_expr(arg, marks);
            }
        }
        Expr::Closure(closure) => mark_expr(&closure.body, marks),
        Expr::Block(block) => {
            for stmt in &block.block.stmts {
                mark_stmt(stmt, marks);
            }
        }
        Expr::Reference(reference) => mark_expr(&reference.expr, marks),
        Expr::Paren(paren) => mark_expr(&paren.expr, marks),
        Expr::Cast(cast) => mark_expr(&cast.expr, marks),
        Expr::Field(field) => mark_expr(&field.base, marks),
        Expr::Unary(unary) => mark_expr(&unary.expr, marks),
        Expr::Binary(bin) => {
            mark_expr(&bin.left, marks);
            mark_expr(&bin.right, marks);
        }
        Expr::Index(index) => {
            mark_expr(&index.expr, marks);
            mark_expr(&index.index, marks);
        }
        Expr::If(gate) => {
            mark_expr(&gate.cond, marks);
            for stmt in &gate.then_branch.stmts {
                mark_stmt(stmt, marks);
            }
            if let Some((_, else_expr)) = &gate.else_branch {
                mark_expr(else_expr, marks);
            }
        }
        Expr::Let(let_expr) => mark_expr(&let_expr.expr, marks),
        Expr::Assign(assign) => {
            mark_expr(&assign.left, marks);
            mark_expr(&assign.right, marks);
        }
        _ => {}
    }
}

fn mark_stmt(stmt: &Stmt, marks: &mut OutputMarks) {
    match stmt {
        Stmt::Local(local) => {
            if let Some(init) = &local.init {
                mark_expr(&init.expr, marks);
            }
        }
        Stmt::Expr(expr, _) => mark_expr(expr, marks),
        Stmt::Item(_) | Stmt::Macro(_) => {}
    }
}

fn bip_local(stmt: &Stmt) -> Option<(String, &Expr)> {
    let Stmt::Local(local) = stmt else {
        return None;
    };
    let syn::Pat::Ident(pat) = &local.pat else {
        return None;
    };
    let init = local.init.as_ref()?;
    Some((pat.ident.to_string(), &init.expr))
}

fn is_ok_digest(stmt: &Stmt) -> bool {
    let Some(expr) = stmt_expr(stmt) else {
        return false;
    };
    let Expr::Call(ok) = peel_paren(expr) else {
        return false;
    };
    if !call_ends(&ok.func, "Ok") || ok.args.len() != 1 {
        return false;
    }
    let Expr::Call(hash) = peel_paren(&ok.args[0]) else {
        return false;
    };
    call_ends(&hash.func, "double_sha256")
        && hash.args.len() == 1
        && path_is(&hash.args[0], "preimage")
}

#[derive(Clone, Copy)]
enum LegSlot {
    Version,
    Lock,
    Absent,
}

struct LegacyLayout {
    start: LegSlot,
    end: LegSlot,
    version_be: bool,
    quirk_byte: i64,
}

fn parse_legacy_sighash(block: &Block) -> Option<LegacyLayout> {
    let stmts = &block.stmts;
    let mut i = 0usize;
    if !is_sha_use(stmts.get(i)?) {
        return None;
    }
    i += 1;
    if !is_cast_let(stmts.get(i)?, "sighash_u32", "sighash_byte") {
        return None;
    }
    i += 1;
    if !is_mask_let(stmts.get(i)?, "base_type", "sighash_u32", 0x1f) {
        return None;
    }
    i += 1;
    if !is_mask_ne_zero(stmts.get(i)?, "anyone_can_pay", "sighash_u32", 0x80) {
        return None;
    }
    i += 1;
    if !is_eq_lit_let(stmts.get(i)?, "hash_none", "base_type", 2) {
        return None;
    }
    i += 1;
    if !is_eq_lit_let(stmts.get(i)?, "hash_single", "base_type", 3) {
        return None;
    }
    i += 1;
    let quirk_byte = single_quirk_byte(stmts.get(i)?)?;
    i += 1;
    if !is_sha_hasher(stmts.get(i)?) {
        return None;
    }
    i += 1;
    let (start, mut version_be) = if let Some(be) = version_update(stmts.get(i)?) {
        i += 1;
        (LegSlot::Version, be)
    } else if lock_update(stmts.get(i)?) {
        i += 1;
        (LegSlot::Lock, false)
    } else {
        (LegSlot::Absent, false)
    };
    if !is_n_inputs(stmts.get(i)?) {
        return None;
    }
    i += 1;
    if !is_varint_path(stmts.get(i)?, "n_inputs") {
        return None;
    }
    i += 1;
    if !is_input_loop(stmts.get(i)?) {
        return None;
    }
    i += 1;
    if !is_n_outputs(stmts.get(i)?) {
        return None;
    }
    i += 1;
    if !is_varint_path(stmts.get(i)?, "n_outputs") {
        return None;
    }
    i += 1;
    if !is_output_loop(stmts.get(i)?) {
        return None;
    }
    i += 1;
    let end = match start {
        LegSlot::Lock => {
            version_be = version_update(stmts.get(i)?)?;
            i += 1;
            LegSlot::Version
        }
        LegSlot::Version | LegSlot::Absent => {
            if !lock_update(stmts.get(i)?) {
                return None;
            }
            i += 1;
            LegSlot::Lock
        }
    };
    if !is_sighash_update(stmts.get(i)?) {
        return None;
    }
    i += 1;
    if !is_finalize(stmts.get(i)?) {
        return None;
    }
    i += 1;
    if !is_sha_digest(stmts.get(i)?) {
        return None;
    }
    i += 1;
    if !is_result_array(stmts.get(i)?) {
        return None;
    }
    i += 1;
    if !is_copy_hash(stmts.get(i)?) {
        return None;
    }
    i += 1;
    if !is_tail_path(stmts.get(i)?, "result") {
        return None;
    }
    if i + 1 != stmts.len() {
        return None;
    }
    Some(LegacyLayout {
        start,
        end,
        version_be,
        quirk_byte,
    })
}

fn is_sha_use(stmt: &Stmt) -> bool {
    let Stmt::Item(syn::Item::Use(item)) = stmt else {
        return false;
    };
    use_has(&item.tree, "Sha256") && use_has(&item.tree, "Digest")
}

fn use_has(tree: &syn::UseTree, name: &str) -> bool {
    match tree {
        syn::UseTree::Name(node) => node.ident == name,
        syn::UseTree::Rename(node) => node.ident == name || node.rename == name,
        syn::UseTree::Path(node) => node.ident == name || use_has(&node.tree, name),
        syn::UseTree::Group(node) => node.items.iter().any(|item| use_has(item, name)),
        syn::UseTree::Glob(_) => false,
    }
}

fn let_named<'a>(stmt: &'a Stmt, name: &str) -> Option<&'a Expr> {
    let (got, init) = bip_local(stmt)?;
    (got == name).then_some(init)
}

fn is_cast_let(stmt: &Stmt, name: &str, src: &str) -> bool {
    let Some(init) = let_named(stmt, name) else {
        return false;
    };
    let Expr::Cast(cast) = peel_paren(init) else {
        return false;
    };
    path_is(&cast.expr, src)
}

fn is_mask_let(stmt: &Stmt, name: &str, src: &str, mask: i64) -> bool {
    let Some(init) = let_named(stmt, name) else {
        return false;
    };
    let Expr::Binary(bin) = peel_paren(init) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::BitAnd(_))
        && path_is(&bin.left, src)
        && lit_i64(&bin.right) == Some(mask)
}

fn is_mask_ne_zero(stmt: &Stmt, name: &str, src: &str, mask: i64) -> bool {
    let Some(init) = let_named(stmt, name) else {
        return false;
    };
    let Expr::Binary(bin) = peel_paren(init) else {
        return false;
    };
    if !matches!(bin.op, syn::BinOp::Ne(_)) || lit_i64(&bin.right) != Some(0) {
        return false;
    }
    let Expr::Binary(mask_bin) = peel_paren(&bin.left) else {
        return false;
    };
    matches!(mask_bin.op, syn::BinOp::BitAnd(_))
        && path_is(&mask_bin.left, src)
        && lit_i64(&mask_bin.right) == Some(mask)
}

fn is_eq_lit_let(stmt: &Stmt, name: &str, src: &str, value: i64) -> bool {
    let Some(init) = let_named(stmt, name) else {
        return false;
    };
    let Expr::Binary(bin) = peel_paren(init) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Eq(_))
        && path_is(&bin.left, src)
        && lit_i64(&bin.right) == Some(value)
}

fn single_quirk_byte(stmt: &Stmt) -> Option<i64> {
    let expr = stmt_expr(stmt)?;
    let Expr::If(gate) = peel_paren(expr) else {
        return None;
    };
    if !quirk_cond(&gate.cond) || gate.else_branch.is_some() {
        return None;
    }
    let stmts = &gate.then_branch.stmts;
    if !is_result_array(stmts.first()?) {
        return None;
    }
    match stmts.len() {
        2 if is_return_path(&stmts[1], "result") => Some(0),
        3 if is_return_path(&stmts[2], "result") => result_byte(&stmts[1]),
        _ => None,
    }
}

fn quirk_cond(expr: &Expr) -> bool {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    if !matches!(bin.op, syn::BinOp::And(_)) || !path_is(&bin.left, "hash_single") {
        return false;
    }
    let Expr::Binary(cmp) = peel_paren(&bin.right) else {
        return false;
    };
    if !matches!(cmp.op, syn::BinOp::Ge(_)) || !path_is(&cmp.left, "input_index") {
        return false;
    }
    let Expr::MethodCall(len) = peel_paren(&cmp.right) else {
        return false;
    };
    len.method == "len" && field_of_path(&len.receiver, "tx", "outputs")
}

fn is_result_array(stmt: &Stmt) -> bool {
    let Some(init) = let_named(stmt, "result") else {
        return false;
    };
    let Expr::Repeat(rep) = peel_paren(init) else {
        return false;
    };
    lit_i64(&rep.expr) == Some(0) && lit_i64(&rep.len) == Some(32)
}

fn result_byte(stmt: &Stmt) -> Option<i64> {
    let expr = stmt_expr(stmt)?;
    let Expr::Assign(assign) = peel_paren(expr) else {
        return None;
    };
    let Expr::Index(index) = peel_paren(&assign.left) else {
        return None;
    };
    if path_is(&index.expr, "result") && lit_i64(&index.index) == Some(0) {
        lit_i64(&assign.right)
    } else {
        None
    }
}

fn is_return_path(stmt: &Stmt, name: &str) -> bool {
    let Stmt::Expr(Expr::Return(ret), _) = stmt else {
        return false;
    };
    ret.expr.as_ref().is_some_and(|expr| path_is(expr, name))
}

fn is_tail_path(stmt: &Stmt, name: &str) -> bool {
    let Stmt::Expr(expr, semi) = stmt else {
        return false;
    };
    semi.is_none() && path_is(expr, name)
}

fn is_sha_hasher(stmt: &Stmt) -> bool {
    let Some(init) = let_named(stmt, "h") else {
        return false;
    };
    let Expr::Call(call) = peel_paren(init) else {
        return false;
    };
    call.args.is_empty() && path_ends(&call.func, "new") && path_has(&call.func, "Sha256")
}

fn path_has(expr: &Expr, name: &str) -> bool {
    let Expr::Path(path) = expr else {
        return false;
    };
    path_to_string(&path.path).contains(name)
}

fn version_update(stmt: &Stmt) -> Option<bool> {
    let arg = update_arg(stmt)?;
    let Expr::MethodCall(call) = peel_paren(arg) else {
        return None;
    };
    if !call.args.is_empty() {
        return None;
    }
    let be = if call.method == "to_le_bytes" {
        false
    } else if call.method == "to_be_bytes" {
        true
    } else {
        return None;
    };
    let Expr::Cast(cast) = peel_paren(&call.receiver) else {
        return None;
    };
    field_of_path(&cast.expr, "tx", "version").then_some(be)
}

fn lock_update(stmt: &Stmt) -> bool {
    update_arg(stmt).is_some_and(|arg| le_cast_field(arg, "tx", "lock_time"))
}

fn is_sighash_update(stmt: &Stmt) -> bool {
    let Some(arg) = update_arg(stmt) else {
        return false;
    };
    let Expr::MethodCall(call) = peel_paren(arg) else {
        return false;
    };
    call.method == "to_le_bytes" && call.args.is_empty() && path_is(&call.receiver, "sighash_u32")
}

fn update_arg(stmt: &Stmt) -> Option<&Expr> {
    let Expr::MethodCall(call) = peel_paren(stmt_expr(stmt)?) else {
        return None;
    };
    if call.method != "update" || call.args.len() != 1 || !path_is(&call.receiver, "h") {
        return None;
    }
    Some(&call.args[0])
}

fn is_n_inputs(stmt: &Stmt) -> bool {
    let Some(init) = let_named(stmt, "n_inputs") else {
        return false;
    };
    let Expr::If(gate) = peel_paren(init) else {
        return false;
    };
    path_is(&gate.cond, "anyone_can_pay")
        && sole_lit(&gate.then_branch, 1)
        && else_len(gate.else_branch.as_ref(), "inputs")
}

fn is_n_outputs(stmt: &Stmt) -> bool {
    let Some(init) = let_named(stmt, "n_outputs") else {
        return false;
    };
    let Expr::If(gate) = peel_paren(init) else {
        return false;
    };
    if !path_is(&gate.cond, "hash_none") || !sole_lit(&gate.then_branch, 0) {
        return false;
    }
    let Some(else_arm) = gate.else_branch.as_ref().and_then(else_expr) else {
        return false;
    };
    let Expr::If(single) = else_arm else {
        return false;
    };
    path_is(&single.cond, "hash_single")
        && sole_plus_one(&single.then_branch, "input_index")
        && else_len(single.else_branch.as_ref(), "outputs")
}

fn sole_expr(block: &Block) -> Option<&Expr> {
    let [stmt] = block.stmts.as_slice() else {
        return None;
    };
    stmt_expr(stmt)
}

fn sole_lit(block: &Block, value: i64) -> bool {
    sole_expr(block).is_some_and(|expr| lit_i64(expr) == Some(value))
}

fn sole_path(block: &Block, name: &str) -> bool {
    sole_expr(block).is_some_and(|expr| path_is(expr, name))
}

fn sole_plus_one(block: &Block, name: &str) -> bool {
    let Some(Expr::Binary(bin)) = sole_expr(block).map(peel_paren) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Add(_))
        && path_is(&bin.left, name)
        && lit_i64(&bin.right) == Some(1)
}

fn else_expr(branch: &(syn::token::Else, Box<Expr>)) -> Option<&Expr> {
    Some(peel_paren(&branch.1))
}

fn else_len(branch: Option<&(syn::token::Else, Box<Expr>)>, field: &str) -> bool {
    let Some(expr) = branch.and_then(else_expr) else {
        return false;
    };
    let Expr::Block(block) = expr else {
        return false;
    };
    let Some(Expr::MethodCall(len)) = sole_expr(&block.block).map(peel_paren) else {
        return false;
    };
    len.method == "len" && field_of_path(&len.receiver, "tx", field)
}

fn is_varint_path(stmt: &Stmt, name: &str) -> bool {
    varint_value(stmt).is_some_and(|value| {
        let Expr::Cast(cast) = peel_paren(value) else {
            return false;
        };
        path_is(&cast.expr, name)
    })
}

fn varint_value(stmt: &Stmt) -> Option<&Expr> {
    let expr = stmt_expr(stmt)?;
    let Expr::Call(call) = peel_paren(expr) else {
        return None;
    };
    if !path_ends(&call.func, "update_varint")
        || call.args.len() != 2
        || !path_is(&call.args[0], "h")
    {
        return None;
    }
    Some(&call.args[1])
}

fn is_input_loop(stmt: &Stmt) -> bool {
    let Some(body) = for_over(stmt, "i", "n_inputs") else {
        return false;
    };
    let stmts = &body.stmts;
    stmts.len() == 6
        && is_actual_i(&stmts[0])
        && is_let_tx_index(&stmts[1], "input", "inputs", "actual_i")
        && update_arg(&stmts[2]).is_some_and(|arg| prevout_field(arg, "hash"))
        && is_prevout_index_update(&stmts[3])
        && is_script_branch(&stmts[4])
        && is_sequence_branch(&stmts[5])
}

fn is_output_loop(stmt: &Stmt) -> bool {
    let Some(body) = for_over(stmt, "i", "n_outputs") else {
        return false;
    };
    let [stmt] = body.stmts.as_slice() else {
        return false;
    };
    let Some(expr) = stmt_expr(stmt) else {
        return false;
    };
    let Expr::If(gate) = peel_paren(expr) else {
        return false;
    };
    output_single_cond(&gate.cond)
        && output_blank(&gate.then_branch)
        && output_real(gate.else_branch.as_ref())
}

fn for_over<'a>(stmt: &'a Stmt, var: &str, end_name: &str) -> Option<&'a Block> {
    let Expr::ForLoop(lp) = stmt_expr(stmt)? else {
        return None;
    };
    let syn::Pat::Ident(pat) = &*lp.pat else {
        return None;
    };
    if pat.ident != var || !range_to(&lp.expr, end_name) {
        return None;
    }
    Some(&lp.body)
}

fn range_to(expr: &Expr, end_name: &str) -> bool {
    let Expr::Range(range) = peel_paren(expr) else {
        return false;
    };
    matches!(range.limits, syn::RangeLimits::HalfOpen(_))
        && range
            .start
            .as_ref()
            .is_some_and(|start| lit_i64(start) == Some(0))
        && range.end.as_ref().is_some_and(|end| path_is(end, end_name))
}

fn is_actual_i(stmt: &Stmt) -> bool {
    let Some(init) = let_named(stmt, "actual_i") else {
        return false;
    };
    let Expr::If(gate) = peel_paren(init) else {
        return false;
    };
    path_is(&gate.cond, "anyone_can_pay")
        && sole_path(&gate.then_branch, "input_index")
        && else_path(gate.else_branch.as_ref(), "i")
}

fn else_path(branch: Option<&(syn::token::Else, Box<Expr>)>, name: &str) -> bool {
    let Some(Expr::Block(block)) = branch.and_then(else_expr) else {
        return false;
    };
    sole_path(&block.block, name)
}

fn is_let_tx_index(stmt: &Stmt, name: &str, field: &str, index_name: &str) -> bool {
    let Some(init) = let_named(stmt, name) else {
        return false;
    };
    let Expr::Index(index) = peel_refs(init) else {
        return false;
    };
    field_of_path(&index.expr, "tx", field) && path_is(&index.index, index_name)
}

fn is_prevout_index_update(stmt: &Stmt) -> bool {
    let Some(arg) = update_arg(stmt) else {
        return false;
    };
    let Expr::MethodCall(call) = peel_paren(arg) else {
        return false;
    };
    call.method == "to_le_bytes" && call.args.is_empty() && prevout_field(&call.receiver, "index")
}

fn is_script_branch(stmt: &Stmt) -> bool {
    let Some(expr) = stmt_expr(stmt) else {
        return false;
    };
    let Expr::If(gate) = peel_paren(expr) else {
        return false;
    };
    if !is_eq_paths(&gate.cond, "actual_i", "input_index") {
        return false;
    }
    let then = &gate.then_branch.stmts;
    if then.len() != 2 || !is_varint_script(&then[0]) || !is_update_path(&then[1], "script_code") {
        return false;
    }
    let Some(else_stmt) = else_one(gate.else_branch.as_ref()) else {
        return false;
    };
    is_update_array(else_stmt)
}

fn is_sequence_branch(stmt: &Stmt) -> bool {
    let Some(expr) = stmt_expr(stmt) else {
        return false;
    };
    let Expr::If(gate) = peel_paren(expr) else {
        return false;
    };
    if !sequence_cond(&gate.cond) {
        return false;
    }
    let Some(then_stmt) = bip_one_stmt(&gate.then_branch) else {
        return false;
    };
    if !is_update_zero_le(then_stmt) {
        return false;
    }
    let Some(else_stmt) = else_one(gate.else_branch.as_ref()) else {
        return false;
    };
    update_arg(else_stmt).is_some_and(|arg| le_cast_field(arg, "input", "sequence"))
}

fn sequence_cond(expr: &Expr) -> bool {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::And(_))
        && is_ne_paths(&bin.left, "actual_i", "input_index")
        && flag_or(&bin.right, &["hash_single", "hash_none"])
}

fn is_eq_paths(expr: &Expr, left: &str, right: &str) -> bool {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Eq(_)) && path_is(&bin.left, left) && path_is(&bin.right, right)
}

fn is_ne_paths(expr: &Expr, left: &str, right: &str) -> bool {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Ne(_)) && path_is(&bin.left, left) && path_is(&bin.right, right)
}

fn is_varint_script(stmt: &Stmt) -> bool {
    varint_value(stmt).is_some_and(|value| {
        let Expr::Cast(cast) = peel_paren(value) else {
            return false;
        };
        let Expr::MethodCall(len) = peel_paren(&cast.expr) else {
            return false;
        };
        len.method == "len" && path_is(&len.receiver, "script_code")
    })
}

fn is_update_path(stmt: &Stmt, name: &str) -> bool {
    update_arg(stmt).is_some_and(|arg| path_is(arg, name))
}

fn is_update_array(stmt: &Stmt) -> bool {
    update_arg(stmt).is_some_and(|arg| {
        let Expr::Array(arr) = peel_paren(arg) else {
            return false;
        };
        arr.elems.len() == 1 && lit_i64(&arr.elems[0]) == Some(0)
    })
}

fn is_update_zero_le(stmt: &Stmt) -> bool {
    update_arg(stmt).is_some_and(|arg| {
        let Expr::MethodCall(call) = peel_paren(arg) else {
            return false;
        };
        call.method == "to_le_bytes" && lit_i64(&call.receiver) == Some(0)
    })
}

fn else_one(branch: Option<&(syn::token::Else, Box<Expr>)>) -> Option<&Stmt> {
    let Expr::Block(block) = branch.and_then(else_expr)? else {
        return None;
    };
    bip_one_stmt(&block.block)
}

fn output_single_cond(expr: &Expr) -> bool {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::And(_))
        && path_is(&bin.left, "hash_single")
        && is_ne_paths(&bin.right, "i", "input_index")
}

fn output_blank(block: &Block) -> bool {
    let stmts = &block.stmts;
    stmts.len() == 2 && is_neg_one_update(&stmts[0]) && is_update_array(&stmts[1])
}

fn is_neg_one_update(stmt: &Stmt) -> bool {
    update_arg(stmt).is_some_and(|arg| {
        let Expr::MethodCall(call) = peel_paren(arg) else {
            return false;
        };
        if call.method != "to_le_bytes" {
            return false;
        }
        let recv = peel_paren(&call.receiver);
        if lit_i64(recv) == Some(-1) {
            return true;
        }
        let Expr::Unary(unary) = recv else {
            return false;
        };
        matches!(unary.op, syn::UnOp::Neg(_)) && lit_i64(&unary.expr) == Some(1)
    })
}

fn output_real(branch: Option<&(syn::token::Else, Box<Expr>)>) -> bool {
    let Some(Expr::Block(block)) = branch.and_then(else_expr) else {
        return false;
    };
    let stmts = &block.block.stmts;
    stmts.len() == 4
        && is_let_tx_index(&stmts[0], "output", "outputs", "i")
        && is_value_update(&stmts[1])
        && is_varint_script_pubkey(&stmts[2])
        && is_script_slice(&stmts[3])
}

fn is_value_update(stmt: &Stmt) -> bool {
    update_arg(stmt).is_some_and(|arg| {
        let Expr::MethodCall(call) = peel_paren(arg) else {
            return false;
        };
        call.method == "to_le_bytes"
            && call.args.is_empty()
            && field_of_path(&call.receiver, "output", "value")
    })
}

fn is_varint_script_pubkey(stmt: &Stmt) -> bool {
    varint_value(stmt).is_some_and(|value| {
        let Expr::Cast(cast) = peel_paren(value) else {
            return false;
        };
        let Expr::MethodCall(len) = peel_paren(&cast.expr) else {
            return false;
        };
        len.method == "len" && field_of_path(&len.receiver, "output", "script_pubkey")
    })
}

fn is_script_slice(stmt: &Stmt) -> bool {
    update_arg(stmt).is_some_and(|arg| {
        let Expr::MethodCall(call) = peel_paren(arg) else {
            return false;
        };
        call.method == "as_slice"
            && call.args.is_empty()
            && field_of_path(&call.receiver, "output", "script_pubkey")
    })
}

fn is_finalize(stmt: &Stmt) -> bool {
    let Some(init) = let_named(stmt, "first_hash") else {
        return false;
    };
    let Expr::MethodCall(call) = peel_paren(init) else {
        return false;
    };
    call.method == "finalize" && call.args.is_empty() && path_is(&call.receiver, "h")
}

fn is_sha_digest(stmt: &Stmt) -> bool {
    let Some(init) = let_named(stmt, "second_hash") else {
        return false;
    };
    let Expr::Call(call) = peel_paren(init) else {
        return false;
    };
    path_ends(&call.func, "digest")
        && path_has(&call.func, "Sha256")
        && call.args.len() == 1
        && path_is(&call.args[0], "first_hash")
}

fn is_copy_hash(stmt: &Stmt) -> bool {
    let Some(expr) = stmt_expr(stmt) else {
        return false;
    };
    let Expr::MethodCall(call) = peel_paren(expr) else {
        return false;
    };
    call.method == "copy_from_slice"
        && path_is(&call.receiver, "result")
        && call.args.len() == 1
        && path_is(&call.args[0], "second_hash")
}

struct FindDelete {
    empty_lt: bool,
    stride_one: bool,
}

fn parse_find_delete(block: &Block) -> Option<FindDelete> {
    let stmts = &block.stmts;
    let mut i = 0usize;
    let empty_lt = empty_return(stmts.get(i)?)?;
    i += 1;
    if !len_return(stmts.get(i)?) {
        return None;
    }
    i += 1;
    if !windows_return(stmts.get(i)?) {
        return None;
    }
    i += 1;
    if !is_len_let(stmts.get(i)?, "end", "script") {
        return None;
    }
    i += 1;
    if !is_zero_let(stmts.get(i)?, "n_found") {
        return None;
    }
    i += 1;
    if !is_vec_new(stmts.get(i)?) {
        return None;
    }
    i += 1;
    if !is_zero_let(stmts.get(i)?, "pc") {
        return None;
    }
    i += 1;
    if !is_zero_let(stmts.get(i)?, "pc2") {
        return None;
    }
    i += 1;
    let stride_one = delete_loop(stmts.get(i)?)?;
    i += 1;
    if !owned_tail(stmts.get(i)?) {
        return None;
    }
    if i + 1 != stmts.len() {
        return None;
    }
    Some(FindDelete {
        empty_lt,
        stride_one,
    })
}

fn empty_return(stmt: &Stmt) -> Option<bool> {
    let cond = borrowed_if(stmt)?;
    if is_method_path(cond, "pattern", "is_empty") {
        Some(false)
    } else if is_len_lt_zero(cond) {
        Some(true)
    } else {
        None
    }
}

fn is_len_lt_zero(expr: &Expr) -> bool {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Lt(_))
        && is_len_call(&bin.left, "pattern")
        && lit_i64(&bin.right) == Some(0)
}

fn len_return(stmt: &Stmt) -> bool {
    borrowed_if(stmt).is_some_and(|cond| is_len_gt_len(cond, "pattern", "script"))
}

fn borrowed_if(stmt: &Stmt) -> Option<&Expr> {
    let expr = stmt_expr(stmt)?;
    let Expr::If(gate) = peel_paren(expr) else {
        return None;
    };
    if gate.else_branch.is_some() {
        return None;
    }
    let [then_stmt] = gate.then_branch.stmts.as_slice() else {
        return None;
    };
    is_return_borrowed(then_stmt).then_some(&gate.cond)
}

fn is_return_borrowed(stmt: &Stmt) -> bool {
    let Stmt::Expr(Expr::Return(ret), _) = stmt else {
        return false;
    };
    ret.expr
        .as_ref()
        .is_some_and(|expr| is_cow(expr, "Borrowed", "script"))
}

fn is_cow(expr: &Expr, name: &str, arg: &str) -> bool {
    let Expr::Call(call) = peel_paren(expr) else {
        return false;
    };
    path_ends(&call.func, name)
        && path_has(&call.func, "Cow")
        && call.args.len() == 1
        && path_is(&call.args[0], arg)
}

fn is_method_path(expr: &Expr, recv: &str, method: &str) -> bool {
    let Expr::MethodCall(call) = peel_paren(expr) else {
        return false;
    };
    call.method == method && call.args.is_empty() && path_is(&call.receiver, recv)
}

fn is_len_call(expr: &Expr, recv: &str) -> bool {
    let Expr::MethodCall(call) = peel_paren(expr) else {
        return false;
    };
    call.method == "len" && call.args.is_empty() && path_is(&call.receiver, recv)
}

fn is_len_gt_len(expr: &Expr, left: &str, right: &str) -> bool {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Gt(_))
        && is_len_call(&bin.left, left)
        && is_len_call(&bin.right, right)
}

fn windows_return(stmt: &Stmt) -> bool {
    let Some(cond) = borrowed_if(stmt) else {
        return false;
    };
    let Expr::Unary(unary) = peel_paren(cond) else {
        return false;
    };
    if !matches!(unary.op, syn::UnOp::Not(_)) {
        return false;
    }
    let Expr::MethodCall(any) = peel_paren(&unary.expr) else {
        return false;
    };
    if any.method != "any" || any.args.len() != 1 || !closure_eq_pattern(&any.args[0]) {
        return false;
    }
    let Expr::MethodCall(windows) = peel_paren(&any.receiver) else {
        return false;
    };
    windows.method == "windows"
        && path_is(&windows.receiver, "script")
        && windows.args.len() == 1
        && is_len_call(&windows.args[0], "pattern")
}

fn closure_eq_pattern(expr: &Expr) -> bool {
    let Expr::Closure(closure) = peel_paren(expr) else {
        return false;
    };
    let mut inputs = closure.inputs.iter();
    let Some(syn::Pat::Ident(pat)) = inputs.next() else {
        return false;
    };
    if pat.ident != "w" || inputs.next().is_some() {
        return false;
    }
    let body = match peel_paren(&closure.body) {
        Expr::Block(block) => {
            let Some(expr) = sole_expr(&block.block) else {
                return false;
            };
            expr
        }
        other => other,
    };
    is_eq_paths(body, "w", "pattern")
}

fn is_len_let(stmt: &Stmt, name: &str, recv: &str) -> bool {
    let_named(stmt, name).is_some_and(|init| is_len_call(init, recv))
}

fn is_zero_let(stmt: &Stmt, name: &str) -> bool {
    let_named(stmt, name).is_some_and(|init| lit_i64(init) == Some(0))
}

fn is_vec_new(stmt: &Stmt) -> bool {
    let Some(init) = let_named(stmt, "result") else {
        return false;
    };
    let Expr::Call(call) = peel_paren(init) else {
        return false;
    };
    call.args.is_empty() && path_ends(&call.func, "new") && path_has(&call.func, "Vec")
}

fn delete_loop(stmt: &Stmt) -> Option<bool> {
    let Expr::Loop(lp) = stmt_expr(stmt)? else {
        return None;
    };
    let stmts = &lp.body.stmts;
    if stmts.len() != 6
        || !is_extend_range(&stmts[0], "pc2", "pc")
        || !is_assign_paths(&stmts[2], "pc2", "pc")
        || !is_pc_end(&stmts[3])
        || !is_let_advance(&stmts[4])
        || !is_assign_paths(&stmts[5], "pc", "next_pc")
    {
        return None;
    }
    delete_while(&stmts[1])
}

fn delete_while(stmt: &Stmt) -> Option<bool> {
    let Expr::While(wh) = stmt_expr(stmt)? else {
        return None;
    };
    if !delete_cond(&wh.cond) {
        return None;
    }
    let [step, inc] = wh.body.stmts.as_slice() else {
        return None;
    };
    is_found_inc(inc)
        .then_some(())
        .and_then(|_| stride_one(step))
}

fn delete_cond(expr: &Expr) -> bool {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    if !matches!(bin.op, syn::BinOp::And(_)) {
        return false;
    }
    let Expr::Binary(ge) = peel_paren(&bin.left) else {
        return false;
    };
    if !matches!(ge.op, syn::BinOp::Ge(_))
        || !is_end_minus_pc(&ge.left)
        || !is_len_call(&ge.right, "pattern")
    {
        return false;
    }
    let Expr::Binary(eq) = peel_paren(&bin.right) else {
        return false;
    };
    matches!(eq.op, syn::BinOp::Eq(_)) && is_match_slice(&eq.left) && is_deref_pattern(&eq.right)
}

fn is_end_minus_pc(expr: &Expr) -> bool {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Sub(_)) && path_is(&bin.left, "end") && path_is(&bin.right, "pc")
}

fn is_match_slice(expr: &Expr) -> bool {
    let Expr::Index(index) = peel_paren(expr) else {
        return false;
    };
    if !path_is(&index.expr, "script") {
        return false;
    }
    let Expr::Range(range) = peel_paren(&index.index) else {
        return false;
    };
    matches!(range.limits, syn::RangeLimits::HalfOpen(_))
        && range
            .start
            .as_ref()
            .is_some_and(|start| path_is(start, "pc"))
        && range.end.as_ref().is_some_and(|end| is_pc_plus_len(end))
}

fn is_pc_plus_len(expr: &Expr) -> bool {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Add(_))
        && path_is(&bin.left, "pc")
        && is_len_call(&bin.right, "pattern")
}

fn is_deref_pattern(expr: &Expr) -> bool {
    let Expr::Unary(unary) = peel_paren(expr) else {
        return false;
    };
    matches!(unary.op, syn::UnOp::Deref(_)) && path_is(&unary.expr, "pattern")
}

fn stride_one(stmt: &Stmt) -> Option<bool> {
    let expr = stmt_expr(stmt)?;
    let Expr::Binary(bin) = peel_paren(expr) else {
        return None;
    };
    if !matches!(bin.op, syn::BinOp::AddAssign(_)) || !path_is(&bin.left, "pc") {
        return None;
    }
    if lit_i64(&bin.right) == Some(1) {
        Some(true)
    } else if is_len_call(&bin.right, "pattern") {
        Some(false)
    } else {
        None
    }
}

fn is_found_inc(stmt: &Stmt) -> bool {
    let Some(expr) = stmt_expr(stmt) else {
        return false;
    };
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::AddAssign(_))
        && path_is(&bin.left, "n_found")
        && lit_i64(&bin.right) == Some(1)
}

fn is_extend_range(stmt: &Stmt, start: &str, end: &str) -> bool {
    let Some(expr) = stmt_expr(stmt) else {
        return false;
    };
    let Expr::MethodCall(call) = peel_paren(expr) else {
        return false;
    };
    call.method == "extend_from_slice"
        && path_is(&call.receiver, "result")
        && call.args.len() == 1
        && is_script_range(&call.args[0], start, end)
}

fn is_script_range(expr: &Expr, start: &str, end: &str) -> bool {
    let Expr::Index(index) = peel_refs(expr) else {
        return false;
    };
    if !path_is(&index.expr, "script") {
        return false;
    }
    let Expr::Range(range) = peel_paren(&index.index) else {
        return false;
    };
    matches!(range.limits, syn::RangeLimits::HalfOpen(_))
        && range
            .start
            .as_ref()
            .is_some_and(|bound| path_is(bound, start))
        && range.end.as_ref().is_some_and(|bound| path_is(bound, end))
}

fn is_assign_paths(stmt: &Stmt, left: &str, right: &str) -> bool {
    let Some(expr) = stmt_expr(stmt) else {
        return false;
    };
    let Expr::Assign(assign) = peel_paren(expr) else {
        return false;
    };
    path_is(&assign.left, left) && path_is(&assign.right, right)
}

fn is_pc_end(stmt: &Stmt) -> bool {
    let Some(expr) = stmt_expr(stmt) else {
        return false;
    };
    let Expr::If(gate) = peel_paren(expr) else {
        return false;
    };
    if gate.else_branch.is_some() {
        return false;
    }
    let Expr::Binary(bin) = peel_paren(&gate.cond) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Ge(_))
        && path_is(&bin.left, "pc")
        && path_is(&bin.right, "end")
        && gate.then_branch.stmts.len() == 1
        && is_break(&gate.then_branch.stmts[0])
}

fn is_break(stmt: &Stmt) -> bool {
    matches!(stmt_expr(stmt), Some(Expr::Break(_)))
}

fn is_let_advance(stmt: &Stmt) -> bool {
    let Stmt::Local(local) = stmt else {
        return false;
    };
    let syn::Pat::TupleStruct(pat) = &local.pat else {
        return false;
    };
    if path_to_string(&pat.path) != "Some" || pat.elems.len() != 1 {
        return false;
    }
    let syn::Pat::Ident(ident) = &pat.elems[0] else {
        return false;
    };
    if ident.ident != "next_pc" {
        return false;
    }
    let Some(init) = &local.init else {
        return false;
    };
    let Expr::Call(call) = peel_paren(&init.expr) else {
        return false;
    };
    if !path_ends(&call.func, "script_get_op_advance")
        || call.args.len() != 2
        || !path_is(&call.args[0], "script")
        || !path_is(&call.args[1], "pc")
    {
        return false;
    }
    let Some((_, else_expr)) = &init.diverge else {
        return false;
    };
    let Expr::Block(block) = peel_paren(else_expr) else {
        return false;
    };
    block.block.stmts.len() == 1 && is_break(&block.block.stmts[0])
}

fn owned_tail(stmt: &Stmt) -> bool {
    let Some(expr) = stmt_expr(stmt) else {
        return false;
    };
    let Expr::If(gate) = peel_paren(expr) else {
        return false;
    };
    let Expr::Binary(bin) = peel_paren(&gate.cond) else {
        return false;
    };
    if !matches!(bin.op, syn::BinOp::Gt(_))
        || !path_is(&bin.left, "n_found")
        || lit_i64(&bin.right) != Some(0)
    {
        return false;
    }
    let then = &gate.then_branch.stmts;
    if then.len() != 2
        || !is_extend_range(&then[0], "pc2", "end")
        || !is_cow_expr(&then[1], "Owned", "result")
    {
        return false;
    }
    let Some(else_branch) = gate.else_branch.as_ref() else {
        return false;
    };
    let Expr::Block(block) = peel_paren(else_branch.1.as_ref()) else {
        return false;
    };
    block.block.stmts.len() == 1 && is_cow_expr(&block.block.stmts[0], "Borrowed", "script")
}

fn is_cow_expr(stmt: &Stmt, name: &str, arg: &str) -> bool {
    stmt_expr(stmt).is_some_and(|expr| is_cow(expr, name, arg))
}

struct TapSigmsg {
    epoch: Option<i64>,
    version_first: bool,
    version_be: bool,
    lock_be: bool,
    index_be: bool,
    amount_be: bool,
    sequence_be: bool,
    input_be: bool,
    value_be: bool,
}

fn parse_tap_sigmsg(block: &Block) -> Option<TapSigmsg> {
    let stmts = &block.stmts;
    let mut i = 0usize;
    if !is_sha_use(stmts.get(i)?) {
        return None;
    }
    i += 1;
    if !is_mask_let(stmts.get(i)?, "input_type", "sighash_type", 0x80) {
        return None;
    }
    i += 1;
    if !is_output_type(stmts.get(i)?) {
        return None;
    }
    i += 1;
    if !is_precompute(stmts.get(i)?) {
        return None;
    }
    i += 1;
    if !is_sigmsg_vec(stmts.get(i)?) {
        return None;
    }
    i += 1;
    let epoch = if let Some(byte) = sig_push_lit(stmts.get(i)?) {
        i += 1;
        Some(byte)
    } else {
        None
    };
    if !sig_push_path(stmts.get(i)?, "sighash_type") {
        return None;
    }
    i += 1;
    let first = word_extend(stmts.get(i)?)?;
    i += 1;
    let second = word_extend(stmts.get(i)?)?;
    i += 1;
    let (version_first, version_be, lock_be) = match (first, second) {
        (Word::Version(version_be), Word::Lock(lock_be)) => (true, version_be, lock_be),
        (Word::Lock(lock_be), Word::Version(version_be)) => (false, version_be, lock_be),
        _ => return None,
    };
    if !common_hashes(stmts.get(i)?) {
        return None;
    }
    i += 1;
    if !outputs_hash(stmts.get(i)?) {
        return None;
    }
    i += 1;
    if !sig_push_path(stmts.get(i)?, "spend_type") {
        return None;
    }
    i += 1;
    let (index_be, amount_be, sequence_be, input_be) = acp_input(stmts.get(i)?)?;
    i += 1;
    if !annex_push(stmts.get(i)?) {
        return None;
    }
    i += 1;
    let value_be = single_output(stmts.get(i)?)?;
    i += 1;
    if !is_ok_sigmsg(stmts.get(i)?) {
        return None;
    }
    if i + 1 != stmts.len() {
        return None;
    }
    Some(TapSigmsg {
        epoch,
        version_first,
        version_be,
        lock_be,
        index_be,
        amount_be,
        sequence_be,
        input_be,
        value_be,
    })
}

enum Word {
    Version(bool),
    Lock(bool),
}

fn sig_method<'a>(stmt: &'a Stmt, method: &str) -> Option<&'a Expr> {
    let Expr::MethodCall(call) = peel_paren(stmt_expr(stmt)?) else {
        return None;
    };
    if call.method != method || call.args.len() != 1 || !path_is(&call.receiver, "sigmsg") {
        return None;
    }
    Some(&call.args[0])
}

fn sig_push_lit(stmt: &Stmt) -> Option<i64> {
    lit_i64(sig_method(stmt, "push")?)
}

fn sig_push_path(stmt: &Stmt, name: &str) -> bool {
    sig_method(stmt, "push").is_some_and(|arg| path_is(arg, name))
}

fn word_extend(stmt: &Stmt) -> Option<Word> {
    let arg = sig_method(stmt, "extend_from_slice")?;
    let (recv, be) = endian_of(peel_refs(arg))?;
    let Expr::Cast(cast) = peel_paren(recv) else {
        return None;
    };
    if field_of_path(&cast.expr, "tx", "lock_time") {
        return Some(Word::Lock(be));
    }
    field_of_path(&cast.expr, "tx", "version").then_some(Word::Version(be))
}

fn endian_of(expr: &Expr) -> Option<(&Expr, bool)> {
    let Expr::MethodCall(call) = peel_paren(expr) else {
        return None;
    };
    if !call.args.is_empty() {
        return None;
    }
    let be = if call.method == "to_le_bytes" {
        false
    } else if call.method == "to_be_bytes" {
        true
    } else {
        return None;
    };
    Some((&call.receiver, be))
}

fn is_output_type(stmt: &Stmt) -> bool {
    let Some(init) = let_named(stmt, "output_type") else {
        return false;
    };
    let Expr::If(gate) = peel_paren(init) else {
        return false;
    };
    let Expr::Binary(eq) = peel_paren(&gate.cond) else {
        return false;
    };
    if !matches!(eq.op, syn::BinOp::Eq(_))
        || !path_is(&eq.left, "sighash_type")
        || lit_i64(&eq.right) != Some(0)
        || !sole_lit(&gate.then_branch, 1)
    {
        return false;
    }
    let Some((_, else_expr)) = &gate.else_branch else {
        return false;
    };
    let Expr::Block(block) = peel_paren(else_expr) else {
        return false;
    };
    let Some(mask_expr) = sole_expr(&block.block) else {
        return false;
    };
    let Expr::Binary(mask) = peel_paren(mask_expr) else {
        return false;
    };
    matches!(mask.op, syn::BinOp::BitAnd(_))
        && path_is(&mask.left, "sighash_type")
        && lit_i64(&mask.right) == Some(3)
}

fn is_precompute(stmt: &Stmt) -> bool {
    let Some(init) = let_named(stmt, "hashes") else {
        return false;
    };
    let Expr::Call(call) = peel_paren(init) else {
        return false;
    };
    path_ends(&call.func, "bip341_precompute")
        && call.args.len() == 3
        && path_is(&call.args[0], "tx")
        && path_is(&call.args[1], "prevout_values")
        && path_is(&call.args[2], "prevout_script_pubkeys")
}

fn is_sigmsg_vec(stmt: &Stmt) -> bool {
    let Some(init) = let_named(stmt, "sigmsg") else {
        return false;
    };
    let Expr::Call(call) = peel_paren(init) else {
        return false;
    };
    path_ends(&call.func, "with_capacity")
        && path_has(&call.func, "Vec")
        && call.args.len() == 1
        && path_is(&call.args[0], "capacity")
}

fn hash_extend(stmt: &Stmt, field: &str) -> bool {
    sig_method(stmt, "extend_from_slice")
        .is_some_and(|arg| field_of_path(peel_refs(arg), "hashes", field))
}

fn common_hashes(stmt: &Stmt) -> bool {
    let Some(expr) = stmt_expr(stmt) else {
        return false;
    };
    let Expr::If(gate) = peel_paren(expr) else {
        return false;
    };
    if gate.else_branch.is_some() || !input_ne_acp(&gate.cond) {
        return false;
    }
    let stmts = &gate.then_branch.stmts;
    stmts.len() == 4
        && hash_extend(&stmts[0], "sha_prevouts")
        && hash_extend(&stmts[1], "sha_amounts")
        && hash_extend(&stmts[2], "sha_scriptpubkeys")
        && hash_extend(&stmts[3], "sha_sequences")
}

fn outputs_hash(stmt: &Stmt) -> bool {
    let Some(expr) = stmt_expr(stmt) else {
        return false;
    };
    let Expr::If(gate) = peel_paren(expr) else {
        return false;
    };
    if gate.else_branch.is_some() || !output_eq(&gate.cond, 1) {
        return false;
    }
    gate.then_branch.stmts.len() == 1 && hash_extend(&gate.then_branch.stmts[0], "sha_outputs")
}

fn input_ne_acp(expr: &Expr) -> bool {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Ne(_))
        && path_is(&bin.left, "input_type")
        && lit_i64(&bin.right) == Some(0x80)
}

fn output_eq(expr: &Expr, value: i64) -> bool {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Eq(_))
        && path_is(&bin.left, "output_type")
        && lit_i64(&bin.right) == Some(value)
}

fn input_eq_acp(expr: &Expr) -> bool {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Eq(_))
        && path_is(&bin.left, "input_type")
        && lit_i64(&bin.right) == Some(0x80)
}

fn acp_input(stmt: &Stmt) -> Option<(bool, bool, bool, bool)> {
    let expr = stmt_expr(stmt)?;
    let Expr::If(gate) = peel_paren(expr) else {
        return None;
    };
    if !input_eq_acp(&gate.cond) {
        return None;
    }
    let then = &gate.then_branch.stmts;
    if then.len() != 9
        || !is_get_let(
            &then[0],
            "input",
            "inputs",
            "input_index out of range",
            false,
        )
        || !prevout_extend(&then[1], "hash")
        || !is_amount_let(&then[3])
        || !is_spk_let(&then[5])
        || !varint_spk(&then[6])
        || !path_extend(&then[7], "spk")
    {
        return None;
    }
    let index_be = prevout_index_extend(&then[2])?;
    let amount_be = amount_extend(&then[4])?;
    let sequence_be = sequence_extend(&then[8])?;
    let else_stmt = else_one(gate.else_branch.as_ref())?;
    let input_be = index_word(else_stmt)?;
    Some((index_be, amount_be, sequence_be, input_be))
}

fn prevout_extend(stmt: &Stmt, field: &str) -> bool {
    sig_method(stmt, "extend_from_slice").is_some_and(|arg| prevout_field(peel_refs(arg), field))
}

fn prevout_index_extend(stmt: &Stmt) -> Option<bool> {
    let arg = sig_method(stmt, "extend_from_slice")?;
    let (recv, be) = endian_of(peel_refs(arg))?;
    prevout_field(recv, "index").then_some(be)
}

fn amount_extend(stmt: &Stmt) -> Option<bool> {
    let arg = sig_method(stmt, "extend_from_slice")?;
    let (recv, be) = endian_of(peel_refs(arg))?;
    path_is(recv, "amount").then_some(be)
}

fn index_word(stmt: &Stmt) -> Option<bool> {
    let arg = sig_method(stmt, "extend_from_slice")?;
    let (recv, be) = endian_of(peel_refs(arg))?;
    let Expr::Cast(cast) = peel_paren(recv) else {
        return None;
    };
    path_is(&cast.expr, "input_index").then_some(be)
}

fn path_extend(stmt: &Stmt, name: &str) -> bool {
    sig_method(stmt, "extend_from_slice").is_some_and(|arg| path_is(arg, name))
}

fn sequence_extend(stmt: &Stmt) -> Option<bool> {
    let arg = sig_method(stmt, "extend_from_slice")?;
    let (recv, be) = endian_of(peel_refs(arg))?;
    let Expr::Cast(cast) = peel_paren(recv) else {
        return None;
    };
    field_of_path(&cast.expr, "input", "sequence").then_some(be)
}

fn varint_spk(stmt: &Stmt) -> bool {
    sig_method(stmt, "extend_from_slice").is_some_and(|arg| {
        let Expr::Call(call) = peel_paren(peel_refs(arg)) else {
            return false;
        };
        if !path_ends(&call.func, "encode_varint") || call.args.len() != 1 {
            return false;
        }
        let Expr::Cast(cast) = peel_paren(&call.args[0]) else {
            return false;
        };
        let Expr::MethodCall(len) = peel_paren(&cast.expr) else {
            return false;
        };
        len.method == "len" && path_is(&len.receiver, "spk")
    })
}

fn is_get_let(stmt: &Stmt, name: &str, field: &str, message: &str, label: bool) -> bool {
    let Some(init) = let_named(stmt, name) else {
        return false;
    };
    let Some((recv, closure)) = peel_ok_get(init) else {
        return false;
    };
    field_of_path(recv, "tx", field)
        && closure_mentions(closure, message)
        && (!label || closure_mentions(closure, "anyone_label"))
}

fn is_amount_let(stmt: &Stmt) -> bool {
    let Some(init) = let_named(stmt, "amount") else {
        return false;
    };
    let Some((recv, closure)) = peel_ok_get(init) else {
        return false;
    };
    path_is(recv, "prevout_values")
        && closure_mentions(closure, "prevout_values index out of range")
        && closure_mentions(closure, "anyone_label")
}

fn is_spk_let(stmt: &Stmt) -> bool {
    let Some(init) = let_named(stmt, "spk") else {
        return false;
    };
    let Some((recv, closure)) = peel_ok_get(init) else {
        return false;
    };
    path_is(recv, "prevout_script_pubkeys")
        && closure_mentions(closure, "prevout_script_pubkeys index out of range")
        && closure_mentions(closure, "anyone_label")
}

fn peel_ok_get(expr: &Expr) -> Option<(&Expr, &Expr)> {
    let expr = match peel_paren(expr) {
        Expr::Cast(cast) => peel_paren(&cast.expr),
        other => other,
    };
    let expr = match expr {
        Expr::Unary(unary) if matches!(unary.op, syn::UnOp::Deref(_)) => peel_paren(&unary.expr),
        other => other,
    };
    let Expr::Try(try_expr) = expr else {
        return None;
    };
    let Expr::MethodCall(ok) = peel_paren(&try_expr.expr) else {
        return None;
    };
    if ok.method != "ok_or_else" || ok.args.len() != 1 {
        return None;
    }
    let Expr::MethodCall(get) = peel_paren(&ok.receiver) else {
        return None;
    };
    if get.method != "get" || get.args.len() != 1 || !path_is(&get.args[0], "input_index") {
        return None;
    }
    Some((&get.receiver, &ok.args[0]))
}

fn closure_mentions(expr: &Expr, needle: &str) -> bool {
    let Expr::Closure(closure) = peel_paren(expr) else {
        return false;
    };
    closure.inputs.is_empty() && tree_has(&closure.body, needle)
}

fn annex_push(stmt: &Stmt) -> bool {
    let Some(expr) = stmt_expr(stmt) else {
        return false;
    };
    let Expr::If(gate) = peel_paren(expr) else {
        return false;
    };
    if gate.else_branch.is_some() {
        return false;
    }
    let Expr::Let(let_expr) = peel_paren(&gate.cond) else {
        return false;
    };
    let syn::Pat::TupleStruct(pat) = &*let_expr.pat else {
        return false;
    };
    if path_to_string(&pat.path) != "Some" || pat.elems.len() != 1 {
        return false;
    }
    let syn::Pat::Ident(ident) = &pat.elems[0] else {
        return false;
    };
    if ident.ident != "h" || !path_is(&let_expr.expr, "annex_hash") {
        return false;
    }
    gate.then_branch.stmts.len() == 1 && path_extend(&gate.then_branch.stmts[0], "h")
}

fn single_output(stmt: &Stmt) -> Option<bool> {
    let expr = stmt_expr(stmt)?;
    let Expr::If(gate) = peel_paren(expr) else {
        return None;
    };
    if gate.else_branch.is_some() || !output_eq(&gate.cond, 3) {
        return None;
    }
    let stmts = &gate.then_branch.stmts;
    if stmts.len() != 6
        || !is_output_some(&stmts[0])
        || !is_out_vec(&stmts[1])
        || !out_varint(&stmts[3])
        || !out_script(&stmts[4])
        || !out_digest(&stmts[5])
    {
        return None;
    }
    out_value(&stmts[2])
}

fn is_output_some(stmt: &Stmt) -> bool {
    let Stmt::Local(local) = stmt else {
        return false;
    };
    let syn::Pat::TupleStruct(pat) = &local.pat else {
        return false;
    };
    if path_to_string(&pat.path) != "Some" || pat.elems.len() != 1 {
        return false;
    }
    let syn::Pat::Ident(ident) = &pat.elems[0] else {
        return false;
    };
    if ident.ident != "output" {
        return false;
    }
    let Some(init) = &local.init else {
        return false;
    };
    let Expr::MethodCall(get) = peel_paren(&init.expr) else {
        return false;
    };
    if get.method != "get" || get.args.len() != 1 || !path_is(&get.args[0], "input_index") {
        return false;
    }
    if !field_of_path(&get.receiver, "tx", "outputs") {
        return false;
    }
    let Some((_, else_expr)) = &init.diverge else {
        return false;
    };
    let Expr::Block(block) = peel_paren(else_expr) else {
        return false;
    };
    block.block.stmts.len() == 1
        && is_return_sig_err(
            &block.block.stmts[0],
            "SIGHASH_SINGLE has no corresponding output",
        )
}

fn is_return_sig_err(stmt: &Stmt, needle: &str) -> bool {
    let Stmt::Expr(Expr::Return(ret), _) = stmt else {
        return false;
    };
    ret.expr.as_ref().is_some_and(|expr| {
        let Expr::Call(err) = peel_paren(expr) else {
            return false;
        };
        path_ends(&err.func, "Err")
            && err.args.len() == 1
            && tree_has(&err.args[0], "InvalidSignature")
            && tree_has(&err.args[0], needle)
    })
}

fn is_out_vec(stmt: &Stmt) -> bool {
    let Some(init) = let_named(stmt, "out_data") else {
        return false;
    };
    let Expr::Call(call) = peel_paren(init) else {
        return false;
    };
    call.args.is_empty() && path_ends(&call.func, "new") && path_has(&call.func, "Vec")
}

fn out_extend(stmt: &Stmt) -> Option<&Expr> {
    let Expr::MethodCall(call) = peel_paren(stmt_expr(stmt)?) else {
        return None;
    };
    if call.method != "extend_from_slice"
        || call.args.len() != 1
        || !path_is(&call.receiver, "out_data")
    {
        return None;
    }
    Some(&call.args[0])
}

fn out_value(stmt: &Stmt) -> Option<bool> {
    let arg = out_extend(stmt)?;
    let (recv, be) = endian_of(peel_refs(arg))?;
    let Expr::Cast(cast) = peel_paren(recv) else {
        return None;
    };
    field_of_path(&cast.expr, "output", "value").then_some(be)
}

fn out_varint(stmt: &Stmt) -> bool {
    out_extend(stmt).is_some_and(|arg| {
        let Expr::Call(call) = peel_paren(peel_refs(arg)) else {
            return false;
        };
        if !path_ends(&call.func, "encode_varint") || call.args.len() != 1 {
            return false;
        }
        let Expr::Cast(cast) = peel_paren(&call.args[0]) else {
            return false;
        };
        let Expr::MethodCall(len) = peel_paren(&cast.expr) else {
            return false;
        };
        len.method == "len" && field_of_path(&len.receiver, "output", "script_pubkey")
    })
}

fn out_script(stmt: &Stmt) -> bool {
    out_extend(stmt).is_some_and(|arg| field_of_path(peel_refs(arg), "output", "script_pubkey"))
}

fn out_digest(stmt: &Stmt) -> bool {
    sig_method(stmt, "extend_from_slice").is_some_and(|arg| {
        let Expr::Call(call) = peel_paren(peel_refs(arg)) else {
            return false;
        };
        path_ends(&call.func, "digest")
            && path_has(&call.func, "Sha256")
            && call.args.len() == 1
            && path_is(peel_refs(&call.args[0]), "out_data")
    })
}

fn is_ok_sigmsg(stmt: &Stmt) -> bool {
    let Some(expr) = stmt_expr(stmt) else {
        return false;
    };
    let Expr::Call(call) = peel_paren(expr) else {
        return false;
    };
    path_ends(&call.func, "Ok") && call.args.len() == 1 && path_is(&call.args[0], "sigmsg")
}

fn tree_has(expr: &Expr, needle: &str) -> bool {
    match expr {
        Expr::Lit(lit) => matches!(&lit.lit, syn::Lit::Str(text) if text.value().contains(needle)),
        Expr::Macro(mac) => {
            mac.mac
                .path
                .segments
                .last()
                .is_some_and(|seg| seg.ident == needle)
                || mac.mac.tokens.to_string().contains(needle)
        }
        Expr::Path(path) => path_to_string(&path.path).contains(needle),
        Expr::Call(call) => {
            tree_has(&call.func, needle) || call.args.iter().any(|arg| tree_has(arg, needle))
        }
        Expr::MethodCall(call) => {
            tree_has(&call.receiver, needle) || call.args.iter().any(|arg| tree_has(arg, needle))
        }
        Expr::Closure(closure) => tree_has(&closure.body, needle),
        Expr::Block(block) => block.block.stmts.iter().any(|stmt| stmt_has(stmt, needle)),
        Expr::Reference(reference) => tree_has(&reference.expr, needle),
        Expr::Paren(paren) => tree_has(&paren.expr, needle),
        Expr::Cast(cast) => tree_has(&cast.expr, needle),
        Expr::Unary(unary) => tree_has(&unary.expr, needle),
        Expr::Field(field) => tree_has(&field.base, needle),
        Expr::Binary(bin) => tree_has(&bin.left, needle) || tree_has(&bin.right, needle),
        Expr::Try(try_expr) => tree_has(&try_expr.expr, needle),
        Expr::Return(ret) => ret
            .expr
            .as_ref()
            .is_some_and(|inner| tree_has(inner, needle)),
        Expr::If(gate) => {
            tree_has(&gate.cond, needle)
                || gate
                    .then_branch
                    .stmts
                    .iter()
                    .any(|stmt| stmt_has(stmt, needle))
                || gate
                    .else_branch
                    .as_ref()
                    .is_some_and(|(_, else_expr)| tree_has(else_expr, needle))
        }
        _ => false,
    }
}

fn stmt_has(stmt: &Stmt, needle: &str) -> bool {
    match stmt {
        Stmt::Local(local) => local
            .init
            .as_ref()
            .is_some_and(|init| tree_has(&init.expr, needle)),
        Stmt::Expr(expr, _) => tree_has(expr, needle),
        Stmt::Item(_) | Stmt::Macro(_) => false,
    }
}

struct DataPush {
    direct: i64,
    push1: i64,
    push2: i64,
    push4: i64,
}

fn minimaldata_mask() -> Option<i64> {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../blvm-consensus/src/script/flags.rs");
    let src = std::fs::read_to_string(path).ok()?;
    let needle = "const SCRIPT_VERIFY_MINIMALDATA:";
    let rest = src.get(src.find(needle)? + needle.len()..)?;
    let expr = rest
        .get(rest.find('=')? + 1..)?
        .split(';')
        .next()?
        .trim()
        .replace(' ', "");
    let (left, right) = expr.split_once("<<")?;
    let base = left.parse::<i64>().ok()?;
    let shift = right.parse::<u32>().ok()?;
    base.checked_shl(shift)
}

fn parse_data_push(block: &Block) -> Option<DataPush> {
    if !crate::parser::spec_expr::consensus_workspace_present() {
        return None;
    }
    let stmts = &block.stmts;
    if stmts.len() != 5 {
        return None;
    }
    let init = tuple_let(stmts.first()?)?;
    let (direct_if, push1_if, push2_if, push4) = push_if_chain(init)?;
    if !is_opcode_le(&direct_if.cond, 0x4b) || !is_opcode_eq(&push1_if.cond, "OP_PUSHDATA1") {
        return None;
    }
    if !is_opcode_eq(&push2_if.cond, "OP_PUSHDATA2") {
        return None;
    }
    let direct = direct_arm(&direct_if.then_branch)?;
    let push1 = sized_arm(&push1_if.then_branch, 1, 2)?;
    let push2 = push2_arm(&push2_if.then_branch)?;
    let push4_add = wide_arm(push4)?;
    if !is_element_limit(stmts.get(1)?)
        || !is_minimal_reject(stmts.get(2)?)
        || !is_false_branch_push(stmts.get(3)?)
        || !is_some_advance(stmts.get(4)?)
    {
        return None;
    }
    Some(DataPush {
        direct,
        push1,
        push2,
        push4: push4_add,
    })
}

fn tuple_let(stmt: &Stmt) -> Option<&Expr> {
    let Stmt::Local(local) = stmt else {
        return None;
    };
    let syn::Pat::Tuple(tup) = &local.pat else {
        return None;
    };
    if tup.elems.len() != 2 {
        return None;
    }
    let syn::Pat::Ident(data) = &tup.elems[0] else {
        return None;
    };
    let syn::Pat::Ident(advance) = &tup.elems[1] else {
        return None;
    };
    if data.ident != "data" || advance.ident != "advance" {
        return None;
    }
    Some(&local.init.as_ref()?.expr)
}

fn push_if_chain(expr: &Expr) -> Option<(&syn::ExprIf, &syn::ExprIf, &syn::ExprIf, &Block)> {
    let Expr::If(direct) = peel_paren(expr) else {
        return None;
    };
    let (_, else1) = direct.else_branch.as_ref()?;
    let Expr::If(push1) = peel_paren(else1) else {
        return None;
    };
    let (_, else2) = push1.else_branch.as_ref()?;
    let Expr::If(push2) = peel_paren(else2) else {
        return None;
    };
    let (_, tail) = push2.else_branch.as_ref()?;
    let Expr::Block(block) = peel_paren(tail) else {
        return None;
    };
    Some((direct, push1, push2, &block.block))
}

fn is_opcode_le(expr: &Expr, bound: i64) -> bool {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Le(_))
        && path_is(&bin.left, "opcode")
        && lit_i64(&bin.right) == Some(bound)
}

fn is_opcode_eq(expr: &Expr, name: &str) -> bool {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Eq(_)) && path_is(&bin.left, "opcode") && path_is(&bin.right, name)
}

fn direct_arm(block: &Block) -> Option<i64> {
    let stmts = &block.stmts;
    if stmts.len() != 3 || !is_cast_let(stmts.first()?, "len", "opcode") {
        return None;
    }
    let cond = none_if(stmts.get(1)?)?;
    if !is_i_plus_k_plus_len_gt(cond, 1) {
        return None;
    }
    let (start, end, addend) = push_tuple(stmts.get(2)?)?;
    if !is_i_plus(start, 1) || !is_i_plus_k_plus_len(end, 1) {
        return None;
    }
    Some(addend)
}

fn sized_arm(block: &Block, prefix: i64, payload_at: i64) -> Option<i64> {
    let stmts = &block.stmts;
    if stmts.len() != 4 {
        return None;
    }
    let header = none_if(stmts.first()?)?;
    if !is_i_plus_ge_len(header, prefix) || !is_index_len(stmts.get(1)?, prefix) {
        return None;
    }
    let bound = none_if(stmts.get(2)?)?;
    if !is_i_plus_k_plus_len_gt(bound, payload_at) {
        return None;
    }
    let (start, end, addend) = push_tuple(stmts.get(3)?)?;
    if !is_i_plus(start, payload_at) || !is_i_plus_k_plus_len(end, payload_at) {
        return None;
    }
    Some(addend)
}

fn push2_arm(block: &Block) -> Option<i64> {
    let stmts = &block.stmts;
    if stmts.len() != 4 {
        return None;
    }
    let header = none_if(stmts.first()?)?;
    if !is_i_plus_ge_len(header, 2) || !is_le_bytes(stmts.get(1)?, 2) {
        return None;
    }
    let bound = none_if(stmts.get(2)?)?;
    if !is_i_plus_k_plus_len_gt(bound, 3) {
        return None;
    }
    let (start, end, addend) = push_tuple(stmts.get(3)?)?;
    if !is_i_plus(start, 3) || !is_i_plus_k_plus_len(end, 3) {
        return None;
    }
    Some(addend)
}

fn wide_arm(block: &Block) -> Option<i64> {
    let stmts = &block.stmts;
    if stmts.len() != 7 {
        return None;
    }
    let header = none_if(stmts.first()?)?;
    if !is_i_plus_ge_len(header, 4) || !is_le_bytes(stmts.get(1)?, 4) {
        return None;
    }
    if !is_sat_add(stmts.get(2)?, "data_start", true, "i", "5") {
        return None;
    }
    if !is_sat_add(stmts.get(3)?, "data_end", false, "data_start", "len") {
        return None;
    }
    let addend = sat_addend(stmts.get(4)?)?;
    let guard = none_if(stmts.get(5)?)?;
    if !is_wide_guard(guard, addend) {
        return None;
    }
    let (start, end, tail) = push_tuple(stmts.get(6)?)?;
    if !path_is(start, "data_start")
        || !path_is(end, "data_end")
        || tail != 0
        || !path_is_advance_tail(stmts.get(6)?)
    {
        return None;
    }
    Some(addend)
}

fn path_is_advance_tail(stmt: &Stmt) -> bool {
    let Stmt::Expr(expr, _) = stmt else {
        return false;
    };
    let Expr::Tuple(tup) = peel_paren(expr) else {
        return false;
    };
    tup.elems.len() == 2 && path_is(&tup.elems[1], "advance")
}

fn none_if(stmt: &Stmt) -> Option<&Expr> {
    let Stmt::Expr(expr, _) = stmt else {
        return None;
    };
    let Expr::If(iff) = peel_paren(expr) else {
        return None;
    };
    if iff.else_branch.is_some() || iff.then_branch.stmts.len() != 1 {
        return None;
    }
    is_return_none(&iff.then_branch.stmts[0]).then_some(&iff.cond)
}

fn is_return_none(stmt: &Stmt) -> bool {
    let Stmt::Expr(Expr::Return(ret), _) = stmt else {
        return false;
    };
    let Some(expr) = ret.expr.as_deref() else {
        return false;
    };
    let Expr::Call(ok) = peel_paren(expr) else {
        return false;
    };
    call_ends(&ok.func, "Ok") && ok.args.len() == 1 && path_is(&ok.args[0], "None")
}

fn is_script_len(expr: &Expr) -> bool {
    let Expr::MethodCall(call) = peel_paren(expr) else {
        return false;
    };
    call.method == "len" && call.args.is_empty() && path_is(&call.receiver, "script")
}

fn is_i_plus(expr: &Expr, k: i64) -> bool {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Add(_))
        && path_is(&bin.left, "i")
        && lit_i64(&bin.right) == Some(k)
}

fn is_i_plus_k_plus_len(expr: &Expr, k: i64) -> bool {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Add(_)) && is_i_plus(&bin.left, k) && path_is(&bin.right, "len")
}

fn is_i_plus_k_plus_len_gt(expr: &Expr, k: i64) -> bool {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Gt(_))
        && is_i_plus_k_plus_len(&bin.left, k)
        && is_script_len(&bin.right)
}

fn is_i_plus_ge_len(expr: &Expr, k: i64) -> bool {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Ge(_)) && is_i_plus(&bin.left, k) && is_script_len(&bin.right)
}

fn is_index_len(stmt: &Stmt, offset: i64) -> bool {
    let Some(init) = let_named(stmt, "len") else {
        return false;
    };
    let Expr::Cast(cast) = peel_paren(init) else {
        return false;
    };
    let Expr::Index(index) = peel_paren(&cast.expr) else {
        return false;
    };
    path_is(&index.expr, "script") && is_i_plus(&index.index, offset)
}

fn is_le_bytes(stmt: &Stmt, width: usize) -> bool {
    let Some(init) = let_named(stmt, "len") else {
        return false;
    };
    let Expr::Cast(cast) = peel_paren(init) else {
        return false;
    };
    let Expr::Call(call) = peel_paren(&cast.expr) else {
        return false;
    };
    if !call_ends(&call.func, "from_le_bytes") || call.args.len() != 1 {
        return false;
    }
    let Expr::Array(arr) = peel_paren(&call.args[0]) else {
        return false;
    };
    arr.elems.len() == width
        && arr
            .elems
            .iter()
            .enumerate()
            .all(|(n, elem)| is_script_at(elem, (n as i64) + 1))
}

fn is_script_at(expr: &Expr, offset: i64) -> bool {
    let Expr::Index(index) = peel_paren(expr) else {
        return false;
    };
    path_is(&index.expr, "script") && is_i_plus(&index.index, offset)
}

fn is_sat_add(stmt: &Stmt, name: &str, lit_arg: bool, recv: &str, arg: &str) -> bool {
    let Some(init) = let_named(stmt, name) else {
        return false;
    };
    let Expr::MethodCall(call) = peel_paren(init) else {
        return false;
    };
    if call.method != "saturating_add" || call.args.len() != 1 {
        return false;
    }
    let recv_ok = path_is(&call.receiver, recv);
    let arg_ok = if lit_arg {
        lit_i64(&call.args[0]) == Some(arg.parse().unwrap_or(-1))
    } else {
        path_is(&call.args[0], arg)
    };
    recv_ok && arg_ok
}

fn sat_addend(stmt: &Stmt) -> Option<i64> {
    let init = let_named(stmt, "advance")?;
    let Expr::MethodCall(call) = peel_paren(init) else {
        return None;
    };
    if call.method != "saturating_add" || call.args.len() != 1 || !path_is(&call.args[0], "len") {
        return None;
    }
    lit_i64(&call.receiver)
}

fn is_wide_guard(expr: &Expr, addend: i64) -> bool {
    let Expr::Binary(outer) = peel_paren(expr) else {
        return false;
    };
    if !matches!(outer.op, syn::BinOp::Or(_)) {
        return false;
    }
    let Expr::Binary(inner) = peel_paren(&outer.left) else {
        return false;
    };
    matches!(inner.op, syn::BinOp::Or(_))
        && is_advance_lt(&inner.left, addend)
        && is_end_gt_script(&inner.right)
        && is_end_before_start(&outer.right)
}

fn is_advance_lt(expr: &Expr, addend: i64) -> bool {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Lt(_))
        && path_is(&bin.left, "advance")
        && lit_i64(&bin.right) == Some(addend)
}

fn is_end_gt_script(expr: &Expr) -> bool {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Gt(_))
        && path_is(&bin.left, "data_end")
        && is_script_len(&bin.right)
}

fn is_end_before_start(expr: &Expr) -> bool {
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Lt(_))
        && path_is(&bin.left, "data_end")
        && path_is(&bin.right, "data_start")
}

fn push_tuple(stmt: &Stmt) -> Option<(&Expr, &Expr, i64)> {
    let Stmt::Expr(expr, _) = stmt else {
        return None;
    };
    let Expr::Tuple(tup) = peel_paren(expr) else {
        return None;
    };
    if tup.elems.len() != 2 {
        return None;
    }
    let (start, end) = script_range(&tup.elems[0])?;
    let addend = if path_is(&tup.elems[1], "len") || path_is(&tup.elems[1], "advance") {
        0
    } else {
        let Expr::Binary(bin) = peel_paren(&tup.elems[1]) else {
            return None;
        };
        if !matches!(bin.op, syn::BinOp::Add(_)) || !path_is(&bin.right, "len") {
            return None;
        }
        lit_i64(&bin.left)?
    };
    Some((start, end, addend))
}

fn script_range(expr: &Expr) -> Option<(&Expr, &Expr)> {
    let Expr::Reference(refer) = peel_paren(expr) else {
        return None;
    };
    let Expr::Index(index) = peel_paren(&refer.expr) else {
        return None;
    };
    if !path_is(&index.expr, "script") {
        return None;
    }
    let Expr::Range(range) = peel_paren(&index.index) else {
        return None;
    };
    if !matches!(range.limits, syn::RangeLimits::HalfOpen(_)) {
        return None;
    }
    Some((range.start.as_deref()?, range.end.as_deref()?))
}

fn is_element_limit(stmt: &Stmt) -> bool {
    let Stmt::Expr(expr, _) = stmt else {
        return false;
    };
    let Expr::If(iff) = peel_paren(expr) else {
        return false;
    };
    if iff.else_branch.is_some() || iff.then_branch.stmts.len() != 1 {
        return false;
    }
    let Expr::Binary(bin) = peel_paren(&iff.cond) else {
        return false;
    };
    let Expr::MethodCall(call) = peel_paren(&bin.left) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::Gt(_))
        && call.method == "len"
        && call.args.is_empty()
        && path_is(&call.receiver, "data")
        && path_ends(peel_paren(&bin.right), "MAX_SCRIPT_ELEMENT_SIZE")
        && is_push_size_err(&iff.then_branch.stmts[0])
}

fn is_push_size_err(stmt: &Stmt) -> bool {
    let Stmt::Expr(Expr::Return(ret), _) = stmt else {
        return false;
    };
    let Some(expr) = ret.expr.as_deref() else {
        return false;
    };
    let Expr::Call(err) = peel_paren(expr) else {
        return false;
    };
    if !call_ends(&err.func, "Err") || err.args.len() != 1 {
        return false;
    }
    let Expr::Struct(item) = peel_paren(&err.args[0]) else {
        return false;
    };
    path_to_string(&item.path).ends_with("ScriptErrorWithCode")
        && item.fields.iter().any(|field| {
            matches!(&field.member, syn::Member::Named(name) if name == "code")
                && path_ends(peel_paren(&field.expr), "PushSize")
        })
}

fn is_minimal_reject(stmt: &Stmt) -> bool {
    let Stmt::Expr(expr, _) = stmt else {
        return false;
    };
    let Expr::If(iff) = peel_paren(expr) else {
        return false;
    };
    iff.else_branch.is_none()
        && iff.then_branch.stmts.len() == 1
        && is_return_none(&iff.then_branch.stmts[0])
        && minimal_cond(&iff.cond)
}

fn minimal_cond(expr: &Expr) -> bool {
    let Expr::Binary(outer) = peel_paren(expr) else {
        return false;
    };
    if !matches!(outer.op, syn::BinOp::And(_)) {
        return false;
    }
    let Expr::Binary(inner) = peel_paren(&outer.left) else {
        return false;
    };
    matches!(inner.op, syn::BinOp::And(_))
        && is_not_path(&inner.left, "in_false_branch")
        && flags_bit_set(&inner.right)
        && is_not_minimal_call(&outer.right)
}

fn flags_bit_set(expr: &Expr) -> bool {
    let Expr::Binary(cmp) = peel_paren(expr) else {
        return false;
    };
    if !matches!(cmp.op, syn::BinOp::Ne(_)) || lit_i64(&cmp.right) != Some(0) {
        return false;
    }
    let Expr::Binary(bit) = peel_paren(&cmp.left) else {
        return false;
    };
    matches!(bit.op, syn::BinOp::BitAnd(_))
        && path_is(&bit.left, "flags")
        && path_ends(peel_paren(&bit.right), "SCRIPT_VERIFY_MINIMALDATA")
}

fn is_not_minimal_call(expr: &Expr) -> bool {
    let Expr::Unary(unary) = peel_paren(expr) else {
        return false;
    };
    if !matches!(unary.op, syn::UnOp::Not(_)) {
        return false;
    }
    let Expr::Call(call) = peel_paren(&unary.expr) else {
        return false;
    };
    call_ends(&call.func, "push_encoding_is_minimal")
        && call.args.len() == 2
        && path_is(&call.args[0], "opcode")
        && path_is(&call.args[1], "data")
}

fn is_false_branch_push(stmt: &Stmt) -> bool {
    let Stmt::Expr(expr, _) = stmt else {
        return false;
    };
    let Expr::If(iff) = peel_paren(expr) else {
        return false;
    };
    if iff.else_branch.is_some()
        || !is_not_path(&iff.cond, "in_false_branch")
        || iff.then_branch.stmts.len() != 1
    {
        return false;
    }
    let Stmt::Expr(body, _) = &iff.then_branch.stmts[0] else {
        return false;
    };
    let Expr::MethodCall(call) = peel_paren(body) else {
        return false;
    };
    if call.method != "push" || call.args.len() != 1 || !path_is(&call.receiver, "stack") {
        return false;
    }
    let Expr::Call(wrap) = peel_paren(&call.args[0]) else {
        return false;
    };
    call_ends(&wrap.func, "to_stack_element")
        && wrap.args.len() == 1
        && path_is(&wrap.args[0], "data")
}

fn is_some_advance(stmt: &Stmt) -> bool {
    let Stmt::Expr(expr, None) = stmt else {
        return false;
    };
    let Expr::Call(ok) = peel_paren(expr) else {
        return false;
    };
    if !call_ends(&ok.func, "Ok") || ok.args.len() != 1 {
        return false;
    }
    let Expr::Call(some) = peel_paren(&ok.args[0]) else {
        return false;
    };
    call_ends(&some.func, "Some") && some.args.len() == 1 && path_is(&some.args[0], "advance")
}

struct Sigops {
    max_keys: i64,
    legacy_init: i64,
    tap_init: i64,
    checksig: i64,
    tap: i64,
}

fn parse_sigops(block: &Block) -> Option<Sigops> {
    if !crate::parser::spec_expr::consensus_workspace_present() {
        return None;
    }
    let stmts = &block.stmts;
    if stmts.len() != 10 {
        return None;
    }
    let max_keys = const_u32(stmts.first()?, "MAX_PUBKEYS_PER_MULTISIG")?;
    let legacy_init = zero_let(stmts.get(1)?, "count")?;
    if !none_let(stmts.get(2)?, "last_opcode") || zero_let(stmts.get(3)?, "i") != Some(0) {
        return None;
    }
    let checksig = legacy_scan(stmts.get(4)?)?;
    if !is_path_tail(stmts.get(5)?, "count") {
        return None;
    }
    let tap_init = zero_let(stmts.get(6)?, "count")?;
    if zero_let(stmts.get(7)?, "i") != Some(0) {
        return None;
    }
    let tap = tap_scan(stmts.get(8)?)?;
    if !is_path_tail(stmts.get(9)?, "count") {
        return None;
    }
    Some(Sigops {
        max_keys,
        legacy_init,
        tap_init,
        checksig,
        tap,
    })
}

fn const_u32(stmt: &Stmt, name: &str) -> Option<i64> {
    let Stmt::Item(syn::Item::Const(item)) = stmt else {
        return None;
    };
    (item.ident == name)
        .then_some(())
        .and_then(|()| lit_i64(&item.expr))
}

fn typed_local(stmt: &Stmt) -> Option<(String, &Expr)> {
    let Stmt::Local(local) = stmt else {
        return None;
    };
    let name = match &local.pat {
        syn::Pat::Ident(pat) => pat.ident.to_string(),
        syn::Pat::Type(ty) => {
            let syn::Pat::Ident(pat) = &*ty.pat else {
                return None;
            };
            pat.ident.to_string()
        }
        _ => return None,
    };
    Some((name, &local.init.as_ref()?.expr))
}

fn zero_let(stmt: &Stmt, name: &str) -> Option<i64> {
    let (got, init) = typed_local(stmt)?;
    (got == name).then_some(lit_i64(init))?
}

fn none_let(stmt: &Stmt, name: &str) -> bool {
    typed_local(stmt).is_some_and(|(got, init)| got == name && path_is(init, "None"))
}

fn is_path_tail(stmt: &Stmt, name: &str) -> bool {
    let Stmt::Expr(expr, _) = stmt else {
        return false;
    };
    path_is(expr, name)
}

fn script_while(stmt: &Stmt) -> Option<&Block> {
    let Stmt::Expr(expr, _) = stmt else {
        return None;
    };
    let Expr::While(lp) = peel_paren(expr) else {
        return None;
    };
    let Expr::Binary(bin) = peel_paren(&lp.cond) else {
        return None;
    };
    if !matches!(bin.op, syn::BinOp::Lt(_))
        || !path_is(&bin.left, "i")
        || !is_script_len(&bin.right)
    {
        return None;
    }
    Some(&lp.body)
}

fn is_opcode_index(stmt: &Stmt) -> bool {
    let Some((name, init)) = typed_local(stmt) else {
        return false;
    };
    if name != "opcode" {
        return false;
    }
    let Expr::Index(index) = peel_paren(init) else {
        return false;
    };
    path_is(&index.expr, "script") && path_is(&index.index, "i")
}

fn legacy_scan(stmt: &Stmt) -> Option<i64> {
    let body = script_while(stmt)?;
    let stmts = &body.stmts;
    if stmts.len() != 5 || !is_opcode_index(stmts.first()?) || !legacy_pushes(stmts.get(1)?) {
        return None;
    }
    let addend = legacy_count(stmts.get(2)?)?;
    (is_prev_assign(stmts.get(3)?) && is_step(stmts.get(4)?, 1)).then_some(addend)
}

fn tap_scan(stmt: &Stmt) -> Option<i64> {
    let body = script_while(stmt)?;
    let stmts = &body.stmts;
    if stmts.len() != 4 || !is_opcode_index(stmts.first()?) || !tap_pushes(stmts.get(1)?) {
        return None;
    }
    let addend = tap_count(stmts.get(2)?)?;
    is_step(stmts.get(3)?, 1).then_some(addend)
}

fn legacy_pushes(stmt: &Stmt) -> bool {
    let Some(iff) = if_expr(stmt) else {
        return false;
    };
    is_direct_cond(&iff.cond)
        && direct_push(&iff.then_branch, true)
        && push_arm(
            iff.else_branch.as_ref().map(|(_, e)| &**e),
            "OP_PUSHDATA1",
            1,
            2,
        )
        && push_arm(next_else(iff), "OP_PUSHDATA2", 2, 3)
        && push_arm(last_else(iff), "OP_PUSHDATA4", 4, 5)
}

fn tap_pushes(stmt: &Stmt) -> bool {
    let Some(iff) = if_expr(stmt) else {
        return false;
    };
    is_direct_cond(&iff.cond)
        && direct_push(&iff.then_branch, false)
        && push_arm_plain(
            iff.else_branch.as_ref().map(|(_, e)| &**e),
            "OP_PUSHDATA1",
            1,
            2,
        )
        && push_arm_plain(next_else(iff), "OP_PUSHDATA2", 2, 3)
        && push_arm_plain(last_else(iff), "OP_PUSHDATA4", 4, 5)
}

fn is_direct_cond(expr: &Expr) -> bool {
    let Expr::Binary(and) = peel_paren(expr) else {
        return false;
    };
    if !matches!(and.op, syn::BinOp::And(_)) {
        return false;
    }
    let Expr::Binary(gt) = peel_paren(&and.left) else {
        return false;
    };
    let Expr::Binary(lt) = peel_paren(&and.right) else {
        return false;
    };
    matches!(gt.op, syn::BinOp::Gt(_))
        && path_is(&gt.left, "opcode")
        && lit_i64(&gt.right) == Some(0)
        && matches!(lt.op, syn::BinOp::Lt(_))
        && path_is(&lt.left, "opcode")
        && path_is(&lt.right, "OP_PUSHDATA1")
}

fn if_expr(stmt: &Stmt) -> Option<&syn::ExprIf> {
    let Stmt::Expr(expr, _) = stmt else {
        return None;
    };
    let Expr::If(iff) = peel_paren(expr) else {
        return None;
    };
    Some(iff)
}

fn next_else(iff: &syn::ExprIf) -> Option<&Expr> {
    let (_, else_expr) = iff.else_branch.as_ref()?;
    let Expr::If(inner) = peel_paren(else_expr) else {
        return None;
    };
    inner.else_branch.as_ref().map(|(_, expr)| &**expr)
}

fn last_else(iff: &syn::ExprIf) -> Option<&Expr> {
    let mid = next_else(iff)?;
    let Expr::If(inner) = peel_paren(mid) else {
        return None;
    };
    inner.else_branch.as_ref().map(|(_, expr)| &**expr)
}

fn direct_push(block: &Block, records: bool) -> bool {
    let stmts = &block.stmts;
    if records {
        stmts.len() == 4
            && is_len_cast(stmts.first(), "opcode")
            && is_some_assign(stmts.get(1), "last_opcode", "opcode")
            && is_add_step(stmts.get(2), 1)
            && sig_continue(stmts.get(3))
    } else {
        stmts.len() == 3
            && is_len_cast(stmts.first(), "opcode")
            && is_add_step(stmts.get(1), 1)
            && sig_continue(stmts.get(2))
    }
}

fn push_arm(expr: Option<&Expr>, opcode: &str, header: i64, advance: i64) -> bool {
    let Some(Expr::If(iff)) = expr.map(peel_paren) else {
        return false;
    };
    is_opcode_eq(&iff.cond, opcode) && recorded_push(&iff.then_branch, header, advance)
}

fn push_arm_plain(expr: Option<&Expr>, opcode: &str, header: i64, advance: i64) -> bool {
    let Some(Expr::If(iff)) = expr.map(peel_paren) else {
        return false;
    };
    is_opcode_eq(&iff.cond, opcode) && plain_push(&iff.then_branch, header, advance)
}

fn recorded_push(block: &Block, header: i64, advance: i64) -> bool {
    let stmts = &block.stmts;
    stmts.len() == 5
        && is_header_break(stmts.first(), header)
        && is_push_len(stmts.get(1), header)
        && is_some_assign(stmts.get(2), "last_opcode", "opcode")
        && is_add_step(stmts.get(3), advance)
        && sig_continue(stmts.get(4))
}

fn plain_push(block: &Block, header: i64, advance: i64) -> bool {
    let stmts = &block.stmts;
    stmts.len() == 4
        && is_header_break(stmts.first(), header)
        && is_push_len(stmts.get(1), header)
        && is_add_step(stmts.get(2), advance)
        && sig_continue(stmts.get(3))
}

fn is_len_cast(stmt: Option<&Stmt>, src: &str) -> bool {
    let Some(stmt) = stmt else {
        return false;
    };
    let Some((name, init)) = typed_local(stmt) else {
        return false;
    };
    if name != "len" {
        return false;
    }
    let Expr::Cast(cast) = peel_paren(init) else {
        return false;
    };
    path_is(&cast.expr, src)
}

fn is_some_assign(stmt: Option<&Stmt>, name: &str, arg: &str) -> bool {
    let Some(Stmt::Expr(expr, _)) = stmt else {
        return false;
    };
    let Expr::Assign(assign) = peel_paren(expr) else {
        return false;
    };
    if !path_is(&assign.left, name) {
        return false;
    }
    let Expr::Call(some) = peel_paren(&assign.right) else {
        return false;
    };
    call_ends(&some.func, "Some") && some.args.len() == 1 && path_is(&some.args[0], arg)
}

fn is_add_step(stmt: Option<&Stmt>, width: i64) -> bool {
    let Some(stmt) = stmt else {
        return false;
    };
    let Stmt::Expr(expr, _) = stmt else {
        return false;
    };
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    if !matches!(bin.op, syn::BinOp::AddAssign(_)) || !path_is(&bin.left, "i") {
        return false;
    }
    let Expr::Binary(add) = peel_paren(&bin.right) else {
        return false;
    };
    matches!(add.op, syn::BinOp::Add(_))
        && lit_i64(&add.left) == Some(width)
        && path_is(&add.right, "len")
}

fn is_step(stmt: &Stmt, width: i64) -> bool {
    let Stmt::Expr(expr, _) = stmt else {
        return false;
    };
    let Expr::Binary(bin) = peel_paren(expr) else {
        return false;
    };
    matches!(bin.op, syn::BinOp::AddAssign(_))
        && path_is(&bin.left, "i")
        && lit_i64(&bin.right) == Some(width)
}

fn sig_continue(stmt: Option<&Stmt>) -> bool {
    matches!(stmt, Some(Stmt::Expr(Expr::Continue(_), _)))
}

fn is_header_break(stmt: Option<&Stmt>, header: i64) -> bool {
    let Some(iff) = stmt.and_then(if_expr) else {
        return false;
    };
    iff.else_branch.is_none()
        && iff.then_branch.stmts.len() == 1
        && matches!(
            iff.then_branch.stmts.first(),
            Some(Stmt::Expr(Expr::Break(_), _))
        )
        && is_i_plus_ge_len(&iff.cond, header)
}

fn is_push_len(stmt: Option<&Stmt>, header: i64) -> bool {
    if header == 1 {
        return is_script_cast(stmt, 1);
    }
    let Some(stmt) = stmt else {
        return false;
    };
    let Some((name, init)) = typed_local(stmt) else {
        return false;
    };
    if name != "len" {
        return false;
    }
    let Expr::Cast(cast) = peel_paren(init) else {
        return false;
    };
    let Expr::Call(call) = peel_paren(&cast.expr) else {
        return false;
    };
    let width = if header == 2 {
        2
    } else if header == 4 {
        4
    } else {
        return false;
    };
    call_ends(&call.func, "from_le_bytes")
        && call.args.len() == 1
        && is_le_array(&call.args[0], width)
}

fn is_script_cast(stmt: Option<&Stmt>, offset: i64) -> bool {
    let Some(stmt) = stmt else {
        return false;
    };
    let Some((name, init)) = typed_local(stmt) else {
        return false;
    };
    if name != "len" {
        return false;
    }
    let Expr::Cast(cast) = peel_paren(init) else {
        return false;
    };
    let Expr::Index(index) = peel_paren(&cast.expr) else {
        return false;
    };
    path_is(&index.expr, "script") && is_i_plus(&index.index, offset)
}

fn is_le_array(expr: &Expr, width: usize) -> bool {
    let Expr::Array(arr) = peel_paren(expr) else {
        return false;
    };
    arr.elems.len() == width
        && arr
            .elems
            .iter()
            .enumerate()
            .all(|(n, elem)| is_script_at(elem, (n as i64) + 1))
}

fn is_prev_assign(stmt: &Stmt) -> bool {
    is_some_assign(Some(stmt), "last_opcode", "opcode")
}

fn legacy_count(stmt: &Stmt) -> Option<i64> {
    let iff = if_expr(stmt)?;
    let addend = sat_lit(&iff.then_branch)?;
    if !checksig_or(&iff.cond, false) {
        return None;
    }
    let (_, else_expr) = iff.else_branch.as_ref()?;
    let Expr::If(multi) = peel_paren(else_expr) else {
        return None;
    };
    if !multisig_or(&multi.cond)
        || multi.else_branch.is_some()
        || !multisig_body(&multi.then_branch)
    {
        return None;
    }
    Some(addend)
}

fn tap_count(stmt: &Stmt) -> Option<i64> {
    let iff = if_expr(stmt)?;
    if iff.else_branch.is_some() || !checksig_or(&iff.cond, true) {
        return None;
    }
    sat_lit(&iff.then_branch)
}

fn checksig_or(expr: &Expr, with_add: bool) -> bool {
    let Expr::Binary(or) = peel_paren(expr) else {
        return false;
    };
    if !matches!(or.op, syn::BinOp::Or(_)) {
        return false;
    }
    if with_add {
        let Expr::Binary(inner) = peel_paren(&or.left) else {
            return false;
        };
        return matches!(inner.op, syn::BinOp::Or(_))
            && is_opcode_eq(&inner.left, "OP_CHECKSIG")
            && is_opcode_eq(&inner.right, "OP_CHECKSIGVERIFY")
            && is_opcode_eq(&or.right, "OP_CHECKSIGADD");
    }
    is_opcode_eq(&or.left, "OP_CHECKSIG") && is_opcode_eq(&or.right, "OP_CHECKSIGVERIFY")
}

fn multisig_or(expr: &Expr) -> bool {
    let Expr::Binary(or) = peel_paren(expr) else {
        return false;
    };
    matches!(or.op, syn::BinOp::Or(_))
        && is_opcode_eq(&or.left, "OP_CHECKMULTISIG")
        && is_opcode_eq(&or.right, "OP_CHECKMULTISIGVERIFY")
}

fn sat_lit(block: &Block) -> Option<i64> {
    if block.stmts.len() != 1 {
        return None;
    }
    sat_arg(block.stmts.first()?, true)
}

fn sat_arg(stmt: &Stmt, literal: bool) -> Option<i64> {
    let Stmt::Expr(expr, _) = stmt else {
        return None;
    };
    let Expr::Assign(assign) = peel_paren(expr) else {
        return None;
    };
    if !path_is(&assign.left, "count") {
        return None;
    }
    let Expr::MethodCall(call) = peel_paren(&assign.right) else {
        return None;
    };
    if call.method != "saturating_add" || call.args.len() != 1 || !path_is(&call.receiver, "count")
    {
        return None;
    }
    if literal {
        lit_i64(&call.args[0])
    } else if path_is(&call.args[0], "MAX_PUBKEYS_PER_MULTISIG") || path_is(&call.args[0], "n") {
        Some(0)
    } else {
        None
    }
}

fn multisig_body(block: &Block) -> bool {
    let Some(iff) = block.stmts.first().and_then(if_expr) else {
        return false;
    };
    if block.stmts.len() != 1 || !path_is(&iff.cond, "accurate") {
        return false;
    }
    let Some((_, rough)) = iff.else_branch.as_ref() else {
        return false;
    };
    let Expr::Block(else_block) = peel_paren(rough) else {
        return false;
    };
    else_block
        .block
        .stmts
        .first()
        .and_then(|stmt| sat_arg(stmt, false))
        .is_some()
        && accurate_arm(&iff.then_branch)
}

fn accurate_arm(block: &Block) -> bool {
    let Some(iff) = block.stmts.first().and_then(if_expr) else {
        return false;
    };
    if block.stmts.len() != 1 {
        return false;
    }
    let Expr::Let(binder) = peel_paren(&iff.cond) else {
        return false;
    };
    let syn::Pat::TupleStruct(pat) = &*binder.pat else {
        return false;
    };
    if path_to_string(&pat.path) != "Some" || pat.elems.len() != 1 {
        return false;
    }
    let syn::Pat::Ident(prev) = &pat.elems[0] else {
        return false;
    };
    if prev.ident != "prev_op" || !path_is(&binder.expr, "last_opcode") {
        return false;
    }
    let Some((_, missing)) = iff.else_branch.as_ref() else {
        return false;
    };
    let Expr::Block(none_arm) = peel_paren(missing) else {
        return false;
    };
    none_arm
        .block
        .stmts
        .first()
        .and_then(|stmt| sat_arg(stmt, false))
        .is_some()
        && decoded_range(&iff.then_branch)
}

fn decoded_range(block: &Block) -> bool {
    let Some(iff) = block.stmts.first().and_then(if_expr) else {
        return false;
    };
    if block.stmts.len() != 1 || !is_opcode_window(&iff.cond) {
        return false;
    }
    let Some((_, other)) = iff.else_branch.as_ref() else {
        return false;
    };
    let Expr::Block(fallback) = peel_paren(other) else {
        return false;
    };
    iff.then_branch.stmts.len() == 2
        && is_decoded_n(iff.then_branch.stmts.first())
        && iff
            .then_branch
            .stmts
            .get(1)
            .and_then(|stmt| sat_arg(stmt, false))
            .is_some()
        && fallback
            .block
            .stmts
            .first()
            .and_then(|stmt| sat_arg(stmt, false))
            .is_some()
}

fn is_decoded_n(stmt: Option<&Stmt>) -> bool {
    let Some(stmt) = stmt else {
        return false;
    };
    let Some((name, init)) = typed_local(stmt) else {
        return false;
    };
    if name != "n" {
        return false;
    }
    let Expr::Cast(cast) = peel_paren(init) else {
        return false;
    };
    let Expr::Binary(add) = peel_paren(&cast.expr) else {
        return false;
    };
    if !matches!(add.op, syn::BinOp::Add(_)) || lit_i64(&add.right) != Some(1) {
        return false;
    }
    let Expr::Binary(sub) = peel_paren(&add.left) else {
        return false;
    };
    matches!(sub.op, syn::BinOp::Sub(_))
        && path_is(&sub.left, "prev_op")
        && path_is(&sub.right, "OP_1")
}

fn is_opcode_window(expr: &Expr) -> bool {
    let Expr::MethodCall(call) = peel_paren(expr) else {
        return false;
    };
    if call.method != "contains" || call.args.len() != 1 || !path_is(&call.args[0], "prev_op") {
        return false;
    }
    let Expr::Range(range) = peel_paren(&call.receiver) else {
        return false;
    };
    matches!(range.limits, syn::RangeLimits::Closed(_))
        && range
            .start
            .as_deref()
            .is_some_and(|start| path_is(start, "OP_1"))
        && range
            .end
            .as_deref()
            .is_some_and(|end| path_is(end, "OP_16"))
}

struct CheckTx {
    max_inputs: i64,
    max_outputs: i64,
    max_money: i64,
    max_weight: i64,
    scale: i64,
    coin_lo: i64,
    coin_hi: i64,
    output_neg: bool,
    total_neg: bool,
    full_prevout: bool,
}

#[derive(Default)]
struct CheckFind {
    output_neg: bool,
    total_neg: bool,
    saw_over: bool,
    saw_empty_in: bool,
    saw_empty_out: bool,
    saw_max_in: bool,
    saw_max_out: bool,
    saw_weight: bool,
    saw_add: bool,
    saw_size: bool,
    saw_coinbase: bool,
    saw_hash: bool,
    saw_index: bool,
    saw_fast: bool,
    saw_none: bool,
    saw_valid: bool,
    saw_insert: bool,
    full_prevout: Option<bool>,
    coin_lo: Option<i64>,
    coin_hi: Option<i64>,
    ranges: u32,
    range_conflict: bool,
    scale: Option<i64>,
}

fn parse_check_tx(block: &Block) -> Option<CheckTx> {
    if !crate::parser::spec_expr::consensus_workspace_present() {
        return None;
    }
    let mut found = CheckFind::default();
    syn::visit::visit_block(&mut found, block);
    if !found.saw_over
        || !found.saw_empty_in
        || !found.saw_empty_out
        || !found.saw_max_in
        || !found.saw_max_out
        || !found.saw_weight
        || !found.saw_add
        || !found.saw_size
        || !found.saw_coinbase
        || !found.saw_hash
        || !found.saw_index
        || !found.saw_fast
        || !found.saw_none
        || !found.saw_valid
        || !found.saw_insert
        || found.full_prevout.is_none()
        || found.ranges < 2
        || found.range_conflict
    {
        return None;
    }
    Some(CheckTx {
        max_inputs: crate::parser::spec_expr::impl_u64("MAX_INPUTS") as i64,
        max_outputs: crate::parser::spec_expr::impl_u64("MAX_OUTPUTS") as i64,
        max_money: crate::parser::spec_expr::impl_u64("MAX_MONEY") as i64,
        max_weight: crate::parser::spec_expr::impl_u64("MAX_BLOCK_WEIGHT") as i64,
        scale: found.scale?,
        coin_lo: found.coin_lo?,
        coin_hi: found.coin_hi?,
        output_neg: found.output_neg,
        total_neg: found.total_neg,
        full_prevout: found.full_prevout?,
    })
}

