        || !found.saw_height
        || !found.saw_utxo
        || !found.saw_tx_empty
        || !found.saw_too_many
        || !found.saw_header
        || !found.saw_bits
        || !found.saw_warp
        || !found.saw_pow
        || !found.saw_bip54_time
        || !found.saw_weight_fn
        || !found.saw_zero
        || !found.saw_double
        || !found.saw_version
        || !found.saw_bip90
