fn note_weight_rel(found: &mut WeightFind, rel: u8) {
    if found.rel.is_some_and(|prev| prev != rel) {
        found.rel_conflict = true;
    }
    found.rel = Some(rel);
}

fn note_sig_rel(found: &mut WeightFind, rel: u8) {
    if found.sig_rel.is_some_and(|prev| prev != rel) {
        found.sig_conflict = true;
    }
    found.sig_rel = Some(rel);
}

fn note_sig_range(found: &mut WeightFind, lo: i64, hi: i64) {
    if found.sig_lo.is_some_and(|prev| prev != lo) || found.sig_hi.is_some_and(|prev| prev != hi) {
        found.sig_range_conflict = true;
    }
    found.sig_lo = Some(lo);
    found.sig_hi = Some(hi);
}

fn closed_bounds(expr: &Expr) -> Option<(i64, i64)> {
    let Expr::Range(range) = peel_paren(expr) else {
        return None;
    };
    if !matches!(range.limits, syn::RangeLimits::Closed(_)) {
        return None;
    }
    let lo = lit_i64(range.start.as_deref()?)?;
    let hi = lit_i64(range.end.as_deref()?)?;
    Some((lo, hi))
}

struct TxFinality {
    fork: u8,
    checks: bool,
}

#[derive(Default)]
struct FinalityFind {
    fork: Option<u8>,
    fork_conflict: bool,
    checks: bool,
}

fn parse_tx_finality(block: &Block) -> Option<TxFinality> {
    let mut found = FinalityFind::default();
    syn::visit::visit_block(&mut found, block);
    if found.fork_conflict {
        return None;
    }
    Some(TxFinality {
        fork: found.fork?,
        checks: found.checks,
    })
}

fn note_csv_fork(found: &mut FinalityFind, fork: u8) {
    if found.fork.is_some_and(|prev| prev != fork) {
        found.fork_conflict = true;
    }
    found.fork = Some(fork);
}

impl<'ast> syn::visit::Visit<'ast> for FinalityFind {
    fn visit_expr(&mut self, expr: &'ast Expr) {
        match expr {
            Expr::Call(call) => {
                if call_ends(&call.func, "is_final_tx") {
                    self.checks = true;
                }
            }
            Expr::MethodCall(call) => {
                if call.method == "is_fork_active" {
                    if let Some(arg) = call.args.first() {
                        if contains_path_end(arg, "Bip112") {
                            note_csv_fork(self, 0);
                        } else if contains_path_end(arg, "Bip66") {
                            note_csv_fork(self, 1);
                        }
                    }
                }
            }
            _ => {}
        }
        syn::visit::visit_expr(self, expr);
    }
}

